('before','functions',16,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_worker_id text, p_started_at timestamp with time zone","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.claim_a2a_order(p_worker_id text, p_started_at timestamp with time zone)\n RETURNS SETOF public.a2a_orders\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  WITH candidate AS (\n    SELECT id\n    FROM public.a2a_orders\n    WHERE status = ''running''\n      AND started_at IS NULL\n      AND request_data IS NOT NULL\n    ORDER BY created_at, id\n    FOR UPDATE SKIP LOCKED\n    LIMIT 1\n  ), claimed AS (\n    UPDATE public.a2a_orders AS orders\n    SET started_at = p_started_at,\n        worker_id = p_worker_id,\n        updated_at = p_started_at\n    FROM candidate\n    WHERE orders.id = candidate.id\n      AND orders.status = ''running''\n      AND orders.started_at IS NULL\n    RETURNING orders.*\n  )\n  SELECT * FROM claimed;\n$function$\n","kind":"f","language":"sql","leakproof":false,"name":"claim_a2a_order","owner":"postgres","parallel":"u","result":"SETOF public.a2a_orders","returnsSet":true,"rows":"1000","schema":"public","securityDefiner":true,"settings":["search_path=public"],"source":"\n  WITH candidate AS (\n    SELECT id\n    FROM public.a2a_orders\n    WHERE status = ''running''\n      AND started_at IS NULL\n      AND request_data IS NOT NULL\n    ORDER BY created_at, id\n    FOR UPDATE SKIP LOCKED\n    LIMIT 1\n  ), claimed AS (\n    UPDATE public.a2a_orders AS orders\n    SET started_at = p_started_at,\n        worker_id = p_worker_id,\n        updated_at = p_started_at\n    FROM candidate\n    WHERE orders.id = candidate.id\n      AND orders.status = ''running''\n      AND orders.started_at IS NULL\n    RETURNING orders.*\n  )\n  SELECT * FROM