('before','functions',18,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_now bigint, p_lease_ms bigint","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.claim_gap_intent(p_now bigint, p_lease_ms bigint)\n RETURNS SETOF public.gap_intents\n LANGUAGE plpgsql\nAS $function$\ndeclare\n  v_id text;\nbegin\n  update public.gap_intents\n     set status = ''failed'',\n         last_error = coalesce(last_error, ''retry lease expired''),\n         lease_expires_at = null,\n         updated_at = now()\n   where status = ''running''\n     and lease_expires_at <= p_now\n     and attempts >= 3;\n\n  select gi.id into v_id\n    from public.gap_intents gi\n    join public.sources s on s.id = gi.source_id\n   where (\n     gi.status = ''pending''\n     or (gi.status = ''running'' and gi.lease_expires_at <= p_now)\n   )\n     and gi.attempts < 3\n     and s.active = true\n     and s.verified = true\n   order by gi.created_at asc\n   for update of gi skip locked\n   limit 1;\n\n  if v_id is null then return; end if;\n\n  return query\n  update public.gap_intents\n     set status = ''running'',\n         attempts = attempts + 1,\n         lease_expires_at = p_now + greatest(1000, p_lease_ms),\n         last_error = null,\n         updated_at = now()\n   where id = v_id\n   returning *;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"claim_gap_intent","owner":"postgres","parallel":"u","result":"SETOF public.gap_intents","returnsSet":true,"rows":"1000","schema":"public","securityDefiner":false,"settings":null,"source":"\ndeclare\n  v_id text;\nbegin\n  update public.gap_intents\n     set status = ''failed'',\n         last_error = coalesce(last_error, ''retry lease expired''),\n         lease_expires_at = null,\n         updated_at = now()\n   where status = ''running''\n     and lease_expires_at <= p_now\n     and attempts >= 3;\n\n  select gi.id into v_id\n    from public.gap_intents gi\n    join public.sources s on s.id = gi.source_id\n   where (\n     gi.status = ''pending''\n     or (gi.status = ''running'' and gi.lease_expires_at <= p_now)\n   )\n     and gi.attempts < 3\n     and s.active = true\n     and s.verified = true\n   order by gi.created_at asc\n   for update of gi skip locked\n   limit 1;\n\n  if v_id is null then return; end if;\n\n  return query\n  update public.gap_intents\n     set status = ''running'',\n         attempts = attempts + 1,\n         lease_expires_at = p_now + greatest(1000, p_lease_ms),\n         last_error = null,\n         updated_at = now()\n   where id = v_id\n   returning *;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',19,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_payer text, p_worker_id uuid","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.claim_private_research_execution(p_id text, p_payer text, p_worker_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare n integer;\nbegin\n  insert into public.private_research_executions(id,worker_id)\n  select p.id,p_worker_id from public.private_research_payment_attempts p\n  join public.private_research_intents i on i.id=p.id\n  where p.id=p_id and i.payer=lower(p_payer)\n    and p.confirmation is not null and p.settled_at is not null\n  on conflict(id) do nothing;\n  get diagnostics n = row_count;\n  return n=1;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"claim_private_research_execution","owner":"postgres","parallel":"u","result":"boolean","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=\"\""],"source":"\ndeclare n integer;\nbegin\n  insert into public.private_research_executions(id,worker_id)\n  select p.id,p_worker_id from public.private_research_payment_attempts p\n  join public.private_research_intents i on i.id=p.id\n  where p.id=p_id and i.payer=lower(p_payer)\n    and p.confirmation is not null and p.settled_at is not null\n  on conflict(id) do nothing;\n  get diagnostics n = row_count;\n  return n=1;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
