('before','functions',21,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_payer text, p_worker_id uuid, p_confirmation jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.confirm_private_creator_submission(p_id text, p_payer text, p_worker_id uuid, p_confirmation jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare original jsonb; nonce text;\nbegin\n  nonce := p_confirmation#>>''{submission,authorizationId}'';\n  select s.data into original from public.private_creator_submissions s\n  join public.private_research_intents i on i.id=s.job_id\n  where s.job_id=p_id and s.worker_id=p_worker_id and i.payer=lower(p_payer) and s.authorization_id=nonce;\n  if not found then return; end if;\n  if coalesce(p_confirmation->>''source'','''') not in (''circle-facilitator-success'',''circle-transfer-search'')\n    or ((p_confirmation->>''source'')=''circle-transfer-search'' and coalesce(p_confirmation->>''transferStatus'','''') not in (''received'',''batched'',''confirmed'',''completed''))\n    or (p_confirmation->''submission'') is distinct from (original->''submission'')\n    or coalesce(p_confirmation->>''transaction'','''') !~ ''^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$''\n  then raise exception ''creator confirmation mismatch''; end if;\n  insert into public.private_creator_confirmations(authorization_id,data) values(nonce,p_confirmation)\n  on conflict(authorization_id) do update set data=excluded.data\n  where public.private_creator_confirmations.data->>''source''=''circle-transfer-search''\n    and excluded.data->>''source''=''circle-transfer-search''\n    and public.private_creator_confirmations.data->>''transferStatus'' in (''received'',''batched'')\n    and excluded.data->>''transferStatus'' in (''confirmed'',''completed'')\n    and public.private_creator_confirmations.data->>''transaction''=excluded.data->>''transaction''\n    and public.private_creator_confirmations.data->''submission''=excluded.data->''submission'';\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"confirm_private_creator_submission","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=\"\""],"source":"\ndeclare original jsonb; nonce text;\nbegin\n  nonce := p_confirmation#>>''{submission,authorizationId}'';\n  select s.data into original from public.private_creator_submissions s\n  join public.private_research_intents i on i.id=s.job_id\n  where s.job_id=p_id and s.worker_id=p_worker_id and i.payer=lower(p_payer) and s.authorization_id=nonce;\n  if not found then return; end if;\n  if coalesce(p_confirmation->>''source'','''') not in (''circle-facilitator-success'',''circle-transfer-search'')\n    or ((p_confirmation->>''source'')=''circle-transfer-search'' and coalesce(p_confirmation->>''transferStatus'','''') not in (''received'',''batched'',''confirmed'',''completed''))\n    or (p_confirmation->''submission'') is distinct from (original->''submission'')\n    or coalesce(p_confirmation->>''transaction'','''') !~ ''^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$''\n  then raise exception ''creator confirmation mismatch''; end if;\n  insert into public.private_creator_confirmations(authorization_id,data) values(nonce,p_confirmation)\n  on conflict(authorization_id) do update set data=excluded.data\n  where public.private_creator_confirmations.data->>''source''=''circle-transfer-search''\n    and excluded.data->>''source''=''circle-transfer-search''\n    and public.private_creator_confirmations.data->>''transferStatus'' in (''received'',''batched'')\n    and excluded.data->>''transferStatus'' in (''confirmed'',''completed'')\n    and public.private_creator_confirmations.data->>''transaction''=excluded.data->>''transaction''\n    and public.private_creator_confirmations.data->''submission''=excluded.data->''submission'';\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',22,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_payer text, p_confirmation jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.confirm_private_research_payment(p_id text, p_payer text, p_confirmation jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare original jsonb;\nbegin\n  select data into original from public.private_research_intents where id=p_id and payer=lower(p_payer);\n  if not found then return; end if;\n  if jsonb_typeof(p_confirmation) is distinct from ''object''\n    or coalesce(p_confirmation->>''source'','''') not in (''circle-facilitator-success'',''circle-transfer-search'')\n    or ((p_confirmation->>''source'') = ''circle-transfer-search'' and coalesce(p_confirmation->>''transferStatus'','''') not in (''confirmed'',''completed''))\n    or ((p_confirmation->>''source'') = ''circle-facilitator-success'' and p_confirmation ? ''transferStatus'')\n    or (p_confirmation->>''network'') is distinct from (original->''requirement''->>''network'')\n    or lower(p_confirmation->>''payer'') is distinct from (original->''submission''->''payment''->''authorization''->>''from'')\n    or lower(p_confirmation->>''payee'') is distinct from (original->''submission''->''payment''->''authorization''->>''to'')\n    or (p_confirmation->>''amountMicros'') is distinct from (original->''submission''->''payment''->''authorization''->>''value'')\n    or (p_confirmation->>''authorizationId'') is distinct from (original->''submission''->''payment''->''authorization''->>''nonce'')\n    or coalesce(p_confirmation->>''transaction'','''') !~ ''^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$''\n  then raise exception ''confirmation mismatch''; end if;\n  update public.private_research_payment_attempts p set confirmation=p_confirmation,settled_at=now()\n  where p.id=p_id and p.confirmation is null and exists (\n    select 1 from public.private_research_intents i where i.id=p.id and i.payer=lower(p_payer)\n  );\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"confirm_private_research_payment","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=\"\""],"source":"\ndeclare original jsonb;\nbegin\n  select data into original from public.private_research_intents where id=p_id and payer=lower(p_payer);\n  if not found then return; end if;\n  if jsonb_typeof(p_confirmation) is distinct from ''object''\n    or coalesce(p_confirmation->>''source'','''') not in (''circle-facilitator-success'',''circle-transfer-search'')\n    or ((p_confirmation->>''source'') = ''circle-transfer-search'' and coalesce(p_confirmation->>''transferStatus'','''') not in (''confirmed'',''completed''))\n    or ((p_confirmation->>''source'') = ''circle-facilitator-success'' and p_confirmation ? ''transferStatus'')\n    or (p_confirmation->>''network'') is distinct from (original->''requirement''->>''network'')\n    or lower(p_confirmation->>''payer'') is distinct from (original->''submission''->''payment''->''authorization''->>''from'')\n    or lower(p_confirmation->>''payee'') is distinct from (original->''submission''->''payment''->''authorization''->>''to'')\n    or (p_confirmation->>''amountMicros'') is distinct from (original->''submission''->''payment''->''authorization''->>''value'')\n    or (p_confirmation->>''authorizationId'') is distinct from (original->''submission''->''payment''->''authorization''->>''nonce'')\n    or coalesce(p_confirmation->>''transaction'','''') !~ ''^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$''\n  then raise exception ''confirmation mismatch''; end if;\n  update public.private_research_payment_attempts p set confirmation=p_confirmation,settled_at=now