('before','functions',30,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_authorization_id text, p_circle_transfer_id text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.fail_pending_payment(p_id text, p_authorization_id text, p_circle_transfer_id text)\n RETURNS TABLE(resolved boolean, reservation_released boolean)\n LANGUAGE plpgsql\nAS $function$\ndeclare\n  v_payer text;\n  v_amount numeric;\n  v_grant_epoch text;\n  v_released integer := 0;\nbegin\n  select payer, amount_usdc, grant_epoch\n    into v_payer, v_amount, v_grant_epoch\n    from public.payment_events\n   where id = p_id\n     and authorization_id = p_authorization_id\n     and settled = false\n     and settlement_status = ''pending''\n   for update;\n\n  if not found then\n    return query select false, false;\n    return;\n  end if;\n\n  update public.payment_events\n     set settlement_status = ''failed'', tx_hash = p_circle_transfer_id\n   where id = p_id\n     and authorization_id = p_authorization_id\n     and settled = false\n     and settlement_status = ''pending'';\n\n  if v_grant_epoch is not null then\n    update public.session_grants\n       set spent = greatest(0, round(spent - v_amount, 6))\n     where grant_epoch = v_grant_epoch\n       and lower(sess_addr) = lower(v_payer);\n    get diagnostics v_released = row_count;\n  end if;\n\n  return query select true, v_released = 1;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"fail_pending_payment","owner":"postgres","parallel":"u","result":"TABLE(resolved boolean, reservation_released boolean)","returnsSet":true,"rows":"1000","schema":"public","securityDefiner":false,"settings":null,"source":"\ndeclare\n  v_payer text;\n  v_amount numeric;\n  v_grant_epoch text;\n  v_released integer := 0;\nbegin\n  select payer, amount_usdc, grant_epoch\n    into v_payer, v_amount, v_grant_epoch\n    from public.payment_events\n   where id = p_id\n     and authorization_id = p_authorization_id\n     and settled = false\n     and settlement_status = ''pending''\n   for update;\n\n  if not found then\n    return query select false, false;\n    return;\n  end if;\n\n  update public.payment_events\n     set settlement_status = ''failed'', tx_hash = p_circle_transfer_id\n   where id = p_id\n     and authorization_id = p_authorization_id\n     and settled = false\n     and settlement_status = ''pending'';\n\n  if v_grant_epoch is not null then\n    update public.session_grants\n       set spent = greatest(0, round(spent - v_amount, 6))\n     where grant_epoch = v_grant_epoch\n       and lower(sess_addr) = lower(v_payer);\n    get diagnostics v_released = row_count;\n  end if;\n\n  return query select true, v_released = 1;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
