('before','functions',33,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_payer text, p_worker_id uuid","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.interrupt_private_research(p_id text, p_payer text, p_worker_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\nbegin\n  -- Same serialization point as creator admission and result saving.\n  perform e.id from public.private_research_executions e join public.private_research_intents i on i.id=e.id\n    where e.id=p_id and e.worker_id=p_worker_id and i.payer=lower(p_payer) for update of e;\n  if not found then return; end if;\n  if exists(select 1 from public.private_research_results where id=p_id) then return; end if;\n  insert into public.private_research_interruptions(id,worker_id,reason)\n    values(p_id,p_worker_id,''worker-interrupted'') on conflict(id) do nothing;\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"interrupt_private_research","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=\"\""],"source":"\nbegin\n  -- Same serialization point as creator admission and result saving.\n  perform e.id from public.private_research_executions e join public.private_research_intents i on i.id=e.id\n    where e.id=p_id and e.worker_id=p_worker_id and i.payer=lower(p_payer) for update of e;\n  if not found then return; end if;\n  if exists(select 1 from public.private_research_results where id=p_id) then return; end if;\n  insert into public.private_research_interruptions(id,worker_id,reason)\n    values(p_id,p_worker_id,''worker-interrupted'') on conflict(id) do nothing;\nend ","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',34,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_wallet text, p_before_created_at timestamp with time zone, p_before_id text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.list_a2a_orders_for_payer(p_wallet text, p_before_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id text DEFAULT NULL::text)\n RETURNS SETOF public.a2a_orders\n LANGUAGE sql\n STABLE\n SET search_path TO ''public''\nAS $function$\n  select * from public.a2a_orders\n  where lower(payer) = lower(p_wallet)\n    and ((p_before_created_at is null and p_before_id is null)\n      or (p_before_created_at is not null and p_before_id is not null\n        and (created_at < p_before_created_at or (created_at = p_before_created_at and id < p_before_id))))\n  order by created_at desc, id desc limit 26;\n$function$\n","kind":"f","language":"sql","leakproof":false,"name":"list_a2a_orders_for_payer","owner":"postgres","parallel":"u","result":"SETOF public.a2a_orders","returnsSet":true,"rows":"1000","schema":"public","securityDefiner":false,"settings":["search_path=public"],"source":"\n  select * from public.a2a_orders\n  where lower(payer) = lower(p_wallet)\n    and ((p_before_created_at is null and p_before_id is null)\n      or (p_before_created_at is not null and p_before_id is not null\n        and (created_at < p_before_created_at or (created_at = p_before_created_at and id < p_before_id))))\n  order by created_at desc, id desc limit 26;\n","strict":false,"support":null,"volatility":"s"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',35,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_signer text, p_after text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.list_private_reconciliation_candidates(p_signer text, p_after text DEFAULT NULL::text)\n RETURNS TABLE(id text, payer text)\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''public''\nAS $function$\nBEGIN\n  IF p_signer IS NULL OR p_signer !~ ''^0x[0-9a-f]{40}$''\n    OR p_signer = ''0x0000000000000000000000000000000000000000''\n    OR (p_after IS NOT NULL AND p_after !~ ''^prv_[0-9a-f]{64}$'') THEN\n    RAISE EXCEPTION ''Invalid private reconciliation selection'';\n  END IF;\n  RETURN QUERY SELECT i.id, i.payer FROM public.private_treasury_reservations r\n    JOIN public.private_research_intents i ON i.id = r.job_id\n    WHERE r.signer = p_signer AND (p_after IS NULL OR i.id > p_after)\n    ORDER BY i.id ASC LIMIT 1;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"list_private_reconciliation_candidates","owner":"postgres","parallel":"u","result":"TABLE(id text, payer text)","returnsSet":true,"rows":"1000","schema":"public","securityDefiner":false,"settings":["search_path=public"],"source":"\nBEGIN\n  IF p_signer IS NULL OR p_signer !~ ''^0x[0-9a-f]{40}$''\n    OR p_signer = ''0x0000000000000000000000000000000000000000''\n    OR (p_after IS NOT NULL AND p_after !~ ''^prv_[0-9a-f]{64}$'') THEN\n    RAISE EXCEPTION ''Invalid private reconciliation selection'';\n  END IF;\n  RETURN QUERY SELECT i.id, i.payer FROM public.private_treasury_reservations r\n    JOIN public.private_research_intents i ON i.id = r.job_id\n    WHERE r.signer = p_signer AND (p_after IS NULL OR i.id > p_after)\n    ORDER BY i.id ASC LIMIT 1;\nEND;\n","strict":false,"support":null,"volatility":"s"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',36,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_signer text, p_after text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.list_private_worker_candidates(p_signer text, p_after text DEFAULT NULL::text)\n RETURNS TABLE(id text, payer text)\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''public''\nAS $function$\nBEGIN\n  IF p_signer IS NULL OR p_signer !~ ''^0x[0-9a-f]{40}$''\n    OR p_signer = ''0x0000000000000000000000000000000000000000''\n    OR (p_after IS NOT NULL AND p_after !~ ''^prv_[0-9a-f]{64}$'') THEN\n    RAISE EXCEPTION ''Invalid private worker selection'';\n  END IF;\n  RETURN QUERY SELECT i.id, i.payer FROM public.private_treasury_reservations r\n    JOIN public.private_research_intents i ON i.id = r.job_id\n    JOIN public.private_research_payment_attempts p ON p.id = i.id\n    LEFT JOIN public.private_research_executions e ON e.id = i.id\n    WHERE r.signer = p_signer AND p.confirmation IS NOT NULL AND p.settled_at IS NOT NULL\n      AND e.id IS NULL AND (p_after IS NULL OR i.id > p_after)\n    ORDER BY i.id ASC LIMIT 25;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"list_private_worker_candidates","owner":"postgres","parallel":"u","result":"TABLE(id text, payer text)","returnsSet":true,"rows":"1000","schema":"public","securityDefiner":false,"settings":["search_path=public"],"source":"\nBEGIN\n  IF p_signer IS NULL OR p_signer !~ ''^0x[0-9a-f]{40}$''\n    OR p_signer = ''0x0000000000000000000000000000000000000000''\n    OR (p_after IS NOT NULL AND p_after !~ ''^prv_[0-9a-f]{64}$'') THEN\n    RAISE EXCEPTION ''Invalid private worker selection'';\n  END IF;\n  RETURN QUERY SELECT i.id, i.payer FROM public.private_treasury_reservations r\n    JOIN public.private_research_intents i ON i.id = r.job_id\n    JOIN public.private_research_payment_attempts p ON p.id = i.id\n    LEFT JOIN public.private_research_executions e ON e.id = i.id\n    WHERE r.signer = p_signer AND p.confirmation IS NOT NULL AND p.settled_at IS NOT NULL\n      AND e.id IS NULL AND (p_after IS NULL OR i.id > p_after)\n    ORDER BY i.id ASC LIMIT 25;\nEND;\n","strict":false,"support":null,"volatility":"s"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',37,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_started_at timestamp with time zone","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.mark_a2a_payment_started(p_id text, p_started_at timestamp with time zone)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nDECLARE\n  changed integer;\nBEGIN\n  UPDATE public.a2a_orders\n     SET payment_started_at = COALESCE(payment_started_at, p_started_at),\n         updated_at = p_started_at\n   WHERE id = p_id\n     AND status = ''running''\n     AND started_at IS NOT NULL\n     AND execution_journal_version = 1;\n  GET DIAGNOSTICS changed = ROW_COUNT;\n  RETURN changed = 1;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"mark_a2a_payment_started","owner":"postgres","parallel":"u","result":"boolean","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=public"],"source":"\nDECLARE\n  changed integer;\nBEGIN\n  UPDATE public.a2a_orders\n     SET payment_started_at = COALESCE(payment_started_at, p_started_at),\n         updated_at = p_started_at\n   WHERE id = p_id\n     AND status = ''running''\n     AND started_at IS NOT NULL\n     AND execution_journal_version = 1;\n  GET DIAGNOSTICS changed = ROW_COUNT;\n  RETURN changed = 1;\nEND;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',38,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_started_at timestamp with time zone","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.mark_a2a_result_saving(p_id text, p_started_at timestamp with time zone)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nDECLARE\n  changed integer;\nBEGIN\n  UPDATE public.a2a_orders\n     SET result_saving_at = COALESCE(result_saving_at, p_started_at),\n         updated_at = p_started_at\n   WHERE id = p_id\n     AND status = ''running''\n     AND started_at IS NOT NULL\n     AND execution_journal_version = 1;\n  GET DIAGNOSTICS changed = ROW_COUNT;\n  RETURN changed = 1;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"mark_a2a_result_saving","owner":"postgres","parallel":"u","result":"boolean","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=public"],"source":"\nDECLARE\n  changed integer;\nBEGIN\n  UPDATE public.a2a_orders\n     SET result_saving_at = COALESCE(result_saving_at, p_started_at),\n         updated_at = p_started_at\n   WHERE id = p_id\n     AND status = ''running''\n     AND started_at IS NOT NULL\n     AND execution_journal_version = 1;\n  GET DIAGNOSTICS changed = ROW_COUNT;\n  RETURN changed = 1;\nEND;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',39,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_signer text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.private_treasury_summary(p_signer text)\n RETURNS TABLE(capacity text, allocated text, committed text, confirmed text, invalid text)\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''public''\nAS $function$\nBEGIN\n  IF p_signer IS NULL OR p_signer !~ ''^0x[0-9a-f]{40}$''\n    OR p_signer = ''0x0000000000000000000000000000000000000000'' THEN\n    RAISE EXCEPTION ''Invalid private treasury selection'';\n  END IF;\n  RETURN QUERY WITH legs AS (\n    SELECT s.amount_micros,\n      CASE WHEN\n        (s.data#>>''{submission,amountMicros}'') IS DISTINCT FROM s.amount_micros::text OR\n        (s.data#>>''{submission,payer}'') IS DISTINCT FROM r.signer OR\n        (c.authorization_id IS NOT NULL AND (\n        (c.data->''submission'') IS DISTINCT FROM (s.data->''submission'') OR\n        NOT (COALESCE(c.data->>''source'','''')=''circle-facilitator-success'' OR\n          (COALESCE(c.data->>''source'','''')=''circle-transfer-search'' AND\n           COALESCE(c.data->>''transferStatus'','''') IN (''received'',''batched'',''confirmed'',''completed'')))\n      )) THEN 1 ELSE 0 END AS bad,\n      CASE WHEN c.data->>''source''=''circle-facilitator-success'' OR\n        (c.data->>''source''=''circle-transfer-search'' AND c.data->>''transferStatus'' IN (''confirmed'',''completed''))\n      THEN s.amount_micros ELSE 0 END AS settled\n    FROM public.private_treasury_reservations r JOIN public.private_creator_submissions s ON s.job_id=r.job_id\n    LEFT JOIN public.private_creator_confirmations c ON c.authorization_id=s.authorization_id WHERE r.signer=p_signer\n  ) SELECT p.capacity_micros::text,\n    COALESCE((SELECT SUM(r.amount_micros-COALESCE(x.amount_micros,0)) FROM public.private_treasury_reservations r\n      LEFT JOIN public.private_treasury_releases x ON x.job_id=r.job_id WHERE r.signer=p.signer),0)::text,\n    COALESCE((SELECT SUM(l.amount_micros) FROM legs l),0)::text,\n    COALESCE((SELECT SUM(l.settled) FROM legs l),0)::text,\n    COALESCE((SELECT SUM(l.bad) FROM legs l),0)::text\n    FROM public.private_treasury_pools p WHERE p.signer=p_signer;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"private_treasury_summary","owner":"postgres","parallel":"u","result":"TABLE(capacity text, allocated text, committed text, confirmed text, invalid text)","returnsSet":true,"rows":"1000","schema":"public","securityDefiner":false,"settings":["search_path=public"],"source":"\nBEGIN\n  IF p_signer IS NULL OR p_signer !~ ''^0x[0-9a-f]{40}$''\n    OR p_signer = ''0x0000000000000000000000000000000000000000'' THEN\n    RAISE EXCEPTION ''Invalid private treasury selection'';\n  END IF;\n  RETURN QUERY WITH legs AS (\n    SELECT s.amount_micros,\n      CASE WHEN\n        (s.data#>>''{submission,amountMicros}'') IS DISTINCT FROM s.amount_micros::text OR\n        (s.data#>>''{submission,payer}'') IS DISTINCT FROM r.signer OR\n        (c.authorization_id IS NOT NULL AND (\n        (c.data->''submission'') IS DISTINCT FROM (s.data->''submission'') OR\n        NOT (COALESCE(c.data->>''source'','''')=''circle-facilitator-success'' OR\n          (COALESCE(c.data->>''source'','''')=''circle-transfer-search'' AND\n           COALESCE(c.data->>''transferStatus'','''') IN (''received'',''batched'',''confirmed'',''completed'')))\n      )) THEN 1 ELSE 0 END AS bad,\n      CASE WHEN c.data->>''source''=''circle-facilitator-success'' OR\n        (c.data->>''source''=''circle-transfer-search'' AND c.data->>''transferStatus'' IN (''confirmed'',''completed''))\n      THEN s.amount_micros ELSE 0 END AS settled\n    FROM public.private_treasury_reservations r JOIN public.private_creator_submissions s ON s.job_id=r.job_id\n    LEFT JOIN public.private_creator_confirmations c ON c.authorization_id=s.authorization_id WHERE r.signer=p_signer\n  ) SELECT p.capacity_micros::text,\n    COALESCE((SELECT SUM(r.amount_micros-COALESCE(x.amount_micros,0)) FROM public.private_treasury_reservations r\n      LEFT JOIN public.private_treasury_releases x ON x.job_id=r.job_id WHERE r.signer=p.signer),0)::text,\n    COALESCE((SELECT SUM(l.amount_micros) FROM legs l),0)::text,\n    COALESCE((SELECT SUM(l.settled) FROM legs l),0)::text,\n    COALESCE((SELECT SUM(l.bad) FROM legs l),0)::text\n    FROM public.private_treasury_pools p WHERE p.signer=p_signer;\nEND;\n","strict":false,"support":null,"volatility":"s"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',40,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.read_storage_identity()\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare result jsonb;\nbegin\n  if current_setting(''statement_timeout'')::interval<=interval ''0''\n    or current_setting(''statement_timeout'')::interval>interval ''30 seconds'' then\n    raise exception ''bounded storage statement deadline required'';\n  end if;\n  select identity into result from keryx_storage.identity where singleton;\n  return result;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"read_storage_identity","owner":"postgres","parallel":"u","result":"jsonb","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare result jsonb;\nbegin\n  if current_setting(''statement_timeout'')::interval<=interval ''0''\n    or current_setting(''statement_timeout'')::interval>interval ''30 seconds'' then\n    raise exception ''bounded storage statement deadline required'';\n  end if;\n  select identity into result from keryx_storage.identity where singleton;\n  return result;\nend;\n","strict":false,"support":null,"volatility":"s"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',41,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_key text, p_transient boolean, p_now bigint, p_threshold integer, p_base_cooldown_ms bigint, p_max_cooldown_ms bigint","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.record_reasoning_circuit_failure(p_key text, p_transient boolean, p_now bigint, p_threshold integer, p_base_cooldown_ms bigint, p_max_cooldown_ms bigint)\n RETURNS TABLE(failures integer, open_until bigint)\n LANGUAGE plpgsql\nAS $function$\ndeclare\n  v_previous integer;\n  v_failures integer;\n  v_exponent integer;\n  v_cooldown bigint;\n  v_open_until bigint;\nbegin\n  insert into public.reasoning_circuits\n    (key, failures, open_until, probe_until, updated_at)\n  values (p_key, 0, 0, 0, p_now)\n  on conflict (key) do nothing;\n\n  select rc.failures\n    into v_previous\n    from public.reasoning_circuits rc\n   where rc.key = p_key\n   for update;\n\n  if p_transient then\n    v_failures := v_previous + 1;\n  else\n    v_failures := greatest(v_previous + 1, p_threshold);\n  end if;\n  v_exponent := greatest(0, least(20, v_failures - p_threshold));\n  v_cooldown := least(\n    greatest(p_base_cooldown_ms, p_max_cooldown_ms),\n    p_base_cooldown_ms * (1::bigint << v_exponent)\n  );\n  v_open_until := case\n    when v_failures >= p_threshold then p_now + v_cooldown\n    else 0\n  end;\n\n  update public.reasoning_circuits\n     set failures = v_failures,\n         open_until = v_open_until,\n         probe_until = 0,\n         updated_at = p_now\n   where key = p_key;\n\n  return query select v_failures, v_open_until;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"record_reasoning_circuit_failure","owner":"postgres","parallel":"u","result":"TABLE(failures integer, open_until bigint)","returnsSet":true,"rows":"1000","schema":"public","securityDefiner":false,"settings":null,"source":"\ndeclare\n  v_previous integer;\n  v_failures integer;\n  v_exponent integer;\n  v_cooldown bigint;\n  v_open_until bigint;\nbegin\n  insert into public.reasoning_circuits\n    (key, failures, open_until, probe_until, updated_at)\n  values (p_key, 0, 0, 0, p_now)\n  on conflict (key) do nothing;\n\n  select rc.failures\n    into v_previous\n    from public.reasoning_circuits rc\n   where rc.key = p_key\n   for update;\n\n  if p_transient then\n    v_failures := v_previous + 1;\n  else\n    v_failures := greatest(v_previous + 1, p_threshold);\n  end if;\n  v_exponent := greatest(0, least(20, v_failures - p_threshold));\n  v_cooldown := least(\n    greatest(p_base_cooldown_ms, p_max_cooldown_ms),\n    p_base_cooldown_ms * (1::bigint << v_exponent)\n  );\n  v_open_until := case\n    when v_failures >= p_threshold then p_now + v_cooldown\n    else 0\n  end;\n\n  update public.reasoning_circuits\n     set failures = v_failures,\n         open_until = v_open_until,\n         probe_until = 0,\n         updated_at = p_now\n   where key = p_key;\n\n  return query select v_failures, v_open_until;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',42,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_address_key text, p_day_key text, p_amount numeric","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.release_onramp(p_address_key text, p_day_key text, p_amount numeric)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\ndeclare\n  v_total numeric;\nbegin\n  perform pg_advisory_xact_lock(hashtext(p_day_key));\n  delete from public.sync_state where key = p_address_key;\n  select coalesce(value::numeric, 0) into v_total\n    from public.sync_state where key = p_day_key;\n  update public.sync_state\n     set value = greatest(0, coalesce(v_total, 0) - p_amount)::text,\n         updated_at = now()\n   where key = p_day_key;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"release_onramp","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":false,"settings":null,"source":"\ndeclare\n  v_total numeric;\nbegin\n  perform pg_advisory_xact_lock(hashtext(p_day_key));\n  delete from public.sync_state where key = p_address_key;\n  select coalesce(value::numeric, 0) into v_total\n    from public.sync_state where key = p_day_key;\n  update public.sync_state\n     set value = greatest(0, coalesce(v_total, 0) - p_amount)::text,\n         updated_at = now()\n   where key = p_day_key;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',43,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_payer text, p_signer text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.release_private_treasury(p_id text, p_payer text, p_signer text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare budget bigint; used bigint; original bigint; n integer;\nbegin\n  -- Share the pool lock with new reservations. Result sealing and creator admission\n  -- already share the execution lock; use it here too to serialize the final snapshot.\n  perform signer from public.private_treasury_pools where signer=p_signer for update;\n  if not found then return false; end if;\n  select r.amount_micros into budget from public.private_treasury_reservations r\n    join public.private_research_intents i on i.id=r.job_id\n    join public.private_research_executions e on e.id=i.id\n    where r.job_id=p_id and r.signer=p_signer and i.payer=lower(p_payer) for update of e;\n  if not found then return false; end if;\n  if not exists(select 1 from public.private_research_results where id=p_id)\n    and not exists(select 1 from public.private_research_interruptions where id=p_id) then return false; end if;\n  if exists(select 1 from public.private_creator_submissions where job_id=p_id and (\n    (data#>>''{submission,payer}'') is distinct from p_signer or\n    (data#>>''{submission,amountMicros}'') is distinct from amount_micros::text\n  )) then raise exception ''private treasury release accounting mismatch''; end if;\n  select coalesce(sum(amount_micros),0) into used from public.private_creator_submissions where job_id=p_id;\n  if used > budget then raise exception ''private treasury release accounting mismatch''; end if;\n  insert into public.private_treasury_releases(job_id,amount_micros) values(p_id,budget-used) on conflict(job_id) do nothing;\n  get diagnostics n = row_count;\n  select amount_micros into original from public.private_treasury_releases where job_id=p_id;\n  if original <> budget-used then raise exception ''private treasury release accounting mismatch''; end if;\n  return n=1;\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"release_private_treasury","owner":"postgres","parallel":"u","result":"boolean","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=\"\""],"source":"\ndeclare budget bigint; used bigint; original bigint; n integer;\nbegin\n  -- Share the pool lock with new reservations. Result sealing and creator admission\n  -- already share the execution lock; use it here too to serialize the final snapshot.\n  perform signer from public.private_treasury_pools where signer=p_signer for update;\n  if not found then return false; end if;\n  select r.amount_micros into budget from public.private_treasury_reservations r\n    join public.private_research_intents i on i.id=r.job_id\n    join public.private_research_executions e on e.id=i.id\n    where r.job_id=p_id and r.signer=p_signer and i.payer=lower(p_payer) for update of e;\n  if not found then return false; end if;\n  if not exists(select 1 from public.private_research_results where id=p_id)\n    and not exists(select 1 from public.private_research_interruptions where id=p_id) then return false; end if;\n  if exists(select 1 from public.private_creator_submissions where job_id=p_id and (\n    (data#>>''{submission,payer}'') is distinct from p_signer or\n    (data#>>''{submission,amountMicros}'') is distinct from amount_micros::text\n  )) then raise exception ''private treasury release accounting mismatch''; end if;\n  select coalesce(sum(amount_micros),0) into used from public.private_creator_submissions where job_id=p_id;\n  if used > budget then raise exception ''private treasury release accounting mismatch''; end if;\n  insert into public.private_treasury_releases(job_id,amount_micros) values(p_id,budget-used) on conflict(job_id) do nothing;\n  get diagnostics n = row_count;\n  select amount_micros into original from public.private_treasury_releases where job_id=p_id;\n  if original <> budget-used then raise exception ''private treasury release accounting mismatch''; end if;\n  return n=1;\nend ","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',44,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_session_id text, p_grant_epoch text, p_sess_addr text, p_amount numeric","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.release_session_grant_spend(p_session_id text, p_grant_epoch text, p_sess_addr text, p_amount numeric)\n RETURNS void\n LANGUAGE sql\nAS $function$\n  update public.session_grants\n     set spent = greatest(0, round(spent - p_amount, 6))\n   where session_id = p_session_id\n     and grant_epoch = p_grant_epoch\n     and lower(sess_addr) = lower(p_sess_addr);\n$function$\n","kind":"f","language":"sql","leakproof":false,"name":"release_session_grant_spend","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":false,"settings":null,"source":"\n  update public.session_grants\n     set spent = greatest(0, round(spent - p_amount, 6))\n   where session_id = p_session_id\n     and grant_epoch = p_grant_epoch\n     and lower(sess_addr) = lower(p_sess_addr);\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',45,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_owner text, p_data jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.reserve_creator_withdrawal(p_id text, p_owner text, p_data jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\nbegin\n  if p_id is null or p_owner is null or p_data is null\n    or (p_data->>''id'') is distinct from p_id or (p_data->>''owner'') is distinct from lower(p_owner)\n    or (p_data->>''network'') is distinct from ''eip155:5042002''\n    or (p_data->>''format'') is distinct from ''creator-withdrawal-request-v1''\n  then raise exception ''invalid withdrawal request''; end if;\n  begin\n    insert into public.creator_withdrawal_requests(id,owner,data) values(p_id,lower(p_owner),p_data)\n      on conflict(id) do nothing;\n  exception when unique_violation then\n    if not exists(select 1 from public.creator_withdrawal_requests where id=p_id)\n    then raise; end if;\n  end;\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"reserve_creator_withdrawal","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=\"\""],"source":"\nbegin\n  if p_id is null or p_owner is null or p_data is null\n    or (p_data->>''id'') is distinct from p_id or (p_data->>''owner'') is distinct from lower(p_owner)\n    or (p_data->>''network'') is distinct from ''eip155:5042002''\n    or (p_data->>''format'') is distinct from ''creator-withdrawal-request-v1''\n  then raise exception ''invalid withdrawal request''; end if;\n  begin\n    insert into public.creator_withdrawal_requests(id,owner,data) values(p_id,lower(p_owner),p_data)\n      on conflict(id) do nothing;\n  exception when unique_violation then\n    if not exists(select 1 from public.creator_withdrawal_requests where id=p_id)\n    then raise; end if;\n  end;\nend ","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',46,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_address_key text, p_day_key text, p_amount numeric, p_daily_cap numeric, p_now bigint","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.reserve_onramp(p_address_key text, p_day_key text, p_amount numeric, p_daily_cap numeric, p_now bigint)\n RETURNS text\n LANGUAGE plpgsql\nAS $function$\ndeclare\n  v_total numeric;\nbegin\n  perform pg_advisory_xact_lock(hashtext(p_day_key));\n  if exists (select 1 from public.sync_state where key = p_address_key) then\n    return ''already-funded'';\n  end if;\n  select coalesce(value::numeric, 0) into v_total\n    from public.sync_state where key = p_day_key;\n  v_total := coalesce(v_total, 0);\n  if v_total + p_amount > p_daily_cap then\n    return ''daily-cap'';\n  end if;\n  insert into public.sync_state (key, value, updated_at)\n    values (p_address_key, p_now::text, now());\n  insert into public.sync_state (key, value, updated_at)\n    values (p_day_key, (v_total + p_amount)::text, now())\n    on conflict (key) do update\n      set value = excluded.value, updated_at = excluded.updated_at;\n  return ''reserved'';\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"reserve_onramp","owner":"postgres","parallel":"u","result":"text","returnsSet":false,"rows":"0","schema":"public","securityDefiner":false,"settings":null,"source":"\ndeclare\n  v_total numeric;\nbegin\n  perform pg_advisory_xact_lock(hashtext(p_day_key));\n  if exists (select 1 from public.sync_state where key = p_address_key) then\n    return ''already-funded'';\n  end if;\n  select coalesce(value::numeric, 0) into v_total\n    from public.sync_state where key = p_day_key;\n  v_total := coalesce(v_total, 0);\n  if v_total + p_amount > p_daily_cap then\n    return ''daily-cap'';\n  end if;\n  insert into public.sync_state (key, value, updated_at)\n    values (p_address_key, p_now::text, now());\n  insert into public.sync_state (key, value, updated_at)\n    values (p_day_key, (v_total + p_amount)::text, now())\n    on conflict (key) do update\n      set value = excluded.value, updated_at = excluded.updated_at;\n  return ''reserved'';\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',47,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_payer text, p_signer text, p_capacity bigint","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.reserve_private_treasury(p_id text, p_payer text, p_signer text, p_capacity bigint)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare amount bigint; ceiling bigint; used bigint; original record;\nbegin\n  if p_signer is null or p_signer !~ ''^0x[a-f0-9]{40}$'' or p_signer = ''0x0000000000000000000000000000000000000000''\n    or p_capacity is null or p_capacity < 1 or p_capacity > 999999999999 then raise exception ''invalid capacity policy''; end if;\n  select round((data->''submission''->''request''->>''budget'')::numeric * 1000000)::bigint into amount\n    from public.private_research_intents where id=p_id and payer=lower(p_payer);\n  if not found then raise exception ''private intent unavailable''; end if;\n  insert into public.private_treasury_pools values(p_signer,p_capacity) on conflict(signer) do nothing;\n  select capacity_micros into ceiling from public.private_treasury_pools where signer=p_signer for update;\n  if ceiling <> p_capacity then raise exception ''capacity policy conflict''; end if;\n  select * into original from public.private_treasury_reservations where job_id=p_id;\n  if found then\n    if original.signer <> p_signer or original.amount_micros <> amount then raise exception ''reservation conflict''; end if;\n    return true;\n  end if;\n  select coalesce(sum(r.amount_micros-coalesce(x.amount_micros,0)),0) into used\n    from public.private_treasury_reservations r left join public.private_treasury_releases x on x.job_id=r.job_id where r.signer=p_signer;\n  if amount > ceiling-used then return false; end if;\n  insert into public.private_treasury_reservations values(p_id,p_signer,amount) on conflict(job_id) do nothing;\n  select * into original from public.private_treasury_reservations where job_id=p_id;\n  if original.signer <> p_signer or original.amount_micros <> amount then raise exception ''reservation conflict''; end if;\n  return true;\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"reserve_private_treasury","owner":"postgres","parallel":"u","result":"boolean","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=\"\""],"source":"\ndeclare amount bigint; ceiling bigint; used bigint; original record;\nbegin\n  if p_signer is null or p_signer !~ ''^0x[a-f0-9]{40}$'' or p_signer = ''0x0000000000000000000000000000000000000000''\n    or p_capacity is null or p_capacity < 1 or p_capacity > 999999999999 then raise exception ''invalid capacity policy''; end if;\n  select round((data->''submission''->''request''->>''budget'')::numeric * 1000000)::bigint into amount\n    from public.private_research_intents where id=p_id and payer=lower(p_payer);\n  if not found then raise exception ''private intent unavailable''; end if;\n  insert into public.private_treasury_pools values(p_signer,p_capacity) on conflict(signer) do nothing;\n  select capacity_micros into ceiling from public.private_treasury_pools where signer=p_signer for update;\n  if ceiling <> p_capacity then raise exception ''capacity policy conflict''; end if;\n  select * into original from public.private_treasury_reservations where job_id=p_id;\n  if found then\n    if original.signer <> p_signer or original.amount_micros <> amount then raise exception ''reservation conflict''; end if;\n    return true;\n  end if;\n  select coalesce(sum(r.amount_micros-coalesce(x.amount_micros,0)),0) into used\n    from public.private_treasury_reservations r left join public.private_treasury_releases x on x.job_id=r.job_id where r.signer=p_signer;\n  if amount > ceiling-used then return false; end if;\n  insert into public.private_treasury_reservations values(p_id,p_signer,amount) on conflict(job_id) do nothing;\n  select * into original from public.private_treasury_reservations where job_id=p_id;\n  if original.signer <> p_signer or original.amount_micros <> amount then raise exception ''reservation conflict''; end if;\n  return true;\nend ","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',48,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_session_id text, p_grant_epoch text, p_sess_addr text, p_amount numeric, p_now bigint","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.reserve_session_grant_spend(p_session_id text, p_grant_epoch text, p_sess_addr text, p_amount numeric, p_now bigint)\n RETURNS boolean\n LANGUAGE plpgsql\nAS $function$\ndeclare\n  updated integer;\nbegin\n  update public.session_grants\n     set spent = round(spent + p_amount, 6)\n   where session_id = p_session_id\n     and grant_epoch = p_grant_epoch\n     and lower(sess_addr) = lower(p_sess_addr)\n     and expiry > p_now\n     and round(spent + p_amount, 6) <= cap;\n  get diagnostics updated = row_count;\n  return updated > 0;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"reserve_session_grant_spend","owner":"postgres","parallel":"u","result":"boolean","returnsSet":false,"rows":"0","schema":"public","securityDefiner":false,"settings":null,"source":"\ndeclare\n  updated integer;\nbegin\n  update public.session_grants\n     set spent = round(spent + p_amount, 6)\n   where session_id = p_session_id\n     and grant_epoch = p_grant_epoch\n     and lower(sess_addr) = lower(p_sess_addr)\n     and expiry > p_now\n     and round(spent + p_amount, 6) <= cap;\n  get diagnostics updated = row_count;\n  return updated > 0;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',49,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_outcome text, p_response jsonb, p_error_code text, p_resolution jsonb, p_started_before timestamp with time zone","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.resolve_a2a_order(p_id text, p_outcome text, p_response jsonb, p_error_code text, p_resolution jsonb, p_started_before timestamp with time zone DEFAULT NULL::timestamp with time zone)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nDECLARE\n  changed integer;\n  evidence_attempts bigint;\n  evidence_settled bigint;\n  evidence_pending bigint;\n  evidence_failed bigint;\n  evidence_simulated bigint;\n  creator_cap bigint;\n  journal_version smallint;\n  payment_boundary_crossed boolean;\n  result_save_boundary_crossed boolean;\nBEGIN\n  IF p_resolution IS NULL OR jsonb_typeof(p_resolution) <> ''object'' THEN\n    RAISE EXCEPTION ''A2A resolution evidence is required'';\n  END IF;\n\n  SELECT COUNT(*),\n         COALESCE(SUM(CASE WHEN state=''settled'' THEN micros ELSE 0 END), 0),\n         COALESCE(SUM(CASE WHEN state=''pending'' THEN micros ELSE 0 END), 0),\n         COALESCE(SUM(CASE WHEN state=''failed'' THEN micros ELSE 0 END), 0),\n         COALESCE(SUM(CASE WHEN state=''simulated'' THEN micros ELSE 0 END), 0)\n    INTO evidence_attempts, evidence_settled, evidence_pending, evidence_failed, evidence_simulated\n    FROM (\n      SELECT ROUND(payments.amount_usdc * 1000000)::bigint AS micros,\n             COALESCE(\n               payments.settlement_status,\n               CASE WHEN payments.settled THEN ''settled'' ELSE ''simulated'' END\n             ) AS state\n        FROM public.payment_events AS payments\n       WHERE payments.query_id = (\n         SELECT orders.query_id FROM public.a2a_orders AS orders WHERE orders.id = p_id\n       )\n         AND payments.kind <> ''inbound''\n    ) AS creator_payments;\n  SELECT ROUND(orders.creator_budget_usdc * 1000000)::bigint,\n         orders.execution_journal_version,\n         orders.payment_started_at IS NOT NULL,\n         orders.result_saving_at IS NOT NULL\n    INTO creator_cap, journal_version, payment_boundary_crossed, result_save_boundary_crossed\n    FROM public.a2a_orders AS orders\n   WHERE orders.id = p_id;\n\n  IF evidence_attempts IS DISTINCT FROM\n       (p_resolution#>>''{evidence,creatorAttempts}'')::bigint\n     OR evidence_settled IS DISTINCT FROM\n       (p_resolution#>>''{evidence,settledCreatorMicros}'')::bigint\n     OR evidence_pending IS DISTINCT FROM\n       (p_resolution#>>''{evidence,pendingCreatorMicros}'')::bigint\n     OR evidence_failed IS DISTINCT FROM\n       (p_resolution#>>''{evidence,failedCreatorMicros}'')::bigint\n     OR evidence_simulated IS DISTINCT FROM\n       (p_resolution#>>''{evidence,simulatedCreatorMicros}'')::bigint\n     OR journal_version IS DISTINCT FROM\n       (p_resolution#>>''{evidence,executionJournalVersion}'')::smallint\n     OR payment_boundary_crossed IS DISTINCT FROM\n       (p_resolution#>>''{evidence,paymentBoundaryCrossed}'')::boolean\n     OR result_save_boundary_crossed IS DISTINCT FROM\n       (p_resolution#>>''{evidence,resultSaveBoundaryCrossed}'')::boolean\n     OR creator_cap IS NULL\n     OR evidence_settled + evidence_pending > creator_cap THEN\n    RETURN false;\n  END IF;\n\n  IF p_outcome = ''completed'' THEN\n    IF p_response IS NULL OR p_error_code IS NOT NULL\n       OR p_resolution->>''action'' <> ''repair_completed''\n       OR (p_resolution#>>''{evidence,queryRunFound}'')::boolean IS DISTINCT FROM true\n       OR evidence_simulated > 0 THEN\n      RAISE EXCEPTION ''invalid A2A completion resolution'';\n    END IF;\n    WITH live_evidence AS (\n      SELECT COUNT(*) AS attempts,\n             COALESCE(SUM(CASE WHEN state=''settled'' THEN micros ELSE 0 END), 0) AS settled,\n             COALESCE(SUM(CASE WHEN state=''pending'' THEN micros ELSE 0 END), 0) AS pending,\n             COALESCE(SUM(CASE WHEN state=''failed'' THEN micros ELSE 0 END), 0) AS failed,\n             COALESCE(SUM(CASE WHEN state=''simulated'' THEN micros ELSE 0 END), 0) AS simulated\n        FROM (\n          SELECT ROUND(payments.amount_usdc * 1000000)::bigint AS micros,\n                 COALESCE(\n                   payments.settlement_status,\n                   CASE WHEN payments.settled THEN ''settled'' ELSE ''simulated'' END\n                 ) AS state\n            FROM public.payment_events AS payments\n           WHERE payments.query_id = (\n             SELECT query_id FROM public.a2a_orders WHERE id = p_id\n           )\n             AND payments.kind <> ''inbound''\n        ) AS current_creator_payments\n    )\n    UPDATE public.a2a_orders AS orders\n       SET status = ''completed'',\n           response_data = p_response,\n           error_code = NULL,\n           resolution_data = p_resolution,\n           updated_at = (p_resolution->>''resolvedAt'')::timestamptz\n     WHERE orders.id = p_id\n       AND orders.status = ''running''\n       AND orders.started_at IS NOT NULL\n       AND EXISTS (\n         SELECT 1 FROM public.query_runs AS runs\n          WHERE runs.id = orders.query_id AND runs.payment_mode = ''real''\n       )\n       AND orders.execution_journal_version IS NOT DISTINCT FROM journal_version\n       AND (orders.payment_started_at IS NOT NULL) IS NOT DISTINCT FROM payment_boundary_crossed\n       AND (orders.result_saving_at IS NOT NULL) IS NOT DISTINCT FROM result_save_boundary_crossed\n       AND (SELECT attempts FROM live_evidence) = evidence_attempts\n       AND (SELECT settled FROM live_evidence) = evidence_settled\n       AND (SELECT pending FROM live_evidence) = evidence_pending\n       AND (SELECT failed FROM live_evidence) = evidence_failed\n       AND (SELECT simulated FROM live_evidence) = evidence_simulated;\n  ELSIF p_outcome = ''failed'' THEN\n    IF p_response IS NOT NULL OR p_error_code <> ''operator_reviewed_no_result''\n       OR p_started_before IS NULL OR p_resolution->>''action'' <> ''close_failed''\n       OR (p_resolution#>>''{evidence,queryRunFound}'')::boolean IS DISTINCT FROM false\n       OR journal_version IS DISTINCT FROM 1 OR payment_boundary_crossed\n       OR result_save_boundary_crossed\n       OR evidence_attempts > 0 THEN\n      RAISE EXCEPTION ''invalid A2A failure resolution'';\n    END IF;\n    UPDATE public.a2a_orders AS orders\n       SET status = ''failed'',\n           response_data = NULL,\n           error_code = p_error_code,\n           resolution_data = p_resolution,\n           updated_at = (p_resolution->>''resolvedAt'')::timestamptz\n     WHERE orders.id = p_id\n       AND orders.status = ''running''\n       AND orders.started_at IS NOT NULL\n       AND orders.started_at <= p_started_before\n       AND orders.execution_journal_version = 1\n       AND orders.payment_started_at IS NULL\n       AND orders.result_saving_at IS NULL\n       AND NOT EXISTS (\n         SELECT 1 FROM public.query_runs AS runs WHERE runs.id = orders.query_id\n       )\n       AND NOT EXISTS (\n         SELECT 1 FROM public.payment_events AS payments\n          WHERE payments.query_id = orders.query_id AND payments.kind <> ''inbound''\n       );\n  ELSE\n    RAISE EXCEPTION ''invalid A2A resolution outcome'';\n  END IF;\n\n  GET DIAGNOSTICS changed = ROW_COUNT;\n  RETURN changed = 1;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"resolve_a2a_order","owner":"postgres","parallel":"u","result":"boolean","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=public"],"source":"\nDECLARE\n  changed integer;\n  evidence_attempts bigint;\n  evidence_settled bigint;\n  evidence_pending bigint;\n  evidence_failed bigint;\n  evidence_simulated bigint;\n  creator_cap bigint;\n  journal_version smallint;\n  payment_boundary_crossed boolean;\n  result_save_boundary_crossed boolean;\nBEGIN\n  IF p_resolution IS NULL OR jsonb_typeof(p_resolution) <> ''object'' THEN\n    RAISE EXCEPTION ''A2A resolution evidence is required'';\n  END IF;\n\n  SELECT COUNT(*),\n         COALESCE(SUM(CASE WHEN state=''settled'' THEN micros ELSE 0 END), 0),\n         COALESCE(SUM(CASE WHEN state=''pending'' THEN micros ELSE 0 END), 0),\n         COALESCE(SUM(CASE WHEN state=''failed'' THEN micros ELSE 0 END), 0),\n         COALESCE(SUM(CASE WHEN state=''simulated'' THEN micros ELSE 0 END), 0)\n    INTO evidence_attempts, evidence_settled, evidence_pending, evidence_failed, evidence_simulated\n    FROM (\n      SELECT ROUND(payments.amount_usdc * 1000000)::bigint AS micros,\n             COALESCE(\n               payments.settlement_status,\n               CASE WHEN payments.settled THEN ''settled'' ELSE ''simulated'' END\n             ) AS state\n        FROM public.payment_events AS payments\n       WHERE payments.query_id = (\n         SELECT orders.query_id FROM public.a2a_orders AS orders WHERE orders.id = p_id\n       )\n         AND payments.kind <> ''inbound''\n    ) AS creator_payments;\n  SELECT ROUND(orders.creator_budget_usdc * 1000000)::bigint,\n         orders.execution_journal_version,\n         orders.payment_started_at IS NOT NULL,\n         orders.result_saving_at IS NOT NULL\n    INTO creator_cap, journal_version, payment_boundary_crossed, result_save_boundary_crossed\n    FROM public.a2a_orders AS orders\n   WHERE orders.id = p_id;\n\n  IF evidence_attempts IS DISTINCT FROM\n       (p_resolution#>>''{evidence,creatorAttempts}'')::bigint\n     OR evidence_settled IS DISTINCT FROM\n       (p_resolution#>>''{evidence,settledCreatorMicros}'')::bigint\n     OR evidence_pending IS DISTINCT FROM\n       (p_resolution#>>''{evidence,pendingCreatorMicros}'')::bigint\n     OR evidence_failed IS DISTINCT FROM\n       (p_resolution#>>''{evidence,failedCreatorMicros}'')::bigint\n     OR evidence_simulated IS DISTINCT FROM\n       (p_resolution#>>''{evidence,simulatedCreatorMicros}'')::bigint\n     OR journal_version IS DISTINCT FROM\n       (p_resolution#>>''{evidence,executionJournalVersion}'')::smallint\n     OR payment_boundary_crossed IS DISTINCT FROM\n       (p_resolution#>>''{evidence,paymentBoundaryCrossed}'')::boolean\n     OR result_save_boundary_crossed IS DISTINCT FROM\n       (p_resolution#>>''{evidence,resultSaveBoundaryCrossed}'')::boolean\n     OR creator_cap IS NULL\n     OR evidence_settled + evidence_pending > creator_cap THEN\n    RETURN false;\n  END IF;\n\n  IF p_outcome = ''completed'' THEN\n    IF p_response IS NULL OR p_error_code IS NOT NULL\n       OR p_resolution->>''action'' <> ''repair_completed''\n       OR (p_resolution#>>''{evidence,queryRunFound}'')::boolean IS DISTINCT FROM true\n       OR evidence_simulated > 0 THEN\n      RAISE EXCEPTION ''invalid A2A completion resolution'';\n    END IF;\n    WITH live_evidence AS (\n      SELECT COUNT(*) AS attempts,\n             COALESCE(SUM(CASE WHEN state=''settled'' THEN micros ELSE 0 END), 0) AS settled,\n             COALESCE(SUM(CASE WHEN state=''pending'' THEN micros ELSE 0 END), 0) AS pending,\n             COALESCE(SUM(CASE WHEN state=''failed'' THEN micros ELSE 0 END), 0) AS failed,\n             COALESCE(SUM(CASE WHEN state=''simulated'' THEN micros ELSE 0 END), 0) AS simulated\n        FROM (\n          SELECT ROUND(payments.amount_usdc * 1000000)::bigint AS micros,\n                 COALESCE(\n                   payments.settlement_status,\n                   CASE WHEN payments.settled THEN ''settled'' ELSE ''simulated'' END\n                 ) AS state\n            FROM public.payment_events AS payments\n           WHERE payments.query_id = (\n             SELECT query_id FROM public.a2a_orders WHERE id = p_id\n           )\n             AND payments.kind <> ''inbound''\n        ) AS current_creator_payments\n    )\n    UPDATE public.a2a_orders AS orders\n       SET status = ''completed'',\n           response_data = p_response,\n           error_code = NULL,\n           resolution_data = p_resolution,\n           updated_at = (p_resolution->>''resolvedAt'')::timestamptz\n     WHERE orders.id = p_id\n       AND orders.status = ''running''\n       AND orders.started_at IS NOT NULL\n       AND EXISTS (\n         SELECT 1 FROM public.query_runs AS runs\n          WHERE runs.id = orders.query_id AND runs.payment_mode = ''real''\n       )\n       AND orders.execution_journal_version IS NOT DISTINCT FROM journal_version\n       AND (orders.payment_started_at IS NOT NULL) IS NOT DISTINCT FROM payment_boundary_crossed\n       AND (orders.result_saving_at IS NOT NULL) IS NOT DISTINCT FROM result_save_boundary_crossed\n       AND (SELECT attempts FROM live_evidence) = evidence_attempts\n       AND (SELECT settled FROM live_evidence) = evidence_settled\n       AND (SELECT pending FROM live_evidence) = evidence_pending\n       AND (SELECT failed FROM live_evidence) = evidence_failed\n       AND (SELECT simulated FROM live_evidence) = evidence_simulated;\n  ELSIF p_outcome = ''failed'' THEN\n    IF p_response IS NOT NULL OR p_error_code <> ''operator_reviewed_no_result''\n       OR p_started_before IS NULL OR p_resolution->>''action'' <> ''close_failed''\n       OR (p_resolution#>>''{evidence,queryRunFound}'')::boolean IS DISTINCT FROM false\n       OR journal_version IS DISTINCT FROM 1 OR payment_boundary_crossed\n       OR result_save_boundary_crossed\n       OR evidence_attempts > 0 THEN\n      RAISE EXCEPTION ''invalid A2A failure resolution'';\n    END IF;\n    UPDATE public.a2a_orders AS orders\n       SET status = ''failed'',\n           response_data = NULL,\n           error_code = p_error_code,\n           resolution_data = p_resolution,\n           updated_at = (p_resolution->>''resolvedAt'')::timestamptz\n     WHERE orders.id = p_id\n       AND orders.status = ''running''\n       AND orders.started_at IS NOT NULL\n       AND orders.started_at <= p_started_before\n       AND orders.execution_journal_version = 1\n       AND orders.payment_started_at IS NULL\n       AND orders.result_saving_at IS NULL\n       AND NOT EXISTS (\n         SELECT 1 FROM public.query_runs AS runs WHERE runs.id = orders.query_id\n       )\n       AND NOT EXISTS (\n         SELECT 1 FROM public.payment_events AS payments\n          WHERE payments.query_id = orders.query_id AND payments.kind <> ''inbound''\n       );\n  ELSE\n    RAISE EXCEPTION ''invalid A2A resolution outcome'';\n  END IF;\n\n  GET DIAGNOSTICS changed = ROW_COUNT;\n  RETURN changed = 1;\nEND;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',50,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_session_id text, p_grant_epoch text, p_sess_addr text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.revoke_session_grant(p_session_id text, p_grant_epoch text, p_sess_addr text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare journal_active boolean; changed bigint;\nbegin\n  -- Same first lock as activation: mode cannot change between admission and CAS.\n  select active into journal_active from public.browser_journal_control where id=1 for update;\n  if journal_active is null then raise exception ''browser journal control unavailable''; end if;\n  if journal_active then\n    insert into public.browser_journal_writer values(txid_current());\n    update public.session_grants set expiry=0\n      where session_id=p_session_id and grant_epoch=p_grant_epoch and lower(sess_addr)=lower(p_sess_addr);\n    get diagnostics changed=row_count;\n    delete from public.browser_journal_writer where transaction_id=txid_current();\n  else\n    delete from public.session_grants\n      where session_id=p_session_id and grant_epoch=p_grant_epoch and lower(sess_addr)=lower(p_sess_addr);\n    get diagnostics changed=row_count;\n  end if;\n  return changed=1;\nend; $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"revoke_session_grant","owner":"postgres","parallel":"u","result":"boolean","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare journal_active boolean; changed bigint;\nbegin\n  -- Same first lock as activation: mode cannot change between admission and CAS.\n  select active into journal_active from public.browser_journal_control where id=1 for update;\n  if journal_active is null then raise exception ''browser journal control unavailable''; end if;\n  if journal_active then\n    insert into public.browser_journal_writer values(txid_current());\n    update public.session_grants set expiry=0\n      where session_id=p_session_id and grant_epoch=p_grant_epoch and lower(sess_addr)=lower(p_sess_addr);\n    get diagnostics changed=row_count;\n    delete from public.browser_journal_writer where transaction_id=txid_current();\n  else\n    delete from public.session_grants\n      where session_id=p_session_id and grant_epoch=p_grant_epoch and lower(sess_addr)=lower(p_sess_addr);\n    get diagnostics changed=row_count;\n  end if;\n  return changed=1;\nend; ","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',51,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_owner text, p_claim_id uuid, p_transfer_id uuid, p_data jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.save_creator_withdrawal_attestation(p_id text, p_owner text, p_claim_id uuid, p_transfer_id uuid, p_data jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\nbegin\n  if p_id is null or p_transfer_id is null or p_data is null\n    or (p_data->>''requestId'') is distinct from p_id\n    or (p_data->>''transferId'') is distinct from p_transfer_id::text\n    or (p_data->>''format'') is distinct from ''creator-withdrawal-attestation-v1''\n    or (p_data->>''authority'') is distinct from ''request-matched-only''\n  then raise exception ''invalid withdrawal attestation''; end if;\n  perform r.id from public.creator_withdrawal_requests r\n    join public.creator_withdrawal_transfer_attempts a on a.id=r.id\n    where r.id=p_id and r.owner=lower(p_owner) and a.claim_id=p_claim_id\n    for no key update of r;\n  if not found then return; end if;\n  insert into public.creator_withdrawal_attestations(id,claim_id,transfer_id,data)\n    select a.id,a.claim_id,p_transfer_id,p_data from public.creator_withdrawal_transfer_attempts a\n    join public.creator_withdrawal_requests r on r.id=a.id\n    where a.id=p_id and a.claim_id=p_claim_id and r.owner=lower(p_owner)\n    on conflict(id) do nothing;\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"save_creator_withdrawal_attestation","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=\"\""],"source":"\nbegin\n  if p_id is null or p_transfer_id is null or p_data is null\n    or (p_data->>''requestId'') is distinct from p_id\n    or (p_data->>''transferId'') is distinct from p_transfer_id::text\n    or (p_data->>''format'') is distinct from ''creator-withdrawal-attestation-v1''\n    or (p_data->>''authority'') is distinct from ''request-matched-only''\n  then raise exception ''invalid withdrawal attestation''; end if;\n  perform r.id from public.creator_withdrawal_requests r\n    join public.creator_withdrawal_transfer_attempts a on a.id=r.id\n    where r.id=p_id and r.owner=lower(p_owner) and a.claim_id=p_claim_id\n    for no key update of r;\n  if not found then return; end if;\n  insert into public.creator_withdrawal_attestations(id,claim_id,transfer_id,data)\n    select a.id,a.claim_id,p_transfer_id,p_data from public.creator_withdrawal_transfer_attempts a\n    join public.creator_withdrawal_requests r on r.id=a.id\n    where a.id=p_id and a.claim_id=p_claim_id and r.owner=lower(p_owner)\n    on conflict(id) do nothing;\nend ","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',52,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_payer text, p_worker_id uuid, p_serialized_run text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.save_private_research_result(p_id text, p_payer text, p_worker_id uuid, p_serialized_run text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\nbegin\n  perform e.id from public.private_research_executions e join public.private_research_intents i on i.id=e.id\n  where e.id=p_id and e.worker_id=p_worker_id and i.payer=lower(p_payer) for update of e;\n  if not found then return; end if;\n  insert into public.private_research_results(id,serialized_run) values(p_id,p_serialized_run) on conflict(id) do nothing;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"save_private_research_result","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=\"\""],"source":"\nbegin\n  perform e.id from public.private_research_executions e join public.private_research_intents i on i.id=e.id\n  where e.id=p_id and e.worker_id=p_worker_id and i.payer=lower(p_payer) for update of e;\n  if not found then return; end if;\n  insert into public.private_research_results(id,serialized_run) values(p_id,p_serialized_run) on conflict(id) do nothing;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
