('before','functions',216,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_nonce text, p_transfer_id text, p_mode text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.terminal_browser_journal(p_id text, p_nonce text, p_transfer_id text, p_mode text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare p public.payment_events%rowtype; v_signer text;\nbegin\n  if coalesce(p_mode,'''') not in (''settled'',''failed'',''cancelled_unexposed'') then raise exception ''Invalid journal terminal mode''; end if;\n  if p_mode<>''cancelled_unexposed'' and coalesce(length(p_transfer_id),0)=0 then raise exception ''Circle terminal proof identifier required''; end if;\n  -- Match lock order used by admission/recovery before touching payment and grant state.\n  select payer into v_signer from public.payment_events where id=p_id and authorization_id=p_nonce;\n  perform 1 from public.browser_signer_capacity where signer=lower(v_signer) for update;\n  select * into p from public.payment_events where id=p_id and authorization_id=p_nonce for update;\n  if not found or p.settlement_status is distinct from ''pending'' then return jsonb_build_object(''resolved'',false,''reservation_released'',false); end if;\n  if p.authorization_phase is null and p.grant_epoch is not null and not (select active from public.browser_journal_control where id=1) then\n    raise exception ''browser journal inactive'';\n  end if;\n  if p_mode=''cancelled_unexposed'' then\n    if p.authorization_phase is distinct from ''prepared'' then return jsonb_build_object(''resolved'',false,''reservation_released'',false); end if;\n  elsif p.authorization_phase is not null and p.authorization_phase not in (''exposed'',''signed'',''submission_attempted'') then\n    return jsonb_build_object(''resolved'',false,''reservation_released'',false);\n  end if;\n  insert into public.browser_journal_writer values(txid_current());\n  update public.payment_events set settlement_status=case when p_mode=''settled'' then ''settled'' else ''failed'' end,\n    settled=(p_mode=''settled''),tx_hash=p_transfer_id,authorization_phase=case when p.authorization_phase is null then null else p_mode end where id=p_id;\n  if p_mode<>''settled'' and p.grant_epoch is not null then\n    perform public.release_browser_journal_capacity(p.grant_epoch,p.payer,(p.amount_usdc*1000000)::bigint);\n  end if;\n  delete from public.browser_journal_writer where transaction_id=txid_current();\n  return jsonb_build_object(''resolved'',true,''reservation_released'',p_mode<>''settled'' and p.grant_epoch is not null);\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"terminal_browser_journal","owner":"postgres","parallel":"u","result":"jsonb","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare p public.payment_events%rowtype; v_signer text;\nbegin\n  if coalesce(p_mode,'''') not in (''settled'',''failed'',''cancelled_unexposed'') then raise exception ''Invalid journal terminal mode''; end if;\n  if p_mode<>''cancelled_unexposed'' and coalesce(length(p_transfer_id),0)=0 then raise exception ''Circle terminal proof identifier required''; end if;\n  -- Match lock order used by admission/recovery before touching payment and grant state.\n  select payer into v_signer from public.payment_events where id=p_id and authorization_id=p_nonce;\n  perform 1 from public.browser_signer_capacity where signer=lower(v_signer) for update;\n  select * into p from public.payment_events where id=p_id and authorization_id=p_nonce for update;\n  if not found or p.settlement_status is distinct from ''pending'' then return jsonb_build_object(''resolved'',false,''reservation_released'',false); end if;\n  if p.authorization_phase is null and p.grant_epoch is not null and not (select active from public.browser_journal_control where id=1) then\n    raise exception ''browser journal inactive'';\n  end if;\n  if p_mode=''cancelled_unexposed'' then\n    if p.authorization_phase is distinct from ''prepared'' then return jsonb_build_object(''resolved'',false,''reservation_released'',false); end if;\n  elsif p.authorization_phase is not null and p.authorization_phase not in (''exposed'',''signed'',''submission_attempted'') then\n    return jsonb_build_object(''resolved'',false,''reservation_released'',false);\n  end if;\n  insert into public.browser_journal_writer values(txid_current());\n  update public.payment_events set settlement_status=case when p_mode=''settled'' then ''settled'' else ''failed'' end,\n    settled=(p_mode=''settled''),tx_hash=p_transfer_id,authorization_phase=case when p.authorization_phase is null then null else p_mode end where id=p_id;\n  if p_mode<>''settled'' and p.grant_epoch is not null then\n    perform public.release_browser_journal_capacity(p.grant_epoch,p.payer,(p.amount_usdc*1000000)::bigint);\n  end if;\n  delete from public.browser_journal_writer where transaction_id=txid_current();\n  return jsonb_build_object(''resolved'',true,''reservation_released'',p_mode<>''settled'' and p.grant_epoch is not null);\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',217,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_session_id text, p_request_id text, p_from text, p_to text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.transition_browser_journal(p_session_id text, p_request_id text, p_from text, p_to text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare n integer;\nbegin\n  if coalesce((p_from,p_to) in ((''prepared'',''exposed''),(''signed'',''submission_attempted'')),false) is distinct from true then raise exception ''Invalid journal transition''; end if;\n  insert into public.browser_journal_writer values(txid_current());\n  update public.payment_events p set authorization_phase=p_to from public.browser_authorization_intents i,public.browser_journal_bindings b\n    where i.session_id=p_session_id and i.request_id=p_request_id and b.nonce=i.nonce and p.id=''x402:''||i.nonce\n      and p.authorization_phase=p_from and p.settlement_status=''pending'';\n  get diagnostics n=row_count;\n  delete from public.browser_journal_writer where transaction_id=txid_current();\n  return n=1;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"transition_browser_journal","owner":"postgres","parallel":"u","result":"boolean","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare n integer;\nbegin\n  if coalesce((p_from,p_to) in ((''prepared'',''exposed''),(''signed'',''submission_attempted'')),false) is distinct from true then raise exception ''Invalid journal transition''; end if;\n  insert into public.browser_journal_writer values(txid_current());\n  update public.payment_events p set authorization_phase=p_to from public.browser_authorization_intents i,public.browser_journal_bindings b\n    where i.session_id=p_session_id and i.request_id=p_request_id and b.nonce=i.nonce and p.id=''x402:''||i.nonce\n      and p.authorization_phase=p_from and p.settlement_status=''pending'';\n  get diagnostics n=row_count;\n  delete from public.browser_journal_writer where transaction_id=txid_current();\n  return n=1;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',218,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_key_id text, p_day date","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.upsert_api_key_usage(p_key_id text, p_day date)\n RETURNS void\n LANGUAGE sql\nAS $function$\n  INSERT INTO api_key_usage (key_id, day, call_count)\n  VALUES (p_key_id, p_day, 1)\n  ON CONFLICT (key_id, day) DO UPDATE SET call_count = api_key_usage.call_count + 1;\n$function$\n","kind":"f","language":"sql","leakproof":false,"name":"upsert_api_key_usage","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":false,"settings":null,"source":"\n  INSERT INTO api_key_usage (key_id, day, call_count)\n  VALUES (p_key_id, p_day, 1)\n  ON CONFLICT (key_id, day) DO UPDATE SET call_count = api_key_usage.call_count + 1;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',219,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_grant jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.upsert_browser_journal_grant(p_grant jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare v_signer text:=lower(p_grant->>''sess_addr''); v_spent bigint; v_cap numeric:=(p_grant->>''cap'')::numeric;\nbegin\n  if not (select active from public.browser_journal_control where id=1) then raise exception ''browser journal inactive''; end if;\n  if coalesce(v_signer ~ ''^0x[0-9a-f]{40}$'',false) is distinct from true\n     or v_cap is null or v_cap=''NaN''::numeric or v_cap<0 or v_cap*1000000<>trunc(v_cap*1000000) or v_cap*1000000>9007199254740991\n     or coalesce(length(p_grant->>''session_id''),0)=0 or coalesce(length(p_grant->>''grant_epoch''),0)=0 then raise exception ''Invalid grant capacity''; end if;\n  insert into public.browser_signer_capacity values(v_signer,0) on conflict do nothing;\n  select spent_micro into v_spent from public.browser_signer_capacity where signer=v_signer for update;\n  if v_spent>v_cap*1000000 then raise exception ''Session recovery cannot reset retained authorization capacity''; end if;\n  if exists(select 1 from public.browser_retained_grants where grant_epoch=p_grant->>''grant_epoch'') then raise exception ''Grant epoch already retained''; end if;\n  insert into public.browser_journal_writer values(txid_current());\n  insert into public.browser_retained_grants values(p_grant->>''grant_epoch'',p_grant->>''session_id'',v_signer,0);\n  insert into public.session_grants(session_id,sess_addr,owner_addr,cap,spent,expiry,tx_hash,grant_epoch)\n    values(p_grant->>''session_id'',v_signer,p_grant->>''owner_addr'',v_cap,v_spent::numeric/1000000,(p_grant->>''expiry'')::bigint,p_grant->>''tx_hash'',p_grant->>''grant_epoch'')\n    on conflict(session_id) do update set sess_addr=excluded.sess_addr,owner_addr=excluded.owner_addr,cap=excluded.cap,\n      spent=excluded.spent,expiry=excluded.expiry,tx_hash=excluded.tx_hash,grant_epoch=excluded.grant_epoch;\n  delete from public.browser_journal_writer where transaction_id=txid_current();\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"upsert_browser_journal_grant","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare v_signer text:=lower(p_grant->>''sess_addr''); v_spent bigint; v_cap numeric:=(p_grant->>''cap'')::numeric;\nbegin\n  if not (select active from public.browser_journal_control where id=1) then raise exception ''browser journal inactive''; end if;\n  if coalesce(v_signer ~ ''^0x[0-9a-f]{40}$'',false) is distinct from true\n     or v_cap is null or v_cap=''NaN''::numeric or v_cap<0 or v_cap*1000000<>trunc(v_cap*1000000) or v_cap*1000000>9007199254740991\n     or coalesce(length(p_grant->>''session_id''),0)=0 or coalesce(length(p_grant->>''grant_epoch''),0)=0 then raise exception ''Invalid grant capacity''; end if;\n  insert into public.browser_signer_capacity values(v_signer,0) on conflict do nothing;\n  select spent_micro into v_spent from public.browser_signer_capacity where signer=v_signer for update;\n  if v_spent>v_cap*1000000 then raise exception ''Session recovery cannot reset retained authorization capacity''; end if;\n  if exists(select 1 from public.browser_retained_grants where grant_epoch=p_grant->>''grant_epoch'') then raise exception ''Grant epoch already retained''; end if;\n  insert into public.browser_journal_writer values(txid_current());\n  insert into public.browser_retained_grants values(p_grant->>''grant_epoch'',p_grant->>''session_id'',v_signer,0);\n  insert into public.session_grants(session_id,sess_addr,owner_addr,cap,spent,expiry,tx_hash,grant_epoch)\n    values(p_grant->>''session_id'',v_signer,p_grant->>''owner_addr'',v_cap,v_spent::numeric/1000000,(p_grant->>''expiry'')::bigint,p_grant->>''tx_hash'',p_grant->>''grant_epoch'')\n    on conflict(session_id) do update set sess_addr=excluded.sess_addr,owner_addr=excluded.owner_addr,cap=excluded.cap,\n      spent=excluded.spent,expiry=excluded.expiry,tx_hash=excluded.tx_hash,grant_epoch=excluded.grant_epoch;\n  delete from public.browser_journal_writer where transaction_id=txid_current();\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',220,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_signing_control_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare retained integer;\nbegin\n if tg_op=''DELETE'' then raise exception ''browser signing activation is retained''; end if;\n select min_original_version into retained from public.browser_signing_v2_barrier where id=1;\n if new.id<>1 or new.min_original_version<coalesce(retained,2)\n  or (tg_op=''UPDATE'' and (new.min_original_version<old.min_original_version or (old.active and not new.active))) then raise exception ''browser signing minimum is retained''; end if;\n if new.min_original_version=3 and (new.active is distinct from true or (select active from public.browser_journal_control where id=1) is distinct from true) then raise exception ''browser signing base journal inactive''; end if;\n if new.active then\n  insert into public.browser_signing_v2_barrier values(1,new.min_original_version)\n   on conflict(id) do update set min_original_version=greatest(public.browser_signing_v2_barrier.min_original_version,excluded.min_original_version);\n end if;\n return new;\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"browser_signing_control_guard","owner":"postgres","parallel":"u","result":"trigger","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare retained integer;\nbegin\n if tg_op=''DELETE'' then raise exception ''browser signing activation is retained''; end if;\n select min_original_version into retained from public.browser_signing_v2_barrier where id=1;\n if new.id<>1 or new.min_original_version<coalesce(retained,2)\n  or (tg_op=''UPDATE'' and (new.min_original_version<old.min_original_version or (old.active and not new.active))) then raise exception ''browser signing minimum is retained''; end if;\n if new.min_original_version=3 and (new.active is distinct from true or (select active from public.browser_journal_control where id=1) is distinct from true) then raise exception ''browser signing base journal inactive''; end if;\n if new.active then\n  insert into public.browser_signing_v2_barrier values(1,new.min_original_version)\n   on conflict(id) do update set min_original_version=greatest(public.browser_signing_v2_barrier.min_original_version,excluded.min_original_version);\n end if;\n return new;\nend ","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',221,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_signing_fresh_gate()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\nbegin\n if exists(select 1 from public.browser_signing_v2_barrier where id=1)\n  and not exists(select 1 from public.browser_signing_v2_writer where transaction_id=txid_current()) then raise exception ''browser signing v2 original required''; end if;\n if public.browser_signing_original_floor_for_write()=3\n  and not exists(select 1 from public.browser_signing_v3_writer where transaction_id=txid_current()) then raise exception ''browser signing v3 source original required''; end if;\n return new;\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"browser_signing_fresh_gate","owner":"postgres","parallel":"u","result":"trigger","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\nbegin\n if exists(select 1 from public.browser_signing_v2_barrier where id=1)\n  and not exists(select 1 from public.browser_signing_v2_writer where transaction_id=txid_current()) then raise exception ''browser signing v2 original required''; end if;\n if public.browser_signing_original_floor_for_write()=3\n  and not exists(select 1 from public.browser_signing_v3_writer where transaction_id=txid_current()) then raise exception ''browser signing v3 source original required''; end if;\n return new;\nend ","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',222,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_session_id text, p_request_id text, p_metadata jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_signing_legacy_signature_internal(p_session_id text, p_request_id text, p_metadata jsonb)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare v_nonce text; v_phase text; b public.browser_journal_bindings%rowtype;\nbegin\n  if coalesce(p_metadata->>''headerHash'','''') !~ ''^[0-9a-f]{64}$''\n     or coalesce(p_metadata->>''validAfter'','''') !~ ''^(0|[1-9][0-9]*)$''\n     or coalesce(p_metadata->>''validBefore'','''') !~ ''^(0|[1-9][0-9]*)$''\n     or (p_metadata->>''validAfter'')::numeric>(p_metadata->>''validBefore'')::numeric\n     or (p_metadata->>''validBefore'')::numeric>8640000000000 then raise exception ''Invalid browser signed metadata''; end if;\n  select i.nonce,p.authorization_phase into v_nonce,v_phase from public.browser_authorization_intents i join public.payment_events p on p.id=''x402:''||i.nonce\n    where i.session_id=p_session_id and i.request_id=p_request_id for update of p;\n  if not found or coalesce(v_phase,'''') not in (''exposed'',''signed'',''submission_attempted'',''settled'',''failed'') then return false; end if;\n  select * into b from public.browser_journal_bindings where nonce=v_nonce for update;\n  if b.header_hash is not null then return (b.header_hash,b.valid_after,b.valid_before) is not distinct from (p_metadata->>''headerHash'',p_metadata->>''validAfter'',p_metadata->>''validBefore''); end if;\n  if v_phase<>''exposed'' then return false; end if;\n  insert into public.browser_journal_writer values(txid_current());\n  update public.browser_journal_bindings set valid_after=p_metadata->>''validAfter'',valid_before=p_metadata->>''validBefore'',header_hash=p_metadata->>''headerHash'' where nonce=v_nonce;\n  update public.payment_events set authorization_phase=''signed'',authorization_expires_at=to_timestamp((p_metadata->>''validBefore'')::double precision) where id=''x402:''||v_nonce;\n  delete from public.browser_journal_writer where transaction_id=txid_current();\n  return true;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"browser_signing_legacy_signature_internal","owner":"postgres","parallel":"u","result":"boolean","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare v_nonce text; v_phase text; b public.browser_journal_bindings%rowtype;\nbegin\n  if coalesce(p_metadata->>''headerHash'','''') !~ ''^[0-9a-f]{64}$''\n     or coalesce(p_metadata->>''validAfter'','''') !~ ''^(0|[1-9][0-9]*)$''\n     or coalesce(p_metadata->>''validBefore'','''') !~ ''^(0|[1-9][0-9]*)$''\n     or (p_metadata->>''validAfter'')::numeric>(p_metadata->>''validBefore'')::numeric\n     or (p_metadata->>''validBefore'')::numeric>8640000000000 then raise exception ''Invalid browser signed metadata''; end if;\n  select i.nonce,p.authorization_phase into v_nonce,v_phase from public.browser_authorization_intents i join public.payment_events p on p.id=''x402:''||i.nonce\n    where i.session_id=p_session_id and i.request_id=p_request_id for update of p;\n  if not found or coalesce(v_phase,'''') not in (''exposed'',''signed'',''submission_attempted'',''settled'',''failed'') then return false; end if;\n  select * into b from public.browser_journal_bindings where nonce=v_nonce for update;\n  if b.header_hash is not null then return (b.header_hash,b.valid_after,b.valid_before) is not distinct from (p_metadata->>''headerHash'',p_metadata->>''validAfter'',p_metadata->>''validBefore''); end if;\n  if v_phase<>''exposed'' then return false; end if;\n  insert into public.browser_journal_writer values(txid_current());\n  update public.browser_journal_bindings set valid_after=p_metadata->>''validAfter'',valid_before=p_metadata->>''validBefore'',header_hash=p_metadata->>''headerHash'' where nonce=v_nonce;\n  update public.payment_events set authorization_phase=''signed'',authorization_expires_at=to_timestamp((p_metadata->>''validBefore'')::double precision) where id=''x402:''||v_nonce;\n  delete from public.browser_journal_writer where transaction_id=txid_current();\n  return true;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',223,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_signing_original_floor_for_write()\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare minimum integer; control_minimum integer;\nbegin\n -- The barrier starts empty. Lock the always-present control first so a stale\n -- snapshot predating the first barrier INSERT cannot fall back to floor2.\n select min_original_version into control_minimum from public.browser_signing_v2_control where id=1 for share;\n if not found then raise exception ''browser signing control missing''; end if;\n select min_original_version into minimum from public.browser_signing_v2_barrier where id=1 for share;\n return greatest(control_minimum,coalesce(minimum,2));\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"browser_signing_original_floor_for_write","owner":"postgres","parallel":"u","result":"integer","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare minimum integer; control_minimum integer;\nbegin\n -- The barrier starts empty. Lock the always-present control first so a stale\n -- snapshot predating the first barrier INSERT cannot fall back to floor2.\n select min_original_version into control_minimum from public.browser_signing_v2_control where id=1 for share;\n if not found then raise exception ''browser signing control missing''; end if;\n select min_original_version into minimum from public.browser_signing_v2_barrier where id=1 for share;\n return greatest(control_minimum,coalesce(minimum,2));\nend ","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',224,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_signing_retention_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\nbegin\n if tg_op=''DELETE'' then raise exception ''browser signing history is retained''; end if;\n if tg_table_name=''browser_signing_queries'' then\n  if (to_jsonb(new)-''spent_micro'') is distinct from (to_jsonb(old)-''spent_micro'') or new.spent_micro<old.spent_micro then raise exception ''browser query consumption is monotonic''; end if;\n elsif tg_table_name=''browser_signing_namespaces'' then\n  if (new.namespace,new.owner,new.signer,new.service,new.network) is distinct from (old.namespace,old.owner,old.signer,old.service,old.network)\n   or new.allocated_micro<old.allocated_micro or new.jobs<old.jobs then raise exception ''browser namespace history is monotonic''; end if;\n elsif tg_table_name=''browser_signing_v2_barrier'' then\n  if new.id<>old.id or new.min_original_version<old.min_original_version then raise exception ''browser signing minimum is retained''; end if;\n else raise exception ''browser signing original is immutable''; end if;\n return new;\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"browser_signing_retention_guard","owner":"postgres","parallel":"u","result":"trigger","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\nbegin\n if tg_op=''DELETE'' then raise exception ''browser signing history is retained''; end if;\n if tg_table_name=''browser_signing_queries'' then\n  if (to_jsonb(new)-''spent_micro'') is distinct from (to_jsonb(old)-''spent_micro'') or new.spent_micro<old.spent_micro then raise exception ''browser query consumption is monotonic''; end if;\n elsif tg_table_name=''browser_signing_namespaces'' then\n  if (new.namespace,new.owner,new.signer,new.service,new.network) is distinct from (old.namespace,old.owner,old.signer,old.service,old.network)\n   or new.allocated_micro<old.allocated_micro or new.jobs<old.jobs then raise exception ''browser namespace history is monotonic''; end if;\n elsif tg_table_name=''browser_signing_v2_barrier'' then\n  if new.id<>old.id or new.min_original_version<old.min_original_version then raise exception ''browser signing minimum is retained''; end if;\n else raise exception ''browser signing original is immutable''; end if;\n return new;\nend ","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',225,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_value jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_signing_source_canonical(p_value jsonb)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE STRICT\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\n select case jsonb_typeof(p_value)\n when ''object'' then ''{''||coalesce((select string_agg(to_jsonb(key)::text||'':''||public.browser_signing_source_canonical(value),'','' order by key collate \"C\") from jsonb_each(p_value)),'''')||''}''\n when ''array'' then ''[''||coalesce((select string_agg(public.browser_signing_source_canonical(value),'','' order by ordinal) from jsonb_array_elements(p_value) with ordinality a(value,ordinal)),'''')||'']''\n else p_value::text end;\n$function$\n","kind":"f","language":"sql","leakproof":false,"name":"browser_signing_source_canonical","owner":"postgres","parallel":"u","result":"text","returnsSet":false,"rows":"0","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, pg_temp"],"source":"\n select case jsonb_typeof(p_value)\n when ''object'' then ''{''||coalesce((select string_agg(to_jsonb(key)::text||'':''||public.browser_signing_source_canonical(value),'','' order by key collate \"C\") from jsonb_each(p_value)),'''')||''}''\n when ''array'' then ''[''||coalesce((select string_agg(public.browser_signing_source_canonical(value),'','' order by ordinal) from jsonb_array_elements(p_value) with ordinality a(value,ordinal)),'''')||'']''\n else p_value::text end;\n","strict":true,"support":null,"volatility":"i"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',226,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_input jsonb, p_journal jsonb, p_original jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_signing_source_context_check(p_input jsonb, p_journal jsonb, p_original jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare c jsonb:=p_input->''sourceContext''; a jsonb:=p_input->''journal''; r jsonb:=c->''registry''; price jsonb:=c->''price'';\n bare jsonb:=p_original-array[''sourceContext'',''sourceContextDigest'']; canonical text; path text;\nbegin\n canonical:=public.browser_signing_source_canonical(c);\n if p_input->>''protocol'' is distinct from ''durable-v3'' or a->>''kind'' is distinct from ''fetch''\n  or jsonb_typeof(c) is distinct from ''object'' or octet_length(convert_to(canonical,''UTF8''))>6144\n  or (select count(*) from jsonb_object_keys(c))<>8\n  or (select count(*) from jsonb_object_keys(c->''source''))<>3 or (select count(*) from jsonb_object_keys(c->''item''))<>2\n  or (select count(*) from jsonb_object_keys(c->''endpoint''))<>2 or (select count(*) from jsonb_object_keys(r))<>9\n  or c->>''version'' is distinct from ''source-context-v1'' or c->>''service'' is distinct from ''https://keryx.cc'' or c->>''kind'' is distinct from ''fetch''\n  or c#>>''{source,sourceId}'' is distinct from a->>''sourceId'' or c#>>''{source,sourceId}'' is distinct from p_input#>>''{source,sourceId}''\n  or c#>>''{item,itemId}'' is distinct from p_input#>>''{source,itemId}'' or c#>>''{item,itemId}'' is distinct from p_journal#>>''{payment,itemId}''\n  or c#>>''{item,contentVersion}'' is distinct from p_input#>>''{source,contentVersion}'' or c#>>''{item,contentVersion}'' is distinct from p_journal#>>''{payment,contentVersion}''\n  or coalesce(c#>>''{source,sourceId}'','''') !~ ''^[A-Za-z0-9:_-]{1,128}$'' or coalesce(c#>>''{item,itemId}'','''') !~ ''^[A-Za-z0-9:_-]{1,128}$''\n  or coalesce(c#>>''{item,contentVersion}'','''') !~ ''^[!-~]{1,128}$'' or length(c#>>''{source,canonicalUrl}'')>2048\n  or coalesce(c#>>''{source,canonicalUrl}'','''') !~ ''^https?://'' or coalesce(c#>>''{source,registryId}'','''') !~ ''^0x[0-9a-f]{64}$''\n  or c#>>''{endpoint,method}'' is distinct from ''GET'' or coalesce(c#>>''{endpoint,path}'','''') !~ ''^/api/source/'' or length(c#>>''{endpoint,path}'')>2048\n  or r->>''network'' is distinct from ''eip155:5042002'' or r->''active'' is distinct from ''true''::jsonb\n  or coalesce(r->>''contract'','''') !~ ''^0x[0-9a-f]{40}$'' or coalesce(r->>''creator'','''') !~ ''^0x[0-9a-f]{40}$''\n  or coalesce(r->>''payoutWallet'','''') !~ ''^0x[0-9a-f]{40}$'' or r->>''payoutWallet'' is distinct from lower(a->>''payee'')\n  or coalesce(r->>''blockHash'','''') !~ ''^0x[0-9a-f]{64}$'' or coalesce(r->>''blockNumber'','''') !~ ''^(0|[1-9][0-9]{0,77})$''\n  or coalesce(r->>''blockTimestamp'','''') !~ ''^(0|[1-9][0-9]{0,77})$'' or coalesce(r->>''listPriceMicros'','''') !~ ''^[1-9][0-9]{0,15}$''\n  or coalesce(price->>''amountMicros'','''') !~ ''^[1-9][0-9]{0,15}$'' or price->>''amountMicros'' is distinct from a->>''amountMicroUsdc''\n  or p_original->''sourceContext'' is distinct from c or coalesce(p_original->>''sourceContextDigest'','''') !~ ''^0x[0-9a-f]{64}$''\n  or p_original->>''sourceContextDigest'' is distinct from ''0x''||encode(sha256(convert_to(public.browser_signing_source_canonical(jsonb_build_object(''original'',bare,''sourceContext'',c)),''UTF8'')),''hex'')\n  then raise exception ''browser source context refused''; end if;\n if (r->>''blockTimestamp'')::numeric>floor(extract(epoch from (p_journal->>''admittedAt'')::timestamptz))\n  or (r->>''listPriceMicros'')::numeric>9007199254740991 or (price->>''amountMicros'')::numeric>9007199254740991 then raise exception ''browser source context refused''; end if;\n if price->>''mode''=''list'' then\n  if (select count(*) from jsonb_object_keys(price))<>2 or price->>''amountMicros'' is distinct from r->>''listPriceMicros'' or p_input#>''{source,offerId}'' is distinct from ''null''::jsonb or a->''offerId'' is distinct from ''null''::jsonb then raise exception ''browser source list price refused''; end if;\n elsif price->>''mode''=''creator-offer'' then\n  if (select count(*) from jsonb_object_keys(price))<>3 or (select count(*) from jsonb_object_keys(price->''offer''))<>10\n   or price#>>''{offer,id}'' is distinct from p_input#>>''{source,offerId}'' or price#>>''{offer,id}'' is distinct from a->>''offerId''\n   or price#>>''{offer,sourceId}'' is distinct from a->>''sourceId'' or price#>>''{offer,itemId}'' is distinct from c#>>''{item,itemId}''\n   or price#>>''{offer,contentVersion}'' is distinct from c#>>''{item,contentVersion}'' or price#>>''{offer,priceUsdc6}'' is distinct from price->>''amountMicros''\n   or price#>>''{offer,signer}'' is distinct from r->>''creator'' or coalesce(price#>>''{offer,signature}'','''') !~ ''^0x[0-9a-f]{130}$''\n   or coalesce(price#>>''{offer,nonce}'','''') !~ ''^0x[0-9a-f]{64}$'' or coalesce(price#>>''{offer,id}'','''') !~ ''^0x[0-9a-f]{64}$''\n   or coalesce(price#>>''{offer,priceUsdc6}'','''') !~ ''^[1-9][0-9]{0,15}$'' or coalesce(price#>>''{offer,expiresAt}'','''') !~ ''^[1-9][0-9]{0,15}$''\n   or (price#>>''{offer,expiresAt}'')::numeric<=floor(extract(epoch from (p_journal->>''admittedAt'')::timestamptz))\n   or (price#>>''{offer,expiresAt}'')::numeric<=floor(extract(epoch from clock_timestamp()))\n   or (price#>>''{offer,expiresAt}'')::numeric>9007199254740991 or (price#>>''{offer,createdAt}'')::timestamptz is null\n   or (price->>''amountMicros'')::numeric>(r->>''listPriceMicros'')::numeric\n   then raise exception ''browser source offer refused''; end if;\n else raise exception ''browser source price mode refused''; end if;\n path:=''/api/source/''||(c#>>''{source,sourceId}'')||''/item/''||public.browser_signing_source_urlencode(c#>>''{item,itemId}'',true)||''?version=''||public.browser_signing_source_urlencode(c#>>''{item,contentVersion}'',false);\n if price->>''mode''=''creator-offer'' then path:=path||''&offer=''||(price#>>''{offer,id}'')||''&listPriceUsdc6=''||(r->>''listPriceMicros''); end if;\n if c#>>''{endpoint,path}'' is distinct from path then raise exception ''browser source endpoint refused''; end if;\n -- Additionally bound the prepared timestamp to five seconds. Recheck its\n -- age after database lock waits; the separate original-token deadline is authoritative.\n if (p_journal->>''admittedAt'')::timestamptz>clock_timestamp()\n  or clock_timestamp()-(p_journal->>''admittedAt'')::timestamptz>=interval ''5 seconds''\n  then raise exception ''browser source observation expired''; end if;\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"browser_signing_source_context_check","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare c jsonb:=p_input->''sourceContext''; a jsonb:=p_input->''journal''; r jsonb:=c->''registry''; price jsonb:=c->''price'';\n bare jsonb:=p_original-array[''sourceContext'',''sourceContextDigest'']; canonical text; path text;\nbegin\n canonical:=public.browser_signing_source_canonical(c);\n if p_input->>''protocol'' is distinct from ''durable-v3'' or a->>''kind'' is distinct from ''fetch''\n  or jsonb_typeof(c) is distinct from ''object'' or octet_length(convert_to(canonical,''UTF8''))>6144\n  or (select count(*) from jsonb_object_keys(c))<>8\n  or (select count(*) from jsonb_object_keys(c->''source''))<>3 or (select count(*) from jsonb_object_keys(c->''item''))<>2\n  or (select count(*) from jsonb_object_keys(c->''endpoint''))<>2 or (select count(*) from jsonb_object_keys(r))<>9\n  or c->>''version'' is distinct from ''source-context-v1'' or c->>''service'' is distinct from ''https://keryx.cc'' or c->>''kind'' is distinct from ''fetch''\n  or c#>>''{source,sourceId}'' is distinct from a->>''sourceId'' or c#>>''{source,sourceId}'' is distinct from p_input#>>''{source,sourceId}''\n  or c#>>''{item,itemId}'' is distinct from p_input#>>''{source,itemId}'' or c#>>''{item,itemId}'' is distinct from p_journal#>>''{payment,itemId}''\n  or c#>>''{item,contentVersion}'' is distinct from p_input#>>''{source,contentVersion}'' or c#>>''{item,contentVersion}'' is distinct from p_journal#>>''{payment,contentVersion}''\n  or coalesce(c#>>''{source,sourceId}'','''') !~ ''^[A-Za-z0-9:_-]{1,128}$'' or coalesce(c#>>''{item,itemId}'','''') !~ ''^[A-Za-z0-9:_-]{1,128}$''\n  or coalesce(c#>>''{item,contentVersion}'','''') !~ ''^[!-~]{1,128}$'' or length(c#>>''{source,canonicalUrl}'')>2048\n  or coalesce(c#>>''{source,canonicalUrl}'','''') !~ ''^https?://'' or coalesce(c#>>''{source,registryId}'','''') !~ ''^0x[0-9a-f]{64}$''\n  or c#>>''{endpoint,method}'' is distinct from ''GET'' or coalesce(c#>>''{endpoint,path}'','''') !~ ''^/api/source/'' or length(c#>>''{endpoint,path}'')>2048\n  or r->>''network'' is distinct from ''eip155:5042002'' or r->''active'' is distinct from ''true''::jsonb\n  or coalesce(r->>''contract'','''') !~ ''^0x[0-9a-f]{40}$'' or coalesce(r->>''creator'','''') !~ ''^0x[0-9a-f]{40}$''\n  or coalesce(r->>''payoutWallet'','''') !~ ''^0x[0-9a-f]{40}$'' or r->>''payoutWallet'' is distinct from lower(a->>''payee'')\n  or coalesce(r->>''blockHash'','''') !~ ''^0x[0-9a-f]{64}$'' or coalesce(r->>''blockNumber'','''') !~ ''^(0|[1-9][0-9]{0,77})$''\n  or coalesce(r->>''blockTimestamp'','''') !~ ''^(0|[1-9][0-9]{0,77})$'' or coalesce(r->>''listPriceMicros'','''') !~ ''^[1-9][0-9]{0,15}$''\n  or coalesce(price->>''amountMicros'','''') !~ ''^[1-9][0-9]{0,15}$'' or price->>''amountMicros'' is distinct from a->>''amountMicroUsdc''\n  or p_original->''sourceContext'' is distinct from c or coalesce(p_original->>''sourceContextDigest'','''') !~ ''^0x[0-9a-f]{64}$''\n  or p_original->>''sourceContextDigest'' is distinct from ''0x''||encode(sha256(convert_to(public.browser_signing_source_canonical(jsonb_build_object(''original'',bare,''sourceContext'',c)),''UTF8'')),''hex'')\n  then raise exception ''browser source context refused''; end if;\n if (r->>''blockTimestamp'')::numeric>floor(extract(epoch from (p_journal->>''admittedAt'')::timestamptz))\n  or (r->>''listPriceMicros'')::numeric>9007199254740991 or (price->>''amountMicros'')::numeric>9007199254740991 then raise exception ''browser source context refused''; end if;\n if price->>''mode''=''list'' then\n  if (select count(*) from jsonb_object_keys(price))<>2 or price->>''amountMicros'' is distinct from r->>''listPriceMicros'' or p_input#>''{source,offerId}'' is distinct from ''null''::jsonb or a->''offerId'' is distinct from ''null''::jsonb then raise exception ''browser source list price refused''; end if;\n elsif price->>''mode''=''creator-offer'' then\n  if (select count(*) from jsonb_object_keys(price))<>3 or (select count(*) from jsonb_object_keys(price->''offer''))<>10\n   or price#>>''{offer,id}'' is distinct from p_input#>>''{source,offerId}'' or price#>>''{offer,id}'' is distinct from a->>''offerId''\n   or price#>>''{offer,sourceId}'' is distinct from a->>''sourceId'' or price#>>''{offer,itemId}'' is distinct from c#>>''{item,itemId}''\n   or price#>>''{offer,contentVersion}'' is distinct from c#>>''{item,contentVersion}'' or price#>>''{offer,priceUsdc6}'' is distinct from price->>''amountMicros''\n   or price#>>''{offer,signer}'' is distinct from r->>''creator'' or coalesce(price#>>''{offer,signature}'','''') !~ ''^0x[0-9a-f]{130}$''\n   or coalesce(price#>>''{offer,nonce}'','''') !~ ''^0x[0-9a-f]{64}$'' or coalesce(price#>>''{offer,id}'','''') !~ ''^0x[0-9a-f]{64}$''\n   or coalesce(price#>>''{offer,priceUsdc6}'','''') !~ ''^[1-9][0-9]{0,15}$'' or coalesce(price#>>''{offer,expiresAt}'','''') !~ ''^[1-9][0-9]{0,15}$''\n   or (price#>>''{offer,expiresAt}'')::numeric<=floor(extract(epoch from (p_journal->>''admittedAt'')::timestamptz))\n   or (price#>>''{offer,expiresAt}'')::numeric<=floor(extract(epoch from clock_timestamp()))\n   or (price#>>''{offer,expiresAt}'')::numeric>9007199254740991 or (price#>>''{offer,createdAt}'')::timestamptz is null\n   or (price->>''amountMicros'')::numeric>(r->>''listPriceMicros'')::numeric\n   then raise exception ''browser source offer refused''; end if;\n else raise exception ''browser source price mode refused''; end if;\n path:=''/api/source/''||(c#>>''{source,sourceId}'')||''/item/''||public.browser_signing_source_urlencode(c#>>''{item,itemId}'',true)||''?version=''||public.browser_signing_source_urlencode(c#>>''{item,contentVersion}'',false);\n if price->>''mode''=''creator-offer'' then path:=path||''&offer=''||(price#>>''{offer,id}'')||''&listPriceUsdc6=''||(r->>''listPriceMicros''); end if;\n if c#>>''{endpoint,path}'' is distinct from path then raise exception ''browser source endpoint refused''; end if;\n -- Additionally bound the prepared timestamp to five seconds. Recheck its\n -- age after database lock waits; the separate original-token deadline is authoritative.\n if (p_journal->>''admittedAt'')::timestamptz>clock_timestamp()\n  or clock_timestamp()-(p_journal->>''admittedAt'')::timestamptz>=interval ''5 seconds''\n  then raise exception ''browser source observation expired''; end if;\nend ","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',227,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_signing_source_exposure_gate()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\nbegin\n -- A previously exposed v2 original retains its exact historical callback.\n if old.authorization_phase=''prepared'' and new.authorization_phase in (''exposed'',''signed'',''submission_attempted'')\n  and exists(select 1 from public.browser_signing_originals where nonce=old.authorization_id and original->>''protocol''=''durable-v3'')\n  and (public.browser_signing_original_floor_for_write()<>3 or (select active from public.browser_journal_control where id=1) is distinct from true\n    or (select active from public.browser_signing_v2_control where id=1) is distinct from true) then raise exception ''browser source exposure inactive''; end if;\n if old.authorization_phase=''prepared'' and new.authorization_phase in (''exposed'',''signed'',''submission_attempted'',''settled'',''failed'')\n  and public.browser_signing_original_floor_for_write()=3\n  and not exists(select 1 from public.browser_signing_originals where nonce=old.authorization_id and original->>''protocol''=''durable-v3'') then raise exception ''browser signing v3 source exposure required''; end if;\n return new;\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"browser_signing_source_exposure_gate","owner":"postgres","parallel":"u","result":"trigger","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\nbegin\n -- A previously exposed v2 original retains its exact historical callback.\n if old.authorization_phase=''prepared'' and new.authorization_phase in (''exposed'',''signed'',''submission_attempted'')\n  and exists(select 1 from public.browser_signing_originals where nonce=old.authorization_id and original->>''protocol''=''durable-v3'')\n  and (public.browser_signing_original_floor_for_write()<>3 or (select active from public.browser_journal_control where id=1) is distinct from true\n    or (select active from public.browser_signing_v2_control where id=1) is distinct from true) then raise exception ''browser source exposure inactive''; end if;\n if old.authorization_phase=''prepared'' and new.authorization_phase in (''exposed'',''signed'',''submission_attempted'',''settled'',''failed'')\n  and public.browser_signing_original_floor_for_write()=3\n  and not exists(select 1 from public.browser_signing_originals where nonce=old.authorization_id and original->>''protocol''=''durable-v3'') then raise exception ''browser signing v3 source exposure required''; end if;\n return new;\nend ","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',228,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_signing_source_original_gate()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\nbegin\n if (new.original->>''protocol''=''durable-v3'' or public.browser_signing_original_floor_for_write()=3)\n  and (new.original->>''protocol'' is distinct from ''durable-v3'' or not exists(select 1 from public.browser_signing_v3_writer where transaction_id=txid_current())) then raise exception ''browser signing v3 source original required''; end if;\n return new;\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"browser_signing_source_original_gate","owner":"postgres","parallel":"u","result":"trigger","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\nbegin\n if (new.original->>''protocol''=''durable-v3'' or public.browser_signing_original_floor_for_write()=3)\n  and (new.original->>''protocol'' is distinct from ''durable-v3'' or not exists(select 1 from public.browser_signing_v3_writer where transaction_id=txid_current())) then raise exception ''browser signing v3 source original required''; end if;\n return new;\nend ","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',229,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_value text, p_component boolean","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_signing_source_urlencode(p_value text, p_component boolean)\n RETURNS text\n LANGUAGE plpgsql\n IMMUTABLE STRICT\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare bytes bytea:=convert_to(p_value,''UTF8''); i integer; b integer; result text:=''''; ch text;\nbegin\n for i in 0..length(bytes)-1 loop\n  b:=get_byte(bytes,i); ch:=chr(b);\n  if (b between 48 and 57) or (b between 65 and 90) or (b between 97 and 122)\n   or (p_component and ch in (''-'',''_'',''.'',''!'',''~'',''*'','''''''',''('','')'')) or (not p_component and ch in (''*'',''-'',''.'',''_'')) then result:=result||ch;\n  elsif not p_component and b=32 then result:=result||''+'';\n  else result:=result||''%''||substr(''0123456789ABCDEF'',b/16+1,1)||substr(''0123456789ABCDEF'',b%16+1,1); end if;\n end loop;\n return result;\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"browser_signing_source_urlencode","owner":"postgres","parallel":"u","result":"text","returnsSet":false,"rows":"0","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare bytes bytea:=convert_to(p_value,''UTF8''); i integer; b integer; result text:=''''; ch text;\nbegin\n for i in 0..length(bytes)-1 loop\n  b:=get_byte(bytes,i); ch:=chr(b);\n  if (b between 48 and 57) or (b between 65 and 90) or (b between 97 and 122)\n   or (p_component and ch in (''-'',''_'',''.'',''!'',''~'',''*'','''''''',''('','')'')) or (not p_component and ch in (''*'',''-'',''.'',''_'')) then result:=result||ch;\n  elsif not p_component and b=32 then result:=result||''+'';\n  else result:=result||''%''||substr(''0123456789ABCDEF'',b/16+1,1)||substr(''0123456789ABCDEF'',b%16+1,1); end if;\n end loop;\n return result;\nend ","strict":true,"support":null,"volatility":"i"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',230,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_input jsonb, p_journal jsonb, p_original jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_signing_v2_admission_internal(p_input jsonb, p_journal jsonb, p_original jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare ns text:=p_input->>''queryNamespace''; qid text:=p_input->>''queryId''; a jsonb:=p_input->''journal'';\n q public.browser_signing_queries%rowtype; n public.browser_signing_namespaces%rowtype; old public.browser_signing_originals%rowtype;\n p jsonb; g public.session_grants%rowtype; intent jsonb; amount bigint; seconds bigint; result text;\nbegin\n if (select active from public.browser_signing_v2_control where id=1) is distinct from true\n  or (select active from public.browser_journal_control where id=1) is distinct from true then return jsonb_build_object(''status'',''inactive''); end if;\n perform pg_advisory_xact_lock(hashtextextended(ns,0));\n select * into old from public.browser_signing_originals where session_id=a->>''sessionId'' and request_id=a->>''requestId'';\n if found then\n  if old.input is distinct from p_input then raise exception ''browser signing original conflict''; end if;\n  select owner into n.owner from public.browser_signing_namespaces where namespace=old.namespace;\n  return jsonb_build_object(''status'',''admitted'',''snapshot'',public.browser_signing_snapshot(n.owner,old.session_id,old.request_id));\n end if;\n select * into q from public.browser_signing_queries where namespace=ns and query_id=qid for update;\n if not found then return jsonb_build_object(''status'',''refused''); end if;\n select * into n from public.browser_signing_namespaces where namespace=ns for update;\n select verified->''policy'' into p from public.browser_signing_policies where namespace=ns and policy_id=q.policy_id;\n select * into g from public.session_grants where session_id=a->>''sessionId'' for update;\n if not found or q.session_id is distinct from a->>''sessionId'' or g.grant_epoch is distinct from p->>''grantEpoch''\n  or a->>''grantEpoch'' is distinct from p->>''grantEpoch'' or lower(g.owner_addr) is distinct from n.owner or lower(g.sess_addr) is distinct from n.signer\n  or g.expiry<=(extract(epoch from clock_timestamp())*1000)::bigint or (p->>''expiresAt'')::bigint<=(extract(epoch from clock_timestamp())*1000)::bigint then return jsonb_build_object(''status'',''refused''); end if;\n if a->>''queryId'' is distinct from qid or p_journal->>''sessionId'' is distinct from a->>''sessionId''\n  or p_journal->>''requestId'' is distinct from a->>''requestId'' or p_journal->>''grantEpoch'' is distinct from a->>''grantEpoch''\n  or lower(a->>''signer'') is distinct from n.signer or lower(p_journal->>''signer'') is distinct from n.signer\n  or p_journal->''requirements'' is distinct from a->''requirements'' or p_journal->>''phase'' is distinct from ''prepared''\n  or p_journal#>>''{payment,queryId}'' is distinct from qid\n  or ((p_journal->''payment'')-array[''id'',''createdAt'',''settled'',''settlementStatus'',''authorizationId'',''authorizationPhase'']) is distinct from a->''payment''\n  then raise exception ''browser signing journal differs''; end if;\n amount:=(a->>''amountMicroUsdc'')::bigint; seconds:=floor(extract(epoch from (p_journal->>''admittedAt'')::timestamptz))::bigint;\n if amount<1 or amount>9007199254740991 or seconds<600 then raise exception ''browser signing original refused''; end if;\n if q.spent_micro+amount>q.ceiling_micro then return jsonb_build_object(''status'',''refused''); end if;\n if p_original is distinct from jsonb_build_object(''protocol'',''durable-v2'',''admittedAt'',p_journal->>''admittedAt'',''namespace'',ns,''queryId'',qid,\n  ''requestId'',a->>''requestId'',''grantEpoch'',a->>''grantEpoch'',''domain'',jsonb_build_object(''name'',''GatewayWalletBatched'',''version'',''1'',''chainId'',5042002,''verifyingContract'',''0x0077777d7eba4688bdef3e311b846f25870a19b9''),\n  ''authorization'',jsonb_build_object(''from'',n.signer,''to'',lower(a->>''payee''),''value'',amount::text,''validAfter'',(seconds-600)::text,\n    ''validBefore'',(seconds+(a#>>''{requirements,maxTimeoutSeconds}'')::bigint)::text,''nonce'',p_journal->>''nonce'')) then raise exception ''browser signing original differs''; end if;\n intent:=jsonb_build_object(''nonce'',p_journal->>''nonce'',''session_id'',a->>''sessionId'',''request_id'',a->>''requestId'',''query_id'',qid,''grant_epoch'',a->>''grantEpoch'',\n  ''signer'',n.signer,''network'',a->>''network'',''token'',a->>''token'',''gateway_contract'',a->>''gatewayContract'',''source_id'',a->>''sourceId'',''offer_id'',a->''offerId'',''kind'',a->>''kind'',''payee'',a->>''payee'',''amount_micro_usdc'',amount::text,''created_at'',p_journal->>''admittedAt'');\n insert into public.browser_signing_v2_writer values(txid_current());\n result:=public.admit_browser_journal(intent,p_journal->''requirements'',p_journal->''payment'');\n delete from public.browser_signing_v2_writer where transaction_id=txid_current();\n if result<>''admitted'' then return jsonb_build_object(''status'',''refused''); end if;\n insert into public.browser_signing_originals values(p_journal->>''nonce'',ns,qid,p_input,p_journal,p_original,a->>''sessionId'',a->>''requestId'');\n update public.browser_signing_queries set spent_micro=spent_micro+amount where namespace=ns and query_id=qid;\n return jsonb_build_object(''status'',''admitted'',''snapshot'',public.browser_signing_snapshot(n.owner,a->>''sessionId'',a->>''requestId''));\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"browser_signing_v2_admission_internal","owner":"postgres","parallel":"u","result":"jsonb","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare ns text:=p_input->>''queryNamespace''; qid text:=p_input->>''queryId''; a jsonb:=p_input->''journal'';\n q public.browser_signing_queries%rowtype; n public.browser_signing_namespaces%rowtype; old public.browser_signing_originals%rowtype;\n p jsonb; g public.session_grants%rowtype; intent jsonb; amount bigint; seconds bigint; result text;\nbegin\n if (select active from public.browser_signing_v2_control where id=1) is distinct from true\n  or (select active from public.browser_journal_control where id=1) is distinct from true then return jsonb_build_object(''status'',''inactive''); end if;\n perform pg_advisory_xact_lock(hashtextextended(ns,0));\n select * into old from public.browser_signing_originals where session_id=a->>''sessionId'' and request_id=a->>''requestId'';\n if found then\n  if old.input is distinct from p_input then raise exception ''browser signing original conflict''; end if;\n  select owner into n.owner from public.browser_signing_namespaces where namespace=old.namespace;\n  return jsonb_build_object(''status'',''admitted'',''snapshot'',public.browser_signing_snapshot(n.owner,old.session_id,old.request_id));\n end if;\n select * into q from public.browser_signing_queries where namespace=ns and query_id=qid for update;\n if not found then return jsonb_build_object(''status'',''refused''); end if;\n select * into n from public.browser_signing_namespaces where namespace=ns for update;\n select verified->''policy'' into p from public.browser_signing_policies where namespace=ns and policy_id=q.policy_id;\n select * into g from public.session_grants where session_id=a->>''sessionId'' for update;\n if not found or q.session_id is distinct from a->>''sessionId'' or g.grant_epoch is distinct from p->>''grantEpoch''\n  or a->>''grantEpoch'' is distinct from p->>''grantEpoch'' or lower(g.owner_addr) is distinct from n.owner or lower(g.sess_addr) is distinct from n.signer\n  or g.expiry<=(extract(epoch from clock_timestamp())*1000)::bigint or (p->>''expiresAt'')::bigint<=(extract(epoch from clock_timestamp())*1000)::bigint then return jsonb_build_object(''status'',''refused''); end if;\n if a->>''queryId'' is distinct from qid or p_journal->>''sessionId'' is distinct from a->>''sessionId''\n  or p_journal->>''requestId'' is distinct from a->>''requestId'' or p_journal->>''grantEpoch'' is distinct from a->>''grantEpoch''\n  or lower(a->>''signer'') is distinct from n.signer or lower(p_journal->>''signer'') is distinct from n.signer\n  or p_journal->''requirements'' is distinct from a->''requirements'' or p_journal->>''phase'' is distinct from ''prepared''\n  or p_journal#>>''{payment,queryId}'' is distinct from qid\n  or ((p_journal->''payment'')-array[''id'',''createdAt'',''settled'',''settlementStatus'',''authorizationId'',''authorizationPhase'']) is distinct from a->''payment''\n  then raise exception ''browser signing journal differs''; end if;\n amount:=(a->>''amountMicroUsdc'')::bigint; seconds:=floor(extract(epoch from (p_journal->>''admittedAt'')::timestamptz))::bigint;\n if amount<1 or amount>9007199254740991 or seconds<600 then raise exception ''browser signing original refused''; end if;\n if q.spent_micro+amount>q.ceiling_micro then return jsonb_build_object(''status'',''refused''); end if;\n if p_original is distinct from jsonb_build_object(''protocol'',''durable-v2'',''admittedAt'',p_journal->>''admittedAt'',''namespace'',ns,''queryId'',qid,\n  ''requestId'',a->>''requestId'',''grantEpoch'',a->>''grantEpoch'',''domain'',jsonb_build_object(''name'',''GatewayWalletBatched'',''version'',''1'',''chainId'',5042002,''verifyingContract'',''0x0077777d7eba4688bdef3e311b846f25870a19b9''),\n  ''authorization'',jsonb_build_object(''from'',n.signer,''to'',lower(a->>''payee''),''value'',amount::text,''validAfter'',(seconds-600)::text,\n    ''validBefore'',(seconds+(a#>>''{requirements,maxTimeoutSeconds}'')::bigint)::text,''nonce'',p_journal->>''nonce'')) then raise exception ''browser signing original differs''; end if;\n intent:=jsonb_build_object(''nonce'',p_journal->>''nonce'',''session_id'',a->>''sessionId'',''request_id'',a->>''requestId'',''query_id'',qid,''grant_epoch'',a->>''grantEpoch'',\n  ''signer'',n.signer,''network'',a->>''network'',''token'',a->>''token'',''gateway_contract'',a->>''gatewayContract'',''source_id'',a->>''sourceId'',''offer_id'',a->''offerId'',''kind'',a->>''kind'',''payee'',a->>''payee'',''amount_micro_usdc'',amount::text,''created_at'',p_journal->>''admittedAt'');\n insert into public.browser_signing_v2_writer values(txid_current());\n result:=public.admit_browser_journal(intent,p_journal->''requirements'',p_journal->''payment'');\n delete from public.browser_signing_v2_writer where transaction_id=txid_current();\n if result<>''admitted'' then return jsonb_build_object(''status'',''refused''); end if;\n insert into public.browser_signing_originals values(p_journal->>''nonce'',ns,qid,p_input,p_journal,p_original,a->>''sessionId'',a->>''requestId'');\n update public.browser_signing_queries set spent_micro=spent_micro+amount where namespace=ns and query_id=qid;\n return jsonb_build_object(''status'',''admitted'',''snapshot'',public.browser_signing_snapshot(n.owner,a->>''sessionId'',a->>''requestId''));\nend ","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',231,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_signing_validity_gate()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare o jsonb; begin\n select original into o from public.browser_signing_originals where nonce=new.nonce;\n if o is not null and new.header_hash is not null and not exists(select 1 from public.browser_signing_v2_writer where transaction_id=txid_current()) then\n  raise exception ''browser signing canonical callback required'';\n end if;\n if o is not null and ((new.valid_after is not null and new.valid_after is distinct from o#>>''{authorization,validAfter}'')\n   or (new.valid_before is not null and new.valid_before is distinct from o#>>''{authorization,validBefore}'')) then raise exception ''browser signing original validity differs''; end if;\n return new;\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"browser_signing_validity_gate","owner":"postgres","parallel":"u","result":"trigger","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare o jsonb; begin\n select original into o from public.browser_signing_originals where nonce=new.nonce;\n if o is not null and new.header_hash is not null and not exists(select 1 from public.browser_signing_v2_writer where transaction_id=txid_current()) then\n  raise exception ''browser signing canonical callback required'';\n end if;\n if o is not null and ((new.valid_after is not null and new.valid_after is distinct from o#>>''{authorization,validAfter}'')\n   or (new.valid_before is not null and new.valid_before is distinct from o#>>''{authorization,validBefore}'')) then raise exception ''browser signing original validity differs''; end if;\n return new;\nend ","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',232,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION keryx_storage.cache_quota_write()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare retained keryx_storage.cache_quota%rowtype;\n  selected_identity jsonb;\n  old_count bigint := 0; old_bytes bigint := 0; new_count bigint := 0; new_bytes bigint := 0;\nbegin\n  if tg_op=''TRUNCATE'' then raise exception ''storage cache truncate refused''; end if;\n  -- This same singleton serializes replacements, inserts and deletes; a stale\n  -- REPEATABLE READ writer must serialize/refuse rather than overwrite totals.\n  select * into retained from keryx_storage.cache_quota where singleton for update;\n  if not found then raise exception ''storage cache quota refused''; end if;\n  if tg_op in (''UPDATE'',''DELETE'') and old.text is not null then\n    old_count := 1; old_bytes := octet_length(old.text);\n  end if;\n  if tg_op in (''UPDATE'',''INSERT'') and new.text is not null then\n    if char_length(new.source_id) not between 1 and 256 or octet_length(new.source_id)>512\n      or (select sum(case when ascii(substr(new.source_id,i,1))>65535 then 2 else 1 end)\n        from generate_series(1,char_length(new.source_id)) i)>256\n      or octet_length(new.text)>2097152 then raise exception ''storage cache quota refused''; end if;\n    new_count := 1; new_bytes := octet_length(new.text);\n    select identity into selected_identity from keryx_storage.identity where singleton;\n    if not found then raise exception ''storage cache identity refused''; end if;\n    perform keryx_storage.validate_cache_wire(new.source_id,new.text,selected_identity);\n  end if;\n  if retained.row_count-old_count+new_count not between 0 and 512\n    or retained.wire_bytes-old_bytes+new_bytes not between 0 and 8388608 then\n    raise exception ''storage cache quota refused'';\n  end if;\n  update keryx_storage.cache_quota set row_count=retained.row_count-old_count+new_count,\n    wire_bytes=retained.wire_bytes-old_bytes+new_bytes where singleton;\n  if tg_op=''DELETE'' then return old; end if;\n  return new;\nend; $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"cache_quota_write","owner":"postgres","parallel":"u","result":"trigger","returnsSet":false,"rows":"0","schema":"keryx_storage","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare retained keryx_storage.cache_quota%rowtype;\n  selected_identity jsonb;\n  old_count bigint := 0; old_bytes bigint := 0; new_count bigint := 0; new_bytes bigint := 0;\nbegin\n  if tg_op=''TRUNCATE'' then raise exception ''storage cache truncate refused''; end if;\n  -- This same singleton serializes replacements, inserts and deletes; a stale\n  -- REPEATABLE READ writer must serialize/refuse rather than overwrite totals.\n  select * into retained from keryx_storage.cache_quota where singleton for update;\n  if not found then raise exception ''storage cache quota refused''; end if;\n  if tg_op in (''UPDATE'',''DELETE'') and old.text is not null then\n    old_count := 1; old_bytes := octet_length(old.text);\n  end if;\n  if tg_op in (''UPDATE'',''INSERT'') and new.text is not null then\n    if char_length(new.source_id) not between 1 and 256 or octet_length(new.source_id)>512\n      or (select sum(case when ascii(substr(new.source_id,i,1))>65535 then 2 else 1 end)\n        from generate_series(1,char_length(new.source_id)) i)>256\n      or octet_length(new.text)>2097152 then raise exception ''storage cache quota refused''; end if;\n    new_count := 1; new_bytes := octet_length(new.text);\n    select identity into selected_identity from keryx_storage.identity where singleton;\n    if not found then raise exception ''storage cache identity refused''; end if;\n    perform keryx_storage.validate_cache_wire(new.source_id,new.text,selected_identity);\n  end if;\n  if retained.row_count-old_count+new_count not between 0 and 512\n    or retained.wire_bytes-old_bytes+new_bytes not between 0 and 8388608 then\n    raise exception ''storage cache quota refused'';\n  end if;\n  update keryx_storage.cache_quota set row_count=retained.row_count-old_count+new_count,\n    wire_bytes=retained.wire_bytes-old_bytes+new_bytes where singleton;\n  if tg_op=''DELETE'' then return old; end if;\n  return new;\nend; ","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',233,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION keryx_storage.catalog_contract()\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\n\ndeclare result jsonb; bytes bigint; rows_count bigint;\nbegin\n  if current_setting(''server_version_num'')::integer/10000<>17 then raise exception ''unsupported schema contract version''; end if;\n  if exists(select 1 from pg_namespace where nspname not in (''public'',''keryx_storage'',''information_schema'')\n    and nspname !~ ''^pg_'') then raise exception ''unsupported schema contract namespace''; end if;\n  -- Reviewed migrations do not define foreign objects/custom operator families.\n  -- Refuse these rather than silently omitting their security semantics.\n  if exists(select 1 from pg_foreign_table f join pg_class c on c.oid=f.ftrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in (''public'',''keryx_storage''))\n    or exists(select 1 from pg_operator o join pg_namespace n on n.oid=o.oprnamespace where n.nspname in (''public'',''keryx_storage''))\n    or exists(select 1 from pg_opclass o join pg_namespace n on n.oid=o.opcnamespace where n.nspname in (''public'',''keryx_storage''))\n    or exists(select 1 from pg_opfamily o join pg_namespace n on n.oid=o.opfnamespace where n.nspname in (''public'',''keryx_storage''))\n    or exists(select 1 from pg_conversion o join pg_namespace n on n.oid=o.connamespace where n.nspname in (''public'',''keryx_storage''))\n    or exists(select 1 from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in (''public'',''keryx_storage'') and t.typtype in (''r'',''m''))\n    then raise exception ''unsupported schema contract object''; end if;\n  if (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in (''public'',''keryx_storage''))>512\n    or (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in (''public'',''keryx_storage''))>512\n    or (select count(*) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in (''public'',''keryx_storage'') and a.attnum>0)>4096\n    or (select count(*) from pg_roles)>128 then raise exception ''schema contract count bound''; end if;\n  if (select count(*) from (\n    select c.oid from pg_constraint c join pg_namespace n on n.oid=c.connamespace where n.nspname in (''public'',''keryx_storage'')\n    union all select t.oid from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in (''public'',''keryx_storage'')\n    union all select t.oid from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in (''public'',''keryx_storage'')\n    union all select p.oid from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in (''public'',''keryx_storage'')\n    union all select oid from pg_auth_members\n    union all select oid from pg_default_acl\n    union all select r.oid from pg_rewrite r join pg_class c on c.oid=r.ev_class join pg_namespace n on n.oid=c.relnamespace where n.nspname in (''public'',''keryx_storage'')\n    union all select e.oid from pg_enum e join pg_type t on t.oid=e.enumtypid join pg_namespace n on n.oid=t.typnamespace where n.nspname in (''public'',''keryx_storage'')\n  ) raw_metadata)>16384 then raise exception ''schema contract count bound''; end if;\n  with fields as (\n    select octet_length(d.adbin::text) bytes from pg_attrdef d join pg_class c on c.oid=d.adrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in (''public'',''keryx_storage'')\n    -- Budget encoded trigger arguments at TWO bytes per raw byte, without first\n    -- allocating hex text. Qualifier nodes are measured before any deparsing.\n    union all select 2::bigint*octet_length(t.tgargs)::bigint+octet_length(coalesce(t.tgqual::text,''''))::bigint from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in (''public'',''keryx_storage'')\n    union all select octet_length(coalesce(x.conbin::text,'''')) from pg_constraint x join pg_namespace n on n.oid=x.connamespace where n.nspname in (''public'',''keryx_storage'')\n    union all select octet_length(coalesce(c.reloptions::text,''''))+octet_length(coalesce(c.relacl::text,'''')) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in (''public'',''keryx_storage'')\n    union all select octet_length(coalesce(p.polqual::text,''''))+octet_length(coalesce(p.polwithcheck::text,'''')) from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in (''public'',''keryx_storage'')\n    union all select octet_length(r.ev_action::text)+octet_length(r.ev_qual::text) from pg_rewrite r join pg_class c on c.oid=r.ev_class join pg_namespace n on n.oid=c.relnamespace where n.nspname in (''public'',''keryx_storage'')\n    union all select octet_length(coalesce(r.rolconfig::text,'''')) from pg_roles r\n    union all select octet_length(coalesce(s.setconfig::text,'''')) from pg_db_role_setting s\n    union all select octet_length(d.defaclacl::text) from pg_default_acl d\n    union all select octet_length(coalesce(t.typdefault,''''))+octet_length(coalesce(t.typacl::text,'''')) from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in (''public'',''keryx_storage'')\n  ) select count(*),coalesce(sum(fields.bytes),0) into rows_count,bytes from fields having coalesce(max(fields.bytes),0)<=131072;\n  if rows_count is null or rows_count>16384 or bytes>8388608 then raise exception ''schema contract raw field bound''; end if;\n  -- Raw stored fields are bounded BEFORE pg_get_* deparsing/json aggregation.\n  if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in (''public'',''keryx_storage'')\n      and (octet_length(p.prosrc)>131072 or octet_length(coalesce(p.probin,''''))>131072\n        or octet_length(coalesce(p.proconfig::text,''''))>131072))\n    or (select coalesce(sum(octet_length(p.prosrc)+octet_length(coalesce(p.probin,''''))+octet_length(coalesce(p.proconfig::text,''''))),0)\n      from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in (''public'',''keryx_storage''))>8388608\n    then raise exception ''schema contract source bound''; end if;\n  -- Each descriptor row is checked before the final aggregate. The second pass is\n  -- coherent under the enclosing transaction snapshot; caller must retain that scope.\n  with entries as (select ''database'' section,value from (select jsonb_build_object(''encoding'',pg_encoding_to_char(d.encoding),''collate'',d.datcollate,\n    ''ctype'',d.datctype,''localeProvider'',d.datlocprovider,''locale'',d.datlocale,\n    ''icuRules'',d.daticurules,''collationVersion'',d.datcollversion,\n    ''actualCollationVersion'',pg_database_collation_actual_version(d.oid),''allowConnections'',d.datallowconn,\n    ''connectionLimit'',d.datconnlimit,''owner'',pg_get_userbyid(d.datdba),''acl'',jsonb_build_object(''explicit'',d.datacl is not null,''grants'',\n    (select coalesce(jsonb_agg(jsonb_build_object(''grantor'',pg_get_userbyid(z.grantor),\n      ''grantee'',case when z.grantee=0 then ''PUBLIC'' else pg_get_userbyid(z.grantee) end,\n      ''privilege'',z.privilege_type,''grantable'',z.is_grantable)\n      order by pg_get_userbyid(z.grantor),case when z.grantee=0 then ''PUBLIC'' else pg_get_userbyid(z.grantee) end,z.privilege_type,z.is_grantable),''[]''::jsonb)\n     from aclexplode(coalesce(d.datacl,acldefault(''d'',d.datdba))) z))) value\n    from pg_database d where d.datname=current_database()) d\nunion all\nselect ''schemas'' section,value from (select jsonb_build_object(''name'',n.nspname,''owner'',pg_get_userbyid(n.nspowner),''acl'',jsonb_build_object(''explicit'',n.nspacl is not null,''grants'',\n    (select coalesce(jsonb_agg(jsonb_build_object(''grantor'',pg_get_userbyid(z.grantor),\n      ''grantee'',case when z.grantee=0 then ''PUBLIC'' else pg_get_userbyid(z.grantee) end,\n      ''privilege'',z.privilege_type,''grantable'',z.is_grantable)\n      order by pg_get_userbyid(z.grantor),case when z.grantee=0 then ''PUBLIC'' else pg_get_userbyid(z.grantee) end,z.privilege_type,z.is_grantable),''[]''::jsonb)\n     from aclexplode(coalesce(n.nspacl,acldefault(''n'',n.nspowner))) z))) value\n    from pg_namespace n where n.nspname in (''public'',''keryx_storage'')) d\nunion all\nselect ''relations'' section,value from (select jsonb_build_object(''schema'',n.nspname,''name'',c.relname,''kind'',c.relkind,\n    ''persistence'',c.relpersistence,''owner'',pg_get_userbyid(c.relowner),''acl'',jsonb_build_object(''explicit'',c.relacl is not null,''grants'',\n    (select coalesce(jsonb_agg(jsonb_build_object(''grantor'',pg_get_userbyid(z.grantor),\n      ''grantee'',case when z.grantee=0 then ''PUBLIC'' else pg_get_userbyid(z.grantee) end,\n      ''privilege'',z.privilege_type,''grantable'',z.is_grantable)\n      order by pg_get_userbyid(z.grantor),case when z.grantee=0 then ''PUBLIC'' else pg_get_userbyid(z.grantee) end,z.privilege_type,z.is_grantable),''[]''::jsonb)\n     from aclexplode(coalesce(c.relacl,acldefault(case when c.relkind=''S'' then ''s''::\"char\" else ''r''::\"char\" end,c.relowner))) z)),\n    ''options'',c.reloptions,''rowSecurity'',c.relrowsecurity,''forceRowSecurity'',c.relforcerowsecurity,\n    ''replicaIdentity'',c.relreplident,''accessMethod'',am.amname,''partition'',pg_get_expr(c.relpartbound,c.oid),\n    ''partitionKey'',pg_get_partkeydef(c.oid),\n    ''view'',case when c.relkind in (''v'',''m'') then pg_get_viewdef(c.oid,false) else null end) value\n    from pg_class c j