('before','functions',242,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_epoch text, p_signer text, p_amount bigint","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.release_browser_journal_capacity(p_epoch text, p_signer text, p_amount bigint)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare n integer; v_spent bigint;\nbegin\n  update public.browser_retained_grants set spent_micro=spent_micro-p_amount where grant_epoch=p_epoch and signer=lower(p_signer) and spent_micro>=p_amount;\n  get diagnostics n=row_count; if n<>1 then raise exception ''Retained grant capacity mismatch''; end if;\n  update public.browser_signer_capacity set spent_micro=spent_micro-p_amount where signer=lower(p_signer) and spent_micro>=p_amount returning spent_micro into v_spent;\n  if not found then raise exception ''Signer capacity mismatch''; end if;\n  update public.session_grants set spent=v_spent::numeric/1000000 where lower(sess_addr)=lower(p_signer);\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"release_browser_journal_capacity","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare n integer; v_spent bigint;\nbegin\n  update public.browser_retained_grants set spent_micro=spent_micro-p_amount where grant_epoch=p_epoch and signer=lower(p_signer) and spent_micro>=p_amount;\n  get diagnostics n=row_count; if n<>1 then raise exception ''Retained grant capacity mismatch''; end if;\n  update public.browser_signer_capacity set spent_micro=spent_micro-p_amount where signer=lower(p_signer) and spent_micro>=p_amount returning spent_micro into v_spent;\n  if not found then raise exception ''Signer capacity mismatch''; end if;\n  update public.session_grants set spent=v_spent::numeric/1000000 where lower(sess_addr)=lower(p_signer);\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',243,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_expected_identity jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION keryx_storage.require_identity(p_expected_identity jsonb)\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare record keryx_storage.identity%rowtype;\nbegin\n  -- This inspects the actual outer statement setting before any catalog/lock work.\n  if current_setting(''statement_timeout'')::interval<=interval ''0''\n    or current_setting(''statement_timeout'')::interval>interval ''30 seconds'' then\n    raise exception ''bounded storage statement deadline required'';\n  end if;\n  perform keryx_storage.validate_identity(p_expected_identity);\n  select * into record from keryx_storage.identity where singleton;\n  if not found then raise exception ''storage identity refused: enrollment_required''; end if;\n  if record.identity is distinct from p_expected_identity\n    or record.identity_digest is distinct from keryx_storage.identity_digest(p_expected_identity) then\n    raise exception ''storage identity refused: identity_mismatch'';\n  end if;\n  perform pg_advisory_xact_lock_shared(634781904177021::bigint);\n  select * into record from keryx_storage.identity where singleton for share;\n  if not found then raise exception ''storage identity refused: enrollment_required''; end if;\n  if record.identity is distinct from p_expected_identity\n     or record.identity_digest is distinct from keryx_storage.identity_digest(p_expected_identity) then\n    raise exception ''storage identity refused: identity_mismatch'';\n  end if;\n  perform keryx_storage.verify_fences();\n  return record.identity_digest;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"require_identity","owner":"postgres","parallel":"u","result":"text","returnsS