ke ''pg\\_%'' escape ''\\'' and n.nspname<>''information_schema''\n    union all select ''collation:''||encode(sha256(convert_to(c::text,''UTF8'')),''hex'') from pg_collation c\n    union all select ''index:''||encode(sha256(convert_to(i::text,''UTF8'')),''hex'') from pg_index i join pg_class c on c.oid=i.indexrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname not like ''pg\\_%'' escape ''\\'' and n.nspname<>''information_schema''\n    union all select ''default:''||encode(sha256(convert_to(d::text,''UTF8'')),''hex'') from pg_attrdef d join pg_class c on c.oid=d.adrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname not like ''pg\\_%'' escape ''\\'' and n.nspname<>''information_schema''\n    union all select ''rule:''||encode(sha256(convert_to(r::text,''UTF8'')),''hex'') from pg_rewrite r join pg_class c on c.oid=r.ev_class join pg_namespace n on n.oid=c.relnamespace where n.nspname not like ''pg\\_%'' escape ''\\'' and n.nspname<>''information_schema''\n    union all select ''sequence-definition:''||encode(sha256(convert_to(s::text,''UTF8'')),''hex'') from pg_sequence s join pg_class c on c.oid=s.seqrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname not like ''pg\\_%'' escape ''\\'' and n.nspname<>''information_schema''\n    union all select ''extension:''||encode(sha256(convert_to(e::text,''UTF8'')),''hex'') from pg_extension e\n    union all select ''grant-default:''||encode(sha256(convert_to(d::text,''UTF8'')),''hex'') from pg_default_acl d\n    union all select ''role:''||encode(sha256(convert_to(r::text,''UTF8'')),''hex'') from pg_roles r\n    union all select ''membership:''||encode(sha256(convert_to(m::text,''UTF8'')),''hex'') from pg_auth_members m\n  ) pieces;\n  return encode(sha256(convert_to(''keryx-postgres-provenance-v1''||E''\\n''||manifest||catalog_digest,''UTF8'')),''hex'');\nend; ","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',247,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION keryx_storage.source_contract_insert_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\nbegin\n  if exists(select 1 from keryx_storage.identity) or exists(select 1 from keryx_storage.enrolled_schema) then\n    raise exception ''published source contract is immutable'';\n  end if;\n  return new;\nend; $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"source_contract_insert_guard","owner":"postgres","parallel":"u","result":"trigger","returnsSet":false,"rows":"0","schema":"keryx_storage","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\nbegin\n  if exists(select 1 from keryx_storage.identity) or exists(select 1 from keryx_storage.enrolled_schema) then\n    raise exception ''published source contract is immutable'';\n  end if;\n  return new;\nend; ","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',248,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_source_id text, p_text text, p_identity jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION keryx_storage.validate_cache_wire(p_source_id text, p_text text, p_identity jsonb)\n RETURNS void\n LANGUAGE plpgsql\n IMMUTABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare wire text; decoded text; envelope jsonb; k text; field text; bytes bytea;\nbegin\n  if p_identity->>''authorityMode''=''testnet-offline'' then\n    if left(p_text,9)<>''plain:v1:'' or octet_length(p_text)>1048576+9 then raise exception ''storage cache format refused''; end if;\n    return;\n  end if;\n  if left(p_text,7)<>''enc:v3:'' or octet_length(p_text)>2097152 then raise exception ''storage cache format refused''; end if;\n  wire := substr(p_text,8);\n  if wire !~ ''^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$'' then raise exception ''storage cache format refused''; end if;\n  bytes := decode(wire,''base64'');\n  if replace(encode(bytes,''base64''),E''\\n'','''')<>wire then raise exception ''storage cache format refused''; end if;\n  decoded := convert_from(bytes,''UTF8''); envelope := decoded::jsonb;\n  if jsonb_typeof(envelope) is distinct from ''object''\n    or public.browser_signing_source_canonical(envelope)<>decoded\n    or (select array_agg(key order by key) from jsonb_object_keys(envelope) key)\n      is distinct from array[''authTagB64'',''cipherB64'',''format'',''ivB64'',''sourceId'',''storageIdentityDigest'',''wrapIvB64'',''wrappedKeyB64'']::text[]\n    or envelope->>''format''<>''keryx-enrolled-cache-v1'' or envelope->>''sourceId'' is distinct from p_source_id\n    or envelope->>''storageIdentityDigest'' is distinct from keryx_storage.identity_digest(p_identity) then\n    raise exception ''storage cache context refused'';\n  end if;\n  foreach k in array array[''format'',''sourceId'',''storageIdentityDigest'',''cipherB64'',''ivB64'',''authTagB64'',''wrappedKeyB64'',''wrapIvB64''] loop\n    if jsonb_typeof(envelope->k) is distinct from ''string'' then raise exception ''storage cache format refused''; end if;\n  end loop;\n  foreach k in array array[''cipherB64'',''ivB64'',''authTagB64'',''wrappedKeyB64'',''wrapIvB64''] loop\n    field := envelope->>k;\n    if field !~ ''^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$'' then raise exception ''storage cache format refused''; end if;\n    bytes := decode(field,''base64'');\n    if replace(encode(bytes,''base64''),E''\\n'','''')<>field or\n      (k=''cipherB64'' and octet_length(bytes)>1048576) or\n      (k in (''ivB64'',''wrapIvB64'') and octet_length(bytes)<>12) or\n      (k=''authTagB64'' and octet_length(bytes)<>16) or\n      (k=''wrappedKeyB64'' and octet_length(bytes)<>48) then raise exception ''storage cache format refused''; end if;\n  end loop;\nend; $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"validate_cache_wire","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"keryx_storage","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare wire text; decoded text; envelope jsonb; k text; field text; bytes bytea;\nbegin\n  if p_identity->>''authorityMode''=''testnet-offline'' then\n    if left(p_text,9)<>''plain:v1:'' or octet_length(p_text)>1048576+9 then raise exception ''storage cache format refused''; end if;\n    return;\n  end if;\n  if left(p_text,7)<>''enc:v3:'' or octet_length(p_text)>2097152 then raise exception ''storage cache format refused''; end if;\n  wire := substr(p_text,8);\n  if wire !~ ''^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$'' then raise exception ''storage cache format refused''; end if;\n  bytes := decode(wire,''base64'');\n  if replace(encode(bytes,''base64''),E''\\n'','''')<>wire then raise exception ''storage cache format refused''; end if;\n  decoded := convert_from(bytes,''UTF8''); envelope := decoded::jsonb;\n  if jsonb_typeof(envelope) is distinct from ''object''\n    or public.browser_signing_source_canonical(envelope)<>decoded\n    or (select array_agg(key order by key) from jsonb_object_keys(envelope) key)\n      is distinct from array[''authTagB64'',''cipherB64'',''format'',''ivB64'',''sourceId'',''storageIdentityDigest'',''wrapIvB64'',''wrappedKeyB64'']::text[]\n    or envelope->>''format''<>''keryx-enrolled-cache-v1'' or envelope->>''sourceId'' is distinct from p_source_id\n    or envelope->>''storageIdentityDigest'' is distinct from keryx_storage.identity_digest(p_identity) then\n    raise exception ''storage cache context refused'';\n  end if;\n  foreach k in array array[''format'',''sourceId'',''storageIdentityDigest'',''cipherB64'',''ivB64'',''authTagB64'',''wrappedKeyB64'',''wrapIvB64''] loop\n    if jsonb_typeof(envelope->k) is distinct from ''string'' then raise exception ''storage cache format refused''; end if;\n  end loop;\n  foreach k in array array[''cipherB64'',''ivB64'',''authTagB64'',''wrappedKeyB64'',''wrapIvB64''] loop\n    field := envelope->>k;\n    if field !~ ''^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$'' then raise exception ''storage cache format refused''; end if;\n    bytes := decode(field,''base64'');\n    if replace(encode(bytes,''base64''),E''\\n'','''')<>field or\n      (k=''cipherB64'' and octet_length(bytes)>1048576) or\n      (k in (''ivB64'',''wrapIvB64'') and octet_length(bytes)<>12) or\n      (k=''authTagB64'' and octet_length(bytes)<>16) or\n      (k=''wrappedKeyB64'' and octet_length(bytes)<>48) then raise exception ''storage cache format refused''; end if;\n  end loop;\nend; ","strict":false,"support":null,"volatility":"i"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',249,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_identity jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION keryx_storage.validate_identity(p_identity jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare k text; keys text[];\nbegin\n  if p_identity is null or jsonb_typeof(p_identity) is distinct from ''object'' then\n    raise exception ''storage identity refused: invalid_identity'';\n  end if;\n  select array_agg(key order by key) into keys from jsonb_object_keys(p_identity) as key;\n  if keys is distinct from array[''authorityMode'',''deploymentId'',''enrolledAt'',''enrollmentId'',''format'',''network'',''profileDigest'',''provenanceDigest'',''storageId'']::text[] then\n    raise exception ''storage identity refused: invalid_identity'';\n  end if;\n  foreach k in array keys loop\n    if jsonb_typeof(p_identity->k) is distinct from ''string'' then raise exception ''storage identity refused: invalid_identity''; end if;\n  end loop;\n  if p_identity->>''format'' <> ''keryx-storage-identity-v1''\n    or p_identity->>''network'' <> ''eip155:5042002''\n    or p_identity->>''authorityMode'' not in (''testnet-real'',''testnet-offline'')\n    or p_identity->>''profileDigest'' <> ''1e6fc06a6668d1626af05d70e88a5df59eebdc67680aca58164cfc9f9c778d9c''\n    or p_identity->>''provenanceDigest'' !~ ''^[0-9a-f]{64}$''\n    or p_identity->>''enrolledAt'' !~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\\.[0-9]{3}Z$'' then\n    raise exception ''storage identity refused: invalid_identity'';\n  end if;\n  foreach k in array array[''deploymentId'',''storageId'',''enrollmentId''] loop\n    if p_identity->>k !~ ''^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'' then\n      raise exception ''storage identity refused: invalid_identity'';\n    end if;\n  end loop;\n  begin\n    if to_char((p_identity->>''enrolledAt'')::timestamptz at time zone ''UTC'',''YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"'') <> p_identity->>''enrolledAt'' then\n      raise exception ''invalid enrollment time'';\n    end if;\n  exception when others then raise exception ''storage identity refused: invalid_identity''; end;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"validate_identity","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"keryx_storage","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare k text; keys text[];\nbegin\n  if p_identity is null or jsonb_typeof(p_identity) is distinct from ''object'' then\n    raise exception ''storage identity refused: invalid_identity'';\n  end if;\n  select array_agg(key order by key) into keys from jsonb_object_keys(p_identity) as key;\n  if keys is distinct from array[''authorityMode'',''deploymentId'',''enrolledAt'',''enrollmentId'',''format'',''network'',''profileDigest'',''provenanceDigest'',''storageId'']::text[] then\n    raise exception ''storage identity refused: invalid_identity'';\n  end if;\n  foreach k in array keys loop\n    if jsonb_typeof(p_identity->k) is distinct from ''string'' then raise exception ''storage identity refused: invalid_identity''; end if;\n  end loop;\n  if p_identity->>''format'' <> ''keryx-storage-identity-v1''\n    or p_identity->>''network'' <> ''eip155:5042002''\n    or p_identity->>''authorityMode'' not in (''testnet-real'',''testnet-offline'')\n    or p_identity->>''profileDigest'' <> ''1e6fc06a6668d1626af05d70e88a5df59eebdc67680aca58164cfc9f9c778d9c''\n    or p_identity->>''provenanceDigest'' !~ ''^[0-9a-f]{64}$''\n    or p_identity->>''enrolledAt'' !~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\\.[0-9]{3}Z$'' then\n    raise exception ''storage identity refused: invalid_identity'';\n  end if;\n  foreach k in array array[''deploymentId'',''storageId'',''enrollmentId''] loop\n    if p_identity->>k !~ ''^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'' then\n      raise exception ''storage identity refused: invalid_identity'';\n    end if;\n  end loop;\n  begin\n    if to_char((p_identity->>''enrolledAt'')::timestamptz at time zone ''UTC'',''YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"'') <> p_identity->>''enrolledAt'' then\n      raise exception ''invalid enrollment time'';\n    end if;\n  exception when others then raise exception ''storage identity refused: invalid_identity''; end;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',250,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_count bigint, p_bytes bigint","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION keryx_storage.verify_cache_quota(p_count bigint, p_bytes bigint)\n RETURNS void\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare retained keryx_storage.cache_quota%rowtype;\nbegin\n  select * into retained from keryx_storage.cache_quota where singleton;\n  if not found or retained.row_count is distinct from p_count or retained.wire_bytes is distinct from p_bytes then\n    raise exception ''storage cache quota refused'';\n  end if;\nend; $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"verify_cache_quota","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"keryx_storage","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare retained keryx_storage.cache_quota%rowtype;\nbegin\n  select * into retained from keryx_storage.cache_quota where singleton;\n  if not found or retained.row_count is distinct from p_count or retained.wire_bytes is distinct from p_bytes then\n    raise exception ''storage cache quota refused'';\n  end if;\nend; ","strict":false,"support":null,"volatility":"s"}'::jsonb,'059414daf5d5a69dcf821820d6809fee8106425a47be43c563b3f084f08c20bb'),
('before','functions',251,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION keryx_storage.verify_fences()\n RETURNS void\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare reference text; retained keryx_storage.enrolled_schema%rowtype;\nbegin\n  reference := keryx_storage.require_source_contract(''after'');\n  select * into retained from keryx_storage.enrolled_schema where singleton;\n  if not found or retained.contract_digest is distinct from reference then raise exception ''storage schema readiness refused''; end if;\n  if not exists(select 1 from keryx_storage.cache_quota where singleton) then raise exception ''storage cache quota refused''; end if;\n  if exists(select 1 from keryx_storage.writer) or exists(select 1 from public.browser_journal_writer)\n    or exists(select 1 from public.browser_signing_v2_writer) or exists(select 1 from public.browser_signing_v3_writer) then\n    raise exception ''retained writer capability refused'';\n  end if;\nend; $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"verify_fences","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"keryx_storage","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare reference text; retained keryx_storage.enrolled_schema%rowtype;\nbegin\n  reference := keryx_storage.require_source_contract(''after'');\n  select * into retained from keryx_storage.enrolled_schema where singleton;\n  if not found or retained.contract_digest is distinct from reference then raise exception ''storage schema readiness refused''; end if;\n  if not exists(select 1 from keryx_storage.cache_quota where singleton) then raise exception ''storage cache quota refused''; end if;\n  if exists(select 1 from keryx_storag