('after','functions',78,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_expected_identity jsonb, p_day date, p_event text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.storage_increment_activation_event(p_expected_identity jsonb, p_day date, p_event text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\n       begin\n        perform keryx_storage.enter_operation(p_expected_identity,''increment_activation_event'');\n        perform public.increment_activation_event(p_day,p_event);\n        perform keryx_storage.leave_operation();\n        return;\n      end; $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"storage_increment_activation_event","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\n       begin\n        perform keryx_storage.enter_operation(p_expected_identity,''increment_activation_event'');\n        perform public.increment_activation_event(p_day,p_event);\n        perform keryx_storage.leave_operation();\n        return;\n      end; ","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
