('after','functions',163,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_key text, p_now bigint, p_probe_ms bigint","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.acquire_reasoning_circuit(p_key text, p_now bigint, p_probe_ms bigint)\n RETURNS TABLE(allowed boolean, retry_after_ms bigint)\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare\n  v_open_until bigint;\n  v_probe_until bigint;\nbegin\n  select open_until, probe_until\n    into v_open_until, v_probe_until\n    from public.reasoning_circuits\n   where key = p_key\n   for update;\n\n  if not found or (v_open_until = 0 and v_probe_until <= p_now) then\n    return query select true, 0::bigint;\n    return;\n  end if;\n\n  if v_open_until > p_now or v_probe_until > p_now then\n    return query\n      select false, greatest(0::bigint, greatest(v_open_until, v_probe_until) - p_now);\n    return;\n  end if;\n\n  update public.reasoning_circuits\n     set probe_until = p_now + p_probe_ms,\n         updated_at = p_now\n   where key = p_key;\n  return query select true, 0::bigint;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"acquire_reasoning_circuit","owner":"postgres","parallel":"u","result":"TABLE(allowed boolean, retry_after_ms bigint)","returnsSet":true,"rows":"1000","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare\n  v_open_until bigint;\n  v_probe_until bigint;\nbegin\n  select open_until, probe_until\n    into v_open_until, v_probe_until\n    from public.reasoning_circuits\n   where key = p_key\n   for update;\n\n  if not found or (v_open_until = 0 and v_probe_until <= p_now) then\n    return query select true, 0::bigint;\n    return;\n  end if;\n\n  if v_open_until > p_now or v_probe_until > p_now then\n    return query\n      select false, greatest(0::bigint, greatest(v_open_until, v_probe_until) - p_now);\n    return;\n  end if;\n\n  update public.reasoning_circuits\n     set probe_until = p_now + p_probe_ms,\n         updated_at = p_now\n   where key = p_key;\n  return query select true, 0::bigint;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',164,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.activate_browser_journal()\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare v_legacy_grant record;\nbegin\n  perform 1 from public.browser_journal_control where id=1 for update;\n  if (select active from public.browser_journal_control where id=1) then return; end if;\n  lock table public.session_grants in share row exclusive mode;\n  lock table public.payment_events in share row exclusive mode;\n  if exists(select 1 from public.session_grants where coalesce(sess_addr,'''') !~* ''^0x[0-9a-f]{40}$''\n    or cap*1000000<>trunc(cap*1000000) or spent*1000000<>trunc(spent*1000000)\n    or cap<0 or spent<0 or spent*1000000>9007199254740991 or cap*1000000>9007199254740991) then\n    raise exception ''Legacy grant requires exact capacity audit'';\n  end if;\n  if exists(select 1 from public.payment_events where grant_epoch is not null and settlement_status in (''pending'',''settled'')\n    and (network is distinct from ''eip155:5042002'' or coalesce(payer,'''') !~* ''^0x[0-9a-f]{40}$''\n      or amount_usdc<=0 or amount_usdc*1000000<>trunc(amount_usdc*1000000) or amount_usdc*1000000>9007199254740991)) then\n    raise exception ''Legacy payment requires exact capacity audit'';\n  end if;\n  if exists(select grant_epoch from (\n    select grant_epoch,lower(sess_addr) signer from public.session_grants\n    union all select grant_epoch,lower(payer) from public.payment_events where grant_epoch is not null and settlement_status in (''pending'',''settled'')\n  ) x group by grant_epoch having count(distinct signer)>1) then raise exception ''Legacy epoch signer mismatch''; end if;\n  for v_legacy_grant in select * from public.session_grants loop\n    insert into public.browser_retained_grants values(v_legacy_grant.grant_epoch,v_legacy_grant.session_id,\n      lower(v_legacy_grant.sess_addr),(v_legacy_grant.spent*1000000)::bigint);\n  end loop;\n  -- Existing grant spend already includes its payments: use the larger amount per\n  -- epoch, then sum epochs. Missing nonce history is never manufactured here.\n  insert into public.browser_retained_grants(grant_epoch,session_id,signer,spent_micro)\n    select grant_epoch,''legacy:''||grant_epoch,lower(payer),sum(amount_usdc*1000000)::bigint\n    from public.payment_events where grant_epoch is not null and settlement_status in (''pending'',''settled'')\n    group by grant_epoch,lower(payer)\n    on conflict(grant_epoch) do update set spent_micro=greatest(browser_retained_grants.spent_micro,excluded.spent_micro);\n  if exists(select signer from public.browser_retained_grants group by signer having sum(spent_micro)>9007199254740991) then\n    raise exception ''Legacy signer requires exact capacity audit'';\n  end if;\n  insert into public.browser_signer_capacity select signer,sum(spent_micro)::bigint from public.browser_retained_grants group by signer;\n  update public.session_grants g set spent=c.spent_micro::numeric/1000000\n    from public.browser_signer_capacity c where lower(g.sess_addr)=c.signer;\n  update public.browser_journal_control set active=true where id=1;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"activate_browser_journal","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare v_legacy_grant record;\nbegin\n  perform 1 from public.browser_journal_control where id=1 for update;\n  if (select active from public.browser_journal_control where id=1) then return; end if;\n  lock table public.session_grants in share row exclusive mode;\n  lock table public.payment_events in share row exclusive mode;\n  if exists(select 1 from public.session_grants where coalesce(sess_addr,'''') !~* ''^0x[0-9a-f]{40}$''\n    or cap*1000000<>trunc(cap*1000000) or spent*1000000<>trunc(spent*1000000)\n    or cap<0 or spent<0 or spent*1000000>9007199254740991 or cap*1000000>9007199254740991) then\n    raise exception ''Legacy grant requires exact capacity audit'';\n  end if;\n  if exists(select 1 from public.payment_events where grant_epoch is not null and settlement_status in (''pending'',''settled'')\n    and (network is distinct from ''eip155:5042002'' or coalesce(payer,'''') !~* ''^0x[0-9a-f]{40}$''\n      or amount_usdc<=0 or amount_usdc*1000000<>trunc(amount_usdc*1000000) or amount_usdc*1000000>9007199254740991)) then\n    raise exception ''Legacy payment requires exact capacity audit'';\n  end if;\n  if exists(select grant_epoch from (\n    select grant_epoch,lower(sess_addr) signer from public.session_grants\n    union all select grant_epoch,lower(payer) from public.payment_events where grant_epoch is not null and settlement_status in (''pending'',''settled'')\n  ) x group by grant_epoch having count(distinct signer)>1) then raise exception ''Legacy epoch signer mismatch''; end if;\n  for v_legacy_grant in select * from public.session_grants loop\n    insert into public.browser_retained_grants values(v_legacy_grant.grant_epoch,v_legacy_grant.session_id,\n      lower(v_legacy_grant.sess_addr),(v_legacy_grant.spent*1000000)::bigint);\n  end loop;\n  -- Existing grant spend already includes its payments: use the larger amount per\n  -- epoch, then sum epochs. Missing nonce history is never manufactured here.\n  insert into public.browser_retained_grants(grant_epoch,session_id,signer,spent_micro)\n    select grant_epoch,''legacy:''||grant_epoch,lower(payer),sum(amount_usdc*1000000)::bigint\n    from public.payment_events where grant_epoch is not null and settlement_status in (''pending'',''settled'')\n    group by grant_epoch,lower(payer)\n    on conflict(grant_epoch) do update set spent_micro=greatest(browser_retained_grants.spent_micro,excluded.spent_micro);\n  if exists(select signer from public.browser_retained_grants group by signer having sum(spent_micro)>9007199254740991) then\n    raise exception ''Legacy signer requires exact capacity audit'';\n  end if;\n  insert into public.browser_signer_capacity select signer,sum(spent_micro)::bigint from public.browser_retained_grants group by signer;\n  update public.session_grants g set spent=c.spent_micro::numeric/1000000\n    from public.browser_signer_capacity c where lower(g.sess_addr)=c.signer;\n  update public.browser_journal_control set active=true where id=1;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',165,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_intent jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.admit_browser_authorization(p_intent jsonb)\n RETURNS text\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare\n  v_amount numeric;\n  v_updated integer;\nbegin\n  -- The adapter supplies a positive safe integer. Recheck at the database boundary.\n  if p_intent->>''nonce'' !~ ''^0x[0-9a-f]{64}$''\n     or p_intent->>''network'' <> ''eip155:5042002''\n     or lower(p_intent->>''token'') <> ''0x3600000000000000000000000000000000000000''\n     or lower(p_intent->>''gateway_contract'') <> ''0x0077777d7eba4688bdef3e311b846f25870a19b9''\n     or p_intent->>''kind'' not in (''fetch'', ''citation'')\n     or p_intent->>''amount_micro_usdc'' !~ ''^[0-9]+$'' then\n    raise exception ''Invalid browser authorization intent'';\n  end if;\n  v_amount := (p_intent->>''amount_micro_usdc'')::numeric;\n  if v_amount < 1 or v_amount > 9007199254740991 then\n    raise exception ''Invalid browser authorization amount'';\n  end if;\n  update public.session_grants\n     set spent = (spent * 1000000 + v_amount) / 1000000\n   where session_id = p_intent->>''session_id''\n     and grant_epoch = p_intent->>''grant_epoch''\n     and lower(sess_addr) = lower(p_intent->>''signer'')\n     and expiry > (extract(epoch from clock_timestamp()) * 1000)::bigint\n     and cap * 1000000 = trunc(cap * 1000000)\n     and spent * 1000000 = trunc(spent * 1000000)\n     and spent * 1000000 + v_amount <= cap * 1000000;\n  get diagnostics v_updated = row_count;\n  if v_updated = 0 then\n    return ''grant_or_cap_refused'';\n  end if;\n  insert into public.browser_authorization_intents\n    (nonce,session_id,request_id,query_id,grant_epoch,signer,network,token,gateway_contract,\n     source_id,offer_id,kind,payee,amount_micro_usdc,created_at)\n  values\n    (p_intent->>''nonce'',p_intent->>''session_id'',p_intent->>''request_id'',\n     p_intent->>''query_id'',p_intent->>''grant_epoch'',p_intent->>''signer'',\n     p_intent->>''network'',p_intent->>''token'',p_intent->>''gateway_contract'',\n     p_intent->>''source_id'',p_intent->>''offer_id'',p_intent->>''kind'',\n     p_intent->>''payee'',v_amount,(p_intent->>''created_at'')::timestamptz);\n  return ''admitted'';\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"admit_browser_authorization","owner":"postgres","parallel":"u","result":"text","returnsSet":false,"rows":"0","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare\n  v_amount numeric;\n  v_updated integer;\nbegin\n  -- The adapter supplies a positive safe integer. Recheck at the database boundary.\n  if p_intent->>''nonce'' !~ ''^0x[0-9a-f]{64}$''\n     or p_intent->>''network'' <> ''eip155:5042002''\n     or lower(p_intent->>''token'') <> ''0x3600000000000000000000000000000000000000''\n     or lower(p_intent->>''gateway_contract'') <> ''0x0077777d7eba4688bdef3e311b846f25870a19b9''\n     or p_intent->>''kind'' not in (''fetch'', ''citation'')\n     or p_intent->>''amount_micro_usdc'' !~ ''^[0-9]+$'' then\n    raise exception ''Invalid browser authorization intent'';\n  end if;\n  v_amount := (p_intent->>''amount_micro_usdc'')::numeric;\n  if v_amount < 1 or v_amount > 9007199254740991 then\n    raise exception ''Invalid browser authorization amount'';\n  end if;\n  update public.session_grants\n     set spent = (spent * 1000000 + v_amount) / 1000000\n   where session_id = p_intent->>''session_id''\n     and grant_epoch = p_intent->>''grant_epoch''\n     and lower(sess_addr) = lower(p_intent->>''signer'')\n     and expiry > (extract(epoch from clock_timestamp()) * 1000)::bigint\n     and cap * 1000000 = trunc(cap * 1000000)\n     and spent * 1000000 = trunc(spent * 1000000)\n     and spent * 1000000 + v_amount <= cap * 1000000;\n  get diagnostics v_updated = row_count;\n  if v_updated = 0 then\n    return ''grant_or_cap_refused'';\n  end if;\n  insert into public.browser_authorization_intents\n    (nonce,session_id,request_id,query_id,grant_epoch,signer,network,token,gateway_contract,\n     source_id,offer_id,kind,payee,amount_micro_usdc,created_at)\n  values\n    (p_intent->>''nonce'',p_intent->>''session_id'',p_intent->>''request_id'',\n     p_intent->>''query_id'',p_intent->>''grant_epoch'',p_intent->>''signer'',\n     p_intent->>''network'',p_intent->>''token'',p_intent->>''gateway_contract'',\n     p_intent->>''source_id'',p_intent->>''offer_id'',p_intent->>''kind'',\n     p_intent->>''payee'',v_amount,(p_intent->>''created_at'')::timestamptz);\n  return ''admitted'';\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',166,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_intent jsonb, p_requirements jsonb, p_payment jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.admit_browser_journal(p_intent jsonb, p_requirements jsonb, p_payment jsonb)\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare v_amount bigint; v_spent bigint; v_cap numeric; g public.session_grants%rowtype;\nbegin\n  if not (select active from public.browser_journal_control where id=1) then return ''inactive''; end if;\n  if coalesce(p_intent->>''amount_micro_usdc'','''') !~ ''^[0-9]+$''\n     or coalesce(p_intent->>''nonce'','''') !~ ''^0x[0-9a-f]{64}$''\n     or p_intent->>''network'' is distinct from ''eip155:5042002''\n     or lower(p_intent->>''token'') is distinct from ''0x3600000000000000000000000000000000000000''\n     or lower(p_intent->>''gateway_contract'') is distinct from ''0x0077777d7eba4688bdef3e311b846f25870a19b9''\n     or coalesce(p_intent->>''kind'','''') not in (''fetch'',''citation'') then raise exception ''Invalid browser authorization intent''; end if;\n  v_amount:=(p_intent->>''amount_micro_usdc'')::bigint;\n  if v_amount<1 or v_amount>9007199254740991 or p_requirements->>''amount'' is distinct from v_amount::text\n    or p_requirements->>''scheme'' is distinct from ''exact'' or p_requirements->>''network'' is distinct from ''eip155:5042002''\n    or lower(p_requirements->>''asset'') is distinct from lower(p_intent->>''token'')\n    or lower(p_requirements->>''payTo'') is distinct from lower(p_intent->>''payee'')\n    or p_requirements#>>''{extra,name}'' is distinct from ''GatewayWalletBatched''\n    or p_requirements#>>''{extra,version}'' is distinct from ''1''\n    or lower(p_requirements#>>''{extra,verifyingContract}'') is distinct from lower(p_intent->>''gateway_contract'')\n    or coalesce(p_requirements->>''maxTimeoutSeconds'','''') !~ ''^[0-9]+$''\n    or (p_requirements->>''maxTimeoutSeconds'')::numeric not between 604900 and 691200\n    or lower(p_payment->>''payer'') is distinct from lower(p_intent->>''signer'') or lower(p_payment->>''payee'') is distinct from lower(p_intent->>''payee'')\n    or p_payment->>''network'' is distinct from p_intent->>''network'' or p_payment->>''queryId'' is distinct from p_intent->>''query_id''\n    or p_payment->>''sourceId'' is distinct from p_intent->>''source_id'' or p_payment->>''kind'' is distinct from p_intent->>''kind''\n    or p_payment->>''grantEpoch'' is distinct from p_intent->>''grant_epoch''\n    or (p_payment->>''amountUsdc'')::numeric*1000000 is distinct from v_amount::numeric\n    or (p_payment->>''offerId'') is distinct from (p_intent->>''offer_id'') then raise exception ''Browser journal economic tuple differs from challenge''; end if;\n  -- Always lock signer capacity before grant rows, including replacement/recovery writers.\n  select spent_micro into v_spent from public.browser_signer_capacity where signer=lower(p_intent->>''signer'') for update;\n  if not found then return ''grant_or_cap_refused''; end if;\n  select * into g from public.session_grants where session_id=p_intent->>''session_id'' and grant_epoch=p_intent->>''grant_epoch''\n    and lower(sess_addr)=lower(p_intent->>''signer'') and expiry>(extract(epoch from clock_timestamp())*1000)::bigint for update;\n  if not found or g.cap*1000000<>trunc(g.cap*1000000) or v_spent+v_amount>g.cap*1000000 then return ''grant_or_cap_refused''; end if;\n  perform pg_advisory_xact_lock(hashtextextended(p_intent->>''nonce'',0));\n  if exists(select 1 from public.payment_events where authorization_id=p_intent->>''nonce'') then raise exception ''Browser journal nonce collision''; end if;\n  insert into public.browser_journal_writer values(txid_current());\n  -- Reuse actual D268 admission validation and immutable insert inside the same transaction.\n  update public.session_grants set spent=v_spent::numeric/1000000 where session_id=g.session_id;\n  if public.admit_browser_authorization(p_intent)<>''admitted'' then raise exception ''Journal grant fence changed''; end if;\n  insert into public.browser_journal_bindings(nonce,requirements,payment_metadata)\n    values(p_intent->>''nonce'',jsonb_build_object(''scheme'',''exact'',''network'',p_intent->>''network'',''asset'',p_intent->>''token'',\n      ''payTo'',p_intent->>''payee'',''amount'',v_amount::text,''maxTimeoutSeconds'',(p_requirements->>''maxTimeoutSeconds'')::integer,\n      ''extra'',jsonb_build_object(''name'',''GatewayWalletBatched'',''version'',''1'',''verifyingContract'',p_intent->>''gateway_contract'')),\n      (select coalesce(jsonb_object_agg(key,value),''{}''::jsonb) from jsonb_each(p_payment)\n        where key=any(array[''id'',''createdAt'',''kind'',''queryId'',''sourceId'',''sourceName'',''payer'',''payee'',''amountUsdc'',''weight'',''rationale'',\n        ''network'',''settled'',''settlementStatus'',''authorizationId'',''grantEpoch'',''origin'',''itemId'',''itemTitle'',''itemUrl'',''contentVersion'',\n        ''itemPublishedAt'',''offerId'',''listPriceUsdc''])));\n  insert into public.payment_events(id,created_at,kind,query_id,source_id,source_name,payer,payee,amount_usdc,weight,rationale,network,settled,settlement_status,authorization_id,grant_epoch,origin,item_id,item_title,item_url,content_version,item_published_at,offer_id,list_price_usdc,authorization_phase)\n    values(''x402:''||(p_intent->>''nonce''),(p_intent->>''created_at'')::timestamptz,p_intent->>''kind'',p_intent->>''query_id'',p_intent->>''source_id'',p_payment->>''sourceName'',p_intent->>''signer'',p_intent->>''payee'',v_amount::numeric/1000000,\n      (p_payment->>''weight'')::numeric,p_payment->>''rationale'',p_intent->>''network'',false,''pending'',p_intent->>''nonce'',p_intent->>''grant_epoch'',coalesce(p_payment->>''origin'',''web''),p_payment->>''itemId'',p_payment->>''itemTitle'',p_payment->>''itemUrl'',p_payment->>''contentVersion'',(p_payment->>''itemPublishedAt'')::timestamptz,p_intent->>''offer_id'',(p_payment->>''listPriceUsdc'')::numeric,''prepared'');\n  update public.browser_signer_capacity set spent_micro=spent_micro+v_amount where signer=lower(g.sess_addr);\n  update public.browser_retained_grants set spent_micro=spent_micro+v_amount where grant_epoch=g.grant_epoch;\n  update public.session_grants set spent=(v_spent+v_amount)::numeric/1000000 where lower(sess_addr)=lower(g.sess_addr);\n  delete from public.browser_journal_writer where transaction_id=txid_current();\n  return ''admitted'';\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"admit_browser_journal","owner":"postgres","parallel":"u","result":"text","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare v_amount bigint; v_spent bigint; v_cap numeric; g public.session_grants%rowtype;\nbegin\n  if not (select active from public.browser_journal_control where id=1) then return ''inactive''; end if;\n  if coalesce(p_intent->>''amount_micro_usdc'','''') !~ ''^[0-9]+$''\n     or coalesce(p_intent->>''nonce'','''') !~ ''^0x[0-9a-f]{64}$''\n     or p_intent->>''network'' is distinct from ''eip155:5042002''\n     or lower(p_intent->>''token'') is distinct from ''0x3600000000000000000000000000000000000000''\n     or lower(p_intent->>''gateway_contract'') is distinct from ''0x0077777d7eba4688bdef3e311b846f25870a19b9''\n     or coalesce(p_intent->>''kind'','''') not in (''fetch'',''citation'') then raise exception ''Invalid browser authorization intent''; end if;\n  v_amount:=(p_intent->>''amount_micro_usdc'')::bigint;\n  if v_amount<1 or v_amount>9007199254740991 or p_requirements->>''amount'' is distinct from v_amount::text\n    or p_requirements->>''scheme'' is distinct from ''exact'' or p_requirements->>''network'' is distinct from ''eip155:5042002''\n    or lower(p_requirements->>''asset'') is distinct from lower(p_intent->>''token'')\n    or lower(p_requirements->>''payTo'') is distinct from lower(p_intent->>''payee'')\n    or p_requirements#>>''{extra,name}'' is distinct from ''GatewayWalletBatched''\n    or p_requirements#>>''{extra,version}'' is distinct from ''1''\n    or lower(p_requirements#>>''{extra,verifyingContract}'') is distinct from lower(p_intent->>''gateway_contract'')\n    or coalesce(p_requirements->>''maxTimeoutSeconds'','''') !~ ''^[0-9]+$''\n    or (p_requirements->>''maxTimeoutSeconds'')::numeric not between 604900 and 691200\n    or lower(p_payment->>''payer'') is distinct from lower(p_intent->>''signer'') or lower(p_payment->>''payee'') is distinct from lower(p_intent->>''payee'')\n    or p_payment->>''network'' is distinct from p_intent->>''network'' or p_payment->>''queryId'' is distinct from p_intent->>''query_id''\n    or p_payment->>''sourceId'' is distinct from p_intent->>''source_id'' or p_payment->>''kind'' is distinct from p_intent->>''kind''\n    or p_payment->>''grantEpoch'' is distinct from p_intent->>''grant_epoch''\n    or (p_payment->>''amountUsdc'')::numeric*1000000 is distinct from v_amount::numeric\n    or (p_payment->>''offerId'') is distinct from (p_intent->>''offer_id'') then raise exception ''Browser journal economic tuple differs from challenge''; end if;\n  -- Always lock signer capacity before grant rows, including replacement/recovery writers.\n  select spent_micro into v_spent from public.browser_signer_capacity where signer=lower(p_intent->>''signer'') for update;\n  if not found then return ''grant_or_cap_refused''; end if;\n  select * into g from public.session_grants where session_id=p_intent->>''session_id'' and grant_epoch=p_intent->>''grant_epoch''\n    and lower(sess_addr)=lower(p_intent->>''signer'') and expiry>(extract(epoch from clock_timestamp())*1000)::bigint for update;\n  if not found or g.cap*1000000<>trunc(g.cap*1000000) or v_spent+v_amount>g.cap*1000000 then return ''grant_or_cap_refused''; end if;\n  perform pg_advisory_xact_lock(hashtextextended(p_intent->>''nonce'',0));\n  if exists(select 1 from public.payment_events where authorization_id=p_intent->>''nonce'') then raise exception ''Browser journal nonce collision''; end if;\n  insert into public.browser_journal_writer values(txid_current());\n  -- Reuse actual D268 admission validation and immutable insert inside the same transaction.\n  update public.session_grants set spent=v_spent::numeric/1000000 where session_id=g.session_id;\n  if public.admit_browser_authorization(p_intent)<>''admitted'' then raise exception ''Journal grant fence changed''; end if;\n  insert into public.browser_journal_bindings(nonce,requirements,payment_metadata)\n    values(p_intent->>''nonce'',jsonb_build_object(''scheme'',''exact'',''network'',p_intent->>''network'',''asset'',p_intent->>''token'',\n      ''payTo'',p_intent->>''payee'',''amount'',v_amount::text,''maxTimeoutSeconds'',(p_requirements->>''maxTimeoutSeconds'')::integer,\n      ''extra'',jsonb_build_object(''name'',''GatewayWalletBatched'',''version'',''1'',''verifyingContract'',p_intent->>''gateway_contract'')),\n      (select coalesce(jsonb_object_agg(key,value),''{}''::jsonb) from jsonb_each(p_payment)\n        where key=any(array[''id'',''createdAt'',''kind'',''queryId'',''sourceId'',''sourceName'',''payer'',''payee'',''amountUsdc'',''weight'',''rationale'',\n        ''network'',''settled'',''settlementStatus'',''authorizationId'',''grantEpoch'',''origin'',''itemId'',''itemTitle'',''itemUrl'',''contentVersion'',\n        ''itemPublishedAt'',''offerId'',''listPriceUsdc''])));\n  insert into public.payment_events(id,created_at,kind,query_id,source_id,source_name,payer,payee,amount_usdc,weight,rationale,network,settled,settlement_status,authorization_id,grant_epoch,origin,item_id,item_title,item_url,content_version,item_published_at,offer_id,list_price_usdc,authorization_phase)\n    values(''x402:''||(p_intent->>''nonce''),(p_intent->>''created_at'')::timestamptz,p_intent->>''kind'',p_intent->>''query_id'',p_intent->>''source_id'',p_payment->>''sourceName'',p_intent->>''signer'',p_intent->>''payee'',v_amount::numeric/1000000,\n      (p_payment->>''weight'')::numeric,p_payment->>''rationale'',p_intent->>''network'',false,''pending'',p_intent->>''nonce'',p_intent->>''grant_epoch'',coalesce(p_payment->>''origin'',''web''),p_payment->>''itemId'',p_payment->>''itemTitle'',p_payment->>''itemUrl'',p_payment->>''contentVersion'',(p_payment->>''itemPublishedAt'')::timestamptz,p_intent->>''offer_id'',(p_payment->>''listPriceUsdc'')::numeric,''prepared'');\n  update public.browser_signer_capacity set spent_micro=spent_micro+v_amount where signer=lower(g.sess_addr);\n  update public.browser_retained_grants set spent_micro=spent_micro+v_amount where grant_epoch=g.grant_epoch;\n  update public.session_grants set spent=(v_spent+v_amount)::numeric/1000000 where lower(sess_addr)=lower(g.sess_addr);\n  delete from public.browser_journal_writer where transaction_id=txid_current();\n  return ''admitted'';\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',167,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_payer text, p_worker_id uuid, p_leg_id text, p_authorization_id text, p_amount_micros integer, p_data jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.admit_private_creator_submission(p_id text, p_payer text, p_worker_id uuid, p_leg_id text, p_authorization_id text, p_amount_micros integer, p_data jsonb)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare budget numeric; used numeric; n integer;\nbegin\n  -- Serialize every leg against the same immutable worker and signed creator budget.\n  select round((i.data#>>''{submission,request,budget}'')::numeric*1000000) into budget\n  from public.private_research_executions e join public.private_research_intents i on i.id=e.id\n  where e.id=p_id and e.worker_id=p_worker_id and i.payer=lower(p_payer) for update of e;\n  if not found then return false; end if;\n  if budget is null or budget <= 0 or budget > 1000000 then raise exception ''invalid creator budget''; end if;\n  if p_amount_micros is null or p_amount_micros <= 0 or p_amount_micros > 1000000\n    or p_leg_id is null or p_leg_id !~ ''^[a-f0-9]{64}$''\n    or p_authorization_id is null or p_authorization_id !~ ''^0x[a-f0-9]{64}$''\n    or (p_data#>>''{submission,authorizationId}'') is distinct from p_authorization_id\n    or (p_data#>>''{submission,amountMicros}'') is distinct from p_amount_micros::text\n  then raise exception ''invalid creator submission''; end if;\n  if exists(select 1 from public.private_research_results where id=p_id)\n    or exists(select 1 from public.private_research_interruptions where id=p_id) then return false; end if;\n  select coalesce(sum(amount_micros),0) into used from public.private_creator_submissions where job_id=p_id;\n  if used+p_amount_micros > budget then return false; end if;\n  insert into public.private_creator_submissions(job_id,leg_id,worker_id,authorization_id,amount_micros,data)\n  values(p_id,p_leg_id,p_worker_id,p_authorization_id,p_amount_micros,p_data) on conflict do nothing;\n  get diagnostics n = row_count;\n  return n=1;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"admit_private_creator_submission","owner":"postgres","parallel":"u","result":"boolean","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare budget numeric; used numeric; n integer;\nbegin\n  -- Serialize every leg against the same immutable worker and signed creator budget.\n  select round((i.data#>>''{submission,request,budget}'')::numeric*1000000) into budget\n  from public.private_research_executions e join public.private_research_intents i on i.id=e.id\n  where e.id=p_id and e.worker_id=p_worker_id and i.payer=lower(p_payer) for update of e;\n  if not found then return false; end if;\n  if budget is null or budget <= 0 or budget > 1000000 then raise exception ''invalid creator budget''; end if;\n  if p_amount_micros is null or p_amount_micros <= 0 or p_amount_micros > 1000000\n    or p_leg_id is null or p_leg_id !~ ''^[a-f0-9]{64}$''\n    or p_authorization_id is null or p_authorization_id !~ ''^0x[a-f0-9]{64}$''\n    or (p_data#>>''{submission,authorizationId}'') is distinct from p_authorization_id\n    or (p_data#>>''{submission,amountMicros}'') is distinct from p_amount_micros::text\n  then raise exception ''invalid creator submission''; end if;\n  if exists(select 1 from public.private_research_results where id=p_id)\n    or exists(select 1 from public.private_research_interruptions where id=p_id) then return false; end if;\n  select coalesce(sum(amount_micros),0) into used from public.private_creator_submissions where job_id=p_id;\n  if used+p_amount_micros > budget then return false; end if;\n  insert into public.private_creator_submissions(job_id,leg_id,worker_id,authorization_id,amount_micros,data)\n  values(p_id,p_leg_id,p_worker_id,p_authorization_id,p_amount_micros,p_data) on conflict do nothing;\n  get diagnostics n = row_count;\n  return n=1;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',168,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_journal_payment_fence()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\nbegin\n  if tg_op=''DELETE'' then\n    if old.authorization_phase is not null\n       or ((select active from public.browser_journal_control where id=1) and old.grant_epoch is not null) then\n      raise exception ''browser journal payment is retained'';\n    end if;\n    return old;\n  end if;\n  if tg_op<>''DELETE'' and new.authorization_id is not null then\n    perform pg_advisory_xact_lock(hashtextextended(new.authorization_id,0));\n  end if;\n  if tg_op=''INSERT'' then\n    if exists(select 1 from public.browser_journal_bindings where nonce=new.authorization_id)\n       and new.id is distinct from (''x402:''||new.authorization_id) then raise exception ''browser journal nonce collision''; end if;\n    if (new.authorization_phase is not null or exists(select 1 from public.browser_journal_bindings where nonce=new.authorization_id)\n       or ((select active from public.browser_journal_control where id=1) and new.grant_epoch is not null))\n       and not exists(select 1 from public.browser_journal_writer where transaction_id=txid_current()) then\n      raise exception ''browser journal payment already admitted'';\n    end if;\n    return new;\n  end if;\n  if old.authorization_phase is not null or new.authorization_phase is not null\n     or ((select active from public.browser_journal_control where id=1) and old.grant_epoch is not null) then\n    if not exists(select 1 from public.browser_journal_writer where transaction_id=txid_current()) then raise exception ''browser journal writer required''; end if;\n    if (new.id,new.authorization_id,new.payer,new.payee,new.amount_usdc,new.network,new.grant_epoch,new.source_id,new.query_id,new.offer_id,new.kind)\n       is distinct from (old.id,old.authorization_id,old.payer,old.payee,old.amount_usdc,old.network,old.grant_epoch,old.source_id,old.query_id,old.offer_id,old.kind) then\n      raise exception ''browser journal payment tuple is immutable'';\n    end if;\n  end if;\n  if tg_op=''UPDATE'' and exists(select 1 from public.browser_journal_bindings where nonce=new.authorization_id)\n     and new.id is distinct from (''x402:''||new.authorization_id) then raise exception ''browser journal nonce collision''; end if;\n  return new;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"browser_journal_payment_fence","owner":"postgres","parallel":"u","result":"trigger","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\nbegin\n  if tg_op=''DELETE'' then\n    if old.authorization_phase is not null\n       or ((select active from public.browser_journal_control where id=1) and old.grant_epoch is not null) then\n      raise exception ''browser journal payment is retained'';\n    end if;\n    return old;\n  end if;\n  if tg_op<>''DELETE'' and new.authorization_id is not null then\n    perform pg_advisory_xact_lock(hashtextextended(new.authorization_id,0));\n  end if;\n  if tg_op=''INSERT'' then\n    if exists(select 1 from public.browser_journal_bindings where nonce=new.authorization_id)\n       and new.id is distinct from (''x402:''||new.authorization_id) then raise exception ''browser journal nonce collision''; end if;\n    if (new.authorization_phase is not null or exists(select 1 from public.browser_journal_bindings where nonce=new.authorization_id)\n       or ((select active from public.browser_journal_control where id=1) and new.grant_epoch is not null))\n       and not exists(select 1 from public.browser_journal_writer where transaction_id=txid_current()) then\n      raise exception ''browser journal payment already admitted'';\n    end if;\n    return new;\n  end if;\n  if old.authorization_phase is not null or new.authorization_phase is not null\n     or ((select active from public.browser_journal_control where id=1) and old.grant_epoch is not null) then\n    if not exists(select 1 from public.browser_journal_writer where transaction_id=txid_current()) then raise exception ''browser journal writer required''; end if;\n    if (new.id,new.authorization_id,new.payer,new.payee,new.amount_usdc,new.network,new.grant_epoch,new.source_id,new.query_id,new.offer_id,new.kind)\n       is distinct from (old.id,old.authorization_id,old.payer,old.payee,old.amount_usdc,old.network,old.grant_epoch,old.source_id,old.query_id,old.offer_id,old.kind) then\n      raise exception ''browser journal payment tuple is immutable'';\n    end if;\n  end if;\n  if tg_op=''UPDATE'' and exists(select 1 from public.browser_journal_bindings where nonce=new.authorization_id)\n     and new.id is distinct from (''x402:''||new.authorization_id) then raise exception ''browser journal nonce collision''; end if;\n  return new;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',169,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_journal_write_fence()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\nbegin\n  if (select active from public.browser_journal_control where id=1)\n     and not exists(select 1 from public.browser_journal_writer where transaction_id=txid_current()) then\n    raise exception ''browser journal writer required'';\n  end if;\n  if tg_op=''DELETE'' then return old; end if;\n  return new;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"browser_journal_write_fence","owner":"postgres","parallel":"u","result":"trigger","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\nbegin\n  if (select active from public.browser_journal_control where id=1)\n     and not exists(select 1 from public.browser_journal_writer where transaction_id=txid_current()) then\n    raise exception ''browser journal writer required'';\n  end if;\n  if tg_op=''DELETE'' then return old; end if;\n  return new;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',170,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_signer text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_signer_confirmed_spend_micro(p_signer text)\n RETURNS bigint\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare v_total numeric;\nbegin\n  if coalesce(p_signer,'''') !~* ''^0x[0-9a-f]{40}$'' then raise exception ''Invalid browser signer''; end if;\n  if exists(select 1 from public.payment_events where settled=true and settlement_status=''settled''\n    and grant_epoch is not null and network=''eip155:5042002'' and lower(payer)=lower(p_signer)\n    and coalesce(trim(tx_hash),'''')<>'''' and authorization_id ~* ''^0x[0-9a-f]{64}$''\n    and (amount_usdc<=0 or amount_usdc*1000000<>trunc(amount_usdc*1000000) or coalesce(payee,'''') !~* ''^0x[0-9a-f]{40}$'')) then\n    raise exception ''Confirmed spend requires exact capacity audit'';\n  end if;\n  if exists(select lower(authorization_id) from public.payment_events\n    where settled=true and settlement_status=''settled'' and grant_epoch is not null\n      and network=''eip155:5042002'' and lower(payer)=lower(p_signer)\n      and coalesce(trim(tx_hash),'''')<>'''' and authorization_id ~* ''^0x[0-9a-f]{64}$''\n    group by lower(authorization_id)\n    having count(distinct (lower(payee),network,amount_usdc,grant_epoch,source_id,query_id,kind,offer_id))>1) then\n    raise exception ''Conflicting confirmed authorization identity'';\n  end if;\n  select coalesce(sum(amount_micro),0) into v_total from (\n    select lower(authorization_id),max(amount_usdc*1000000) amount_micro from public.payment_events\n    where settled=true and settlement_status=''settled'' and grant_epoch is not null\n      and network=''eip155:5042002'' and lower(payer)=lower(p_signer)\n      and coalesce(trim(tx_hash),'''')<>'''' and authorization_id ~* ''^0x[0-9a-f]{64}$''\n    group by lower(authorization_id)\n  ) deduplicated;\n  if v_total>9007199254740991 then raise exception ''Confirmed spend requires exact capacity audit''; end if;\n  return v_total::bigint;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"browser_signer_confirmed_spend_micro","owner":"postgres","parallel":"u","result":"bigint","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare v_total numeric;\nbegin\n  if coalesce(p_signer,'''') !~* ''^0x[0-9a-f]{40}$'' then raise exception ''Invalid browser signer''; end if;\n  if exists(select 1 from public.payment_events where settled=true and settlement_status=''settled''\n    and grant_epoch is not null and network=''eip155:5042002'' and lower(payer)=lower(p_signer)\n    and coalesce(trim(tx_hash),'''')<>'''' and authorization_id ~* ''^0x[0-9a-f]{64}$''\n    and (amount_usdc<=0 or amount_usdc*1000000<>trunc(amount_usdc*1000000) or coalesce(payee,'''') !~* ''^0x[0-9a-f]{40}$'')) then\n    raise exception ''Confirmed spend requires exact capacity audit'';\n  end if;\n  if exists(select lower(authorization_id) from public.payment_events\n    where settled=true and settlement_status=''settled'' and grant_epoch is not null\n      and network=''eip155:5042002'' and lower(payer)=lower(p_signer)\n      and coalesce(trim(tx_hash),'''')<>'''' and authorization_id ~* ''^0x[0-9a-f]{64}$''\n    group by lower(authorization_id)\n    having count(distinct (lower(payee),network,amount_usdc,grant_epoch,source_id,query_id,kind,offer_id))>1) then\n    raise exception ''Conflicting confirmed authorization identity'';\n  end if;\n  select coalesce(sum(amount_micro),0) into v_total from (\n    select lower(authorization_id),max(amount_usdc*1000000) amount_micro from public.payment_events\n    where settled=true and settlement_status=''settled'' and grant_epoch is not null\n      and network=''eip155:5042002'' and lower(payer)=lower(p_signer)\n      and coalesce(trim(tx_hash),'''')<>'''' and authorization_id ~* ''^0x[0-9a-f]{64}$''\n    group by lower(authorization_id)\n  ) deduplicated;\n  if v_total>9007199254740991 then raise exception ''Confirmed spend requires exact capacity audit''; end if;\n  return v_total::bigint;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',171,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_input jsonb, p_journal jsonb, p_original jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_signing_admit_original(p_input jsonb, p_journal jsonb, p_original jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\nbegin\n if public.browser_signing_original_floor_for_write()=3\n  and not exists(select 1 from public.browser_signing_originals where session_id=p_input#>>''{journal,sessionId}'' and request_id=p_input#>>''{journal,requestId}'') then return jsonb_build_object(''status'',''refused''); end if;\n return public.browser_signing_v2_admission_internal(p_input,p_journal,p_original);\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"browser_signing_admit_original","owner":"postgres","parallel":"u","result":"jsonb","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\nbegin\n if public.browser_signing_original_floor_for_write()=3\n  and not exists(select 1 from public.browser_signing_originals where session_id=p_input#>>''{journal,sessionId}'' and request_id=p_input#>>''{journal,requestId}'') then return jsonb_build_object(''status'',''refused''); end if;\n return public.browser_signing_v2_admission_internal(p_input,p_journal,p_original);\nend ","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',172,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_verified jsonb, p_session_id text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_signing_admit_query(p_verified jsonb, p_session_id text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare p jsonb:=p_verified->''policy''; ns text:=p_verified->>''namespace''; n public.browser_signing_namespaces%rowtype;\n q public.browser_signing_queries%rowtype; saved jsonb; g public.session_grants%rowtype; ceiling bigint; lifetime bigint; jobs_limit bigint;\nbegin\n if (select active from public.browser_signing_v2_control where id=1) is distinct from true\n  or (select active from public.browser_journal_control where id=1) is distinct from true then return jsonb_build_object(''status'',''inactive''); end if;\n if p->>''protocol'' is distinct from ''durable-v2'' or p->>''service'' is distinct from ''https://keryx.cc''\n  or coalesce(ns,'''') !~ ''^0x[0-9a-f]{64}$'' or coalesce(p_verified->>''proofDigest'','''') !~ ''^0x[0-9a-f]{64}$''\n  or coalesce(p_verified->>''signature'','''') !~ ''^0x[0-9a-f]{130}$''\n  or coalesce(p->>''owner'','''') !~ ''^0x[0-9a-f]{40}$'' or coalesce(p->>''signer'','''') !~ ''^0x[0-9a-f]{40}$''\n  or coalesce(p->>''policyId'','''') !~ ''^0x[0-9a-f]{64}$'' or coalesce(p->>''requestNonce'','''') !~ ''^0x[0-9a-f]{64}$''\n  or coalesce(p->>''questionDigest'','''') !~ ''^0x[0-9a-f]{64}$''\n  or coalesce(p->>''queryCeilingMicros'','''') !~ ''^[1-9][0-9]{0,15}$'' or coalesce(p->>''lifetimeCeilingMicros'','''') !~ ''^[1-9][0-9]{0,15}$''\n  or coalesce(p->>''jobLimit'','''') !~ ''^[1-9][0-9]{0,15}$'' or coalesce(p->>''expiresAt'','''') !~ ''^[1-9][0-9]{0,15}$''\n  or coalesce(p_session_id,'''')='''' then raise exception ''browser query policy refused''; end if;\n perform (p->>''queryId'')::uuid; perform (p->>''grantEpoch'')::uuid;\n ceiling:=(p->>''queryCeilingMicros'')::bigint; lifetime:=(p->>''lifetimeCeilingMicros'')::bigint; jobs_limit:=(p->>''jobLimit'')::bigint;\n if ceiling>lifetime or lifetime>9007199254740991 or jobs_limit>9007199254740991 or (p->>''expiresAt'')::numeric>9007199254740991 then raise exception ''browser query policy refused''; end if;\n perform pg_advisory_xact_lock(hashtextextended(ns,0));\n select verified into saved from public.browser_signing_policies where namespace=ns and policy_id=p->>''policyId'';\n if found and saved is distinct from p_verified then raise exception ''browser query policy conflict''; end if;\n select * into q from public.browser_signing_queries where namespace=ns and (request_nonce=p->>''requestNonce'' or query_id=p->>''queryId'');\n if found then\n  if q.policy_id=p->>''policyId'' and q.query_id=p->>''queryId'' and q.request_nonce=p->>''requestNonce'' and q.session_id=p_session_id and saved=p_verified then\n   return jsonb_build_object(''status'',''admitted'',''namespace'',ns,''queryId'',q.query_id);\n  end if; raise exception ''browser query original conflict'';\n end if;\n select * into g from public.session_grants where session_id=p_session_id for update;\n if not found or lower(g.owner_addr) is distinct from p->>''owner'' or lower(g.sess_addr) is distinct from p->>''signer''\n  or g.grant_epoch is distinct from p->>''grantEpoch'' or g.expiry<=(extract(epoch from clock_timestamp())*1000)::bigint\n  or (p->>''expiresAt'')::bigint<=(extract(epoch from clock_timestamp())*1000)::bigint or (p->>''expiresAt'')::bigint>g.expiry\n  or g.cap is null or g.cap=''NaN''::numeric or g.cap<0 or g.cap*1000000<>trunc(g.cap*1000000)\n  or g.cap*1000000>9007199254740991 or lifetime>g.cap*1000000 then return jsonb_build_object(''status'',''refused''); end if;\n select * into n from public.browser_signing_namespaces where namespace=ns for update;\n if found and (n.owner is distinct from p->>''owner'' or n.signer is distinct from p->>''signer'' or n.service is distinct from p->>''service''\n  or n.allocated_micro+ceiling>lifetime or n.jobs+1>jobs_limit) then return jsonb_build_object(''status'',''refused''); end if;\n if not found then\n  insert into public.browser_signing_namespaces(namespace,owner,signer,service,network,ceiling_micro,job_limit,ceiling_proof)\n   values(ns,p->>''owner'',p->>''signer'',p->>''service'',''eip155:5042002'',lifetime,jobs_limit,jsonb_build_object(''policy'',p,''signature'',p_verified->>''signature''));\n end if;\n insert into public.browser_signing_policies values(ns,p->>''policyId'',p_verified);\n insert into public.browser_signing_queries(namespace,query_id,request_nonce,policy_id,session_id,ceiling_micro)\n  values(ns,p->>''queryId'',p->>''requestNonce'',p->>''policyId'',p_session_id,ceiling);\n update public.browser_signing_namespaces set ceiling_micro=lifetime,job_limit=jobs_limit,ceiling_proof=jsonb_build_object(''policy'',p,''signature'',p_verified->>''signature''),allocated_micro=allocated_micro+ceiling,jobs=jobs+1 where namespace=ns;\n return jsonb_build_object(''status'',''admitted'',''namespace'',ns,''queryId'',p->>''queryId'');\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"browser_signing_admit_query","owner":"postgres","parallel":"u","result":"jsonb","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare p jsonb:=p_verified->''policy''; ns text:=p_verified->>''namespace''; n public.browser_signing_namespaces%rowtype;\n q public.browser_signing_queries%rowtype; saved jsonb; g public.session_grants%rowtype; ceiling bigint; lifetime bigint; jobs_limit bigint;\nbegin\n if (select active from public.browser_signing_v2_control where id=1) is distinct from true\n  or (select active from public.browser_journal_control where id=1) is distinct from true then return jsonb_build_object(''status'',''inactive''); end if;\n if p->>''protocol'' is distinct from ''durable-v2'' or p->>''service'' is distinct from ''https://keryx.cc''\n  or coalesce(ns,'''') !~ ''^0x[0-9a-f]{64}$'' or coalesce(p_verified->>''proofDigest'','''') !~ ''^0x[0-9a-f]{64}$''\n  or coalesce(p_verified->>''signature'','''') !~ ''^0x[0-9a-f]{130}$''\n  or coalesce(p->>''owner'','''') !~ ''^0x[0-9a-f]{40}$'' or coalesce(p->>''signer'','''') !~ ''^0x[0-9a-f]{40}$''\n  or coalesce(p->>''policyId'','''') !~ ''^0x[0-9a-f]{64}$'' or coalesce(p->>''requestNonce'','''') !~ ''^0x[0-9a-f]{64}$''\n  or coalesce(p->>''questionDigest'','''') !~ ''^0x[0-9a-f]{64}$''\n  or coalesce(p->>''queryCeilingMicros'','''') !~ ''^[1-9][0-9]{0,15}$'' or coalesce(p->>''lifetimeCeilingMicros'','''') !~ ''^[1-9][0-9]{0,15}$''\n  or coalesce(p->>''jobLimit'','''') !~ ''^[1-9][0-9]{0,15}$'' or coalesce(p->>''expiresAt'','''') !~ ''^[1-9][0-9]{0,15}$''\n  or coalesce(p_session_id,'''')='''' then raise exception ''browser query policy refused''; end if;\n perform (p->>''queryId'')::uuid; perform (p->>''grantEpoch'')::uuid;\n ceiling:=(p->>''queryCeilingMicros'')::bigint; lifetime:=(p->>''lifetimeCeilingMicros'')::bigint; jobs_limit:=(p->>''jobLimit'')::bigint;\n if ceiling>lifetime or lifetime>9007199254740991 or jobs_limit>9007199254740991 or (p->>''expiresAt'')::numeric>9007199254740991 then raise exception ''browser query policy refused''; end if;\n perform pg_advisory_xact_lock(hashtextextended(ns,0));\n select verified into saved from public.browser_signing_policies where namespace=ns and policy_id=p->>''policyId'';\n if found and saved is distinct from p_verified then raise exception ''browser query policy conflict''; end if;\n select * into q from public.browser_signing_queries where namespace=ns and (request_nonce=p->>''requestNonce'' or query_id=p->>''queryId'');\n if found then\n  if q.policy_id=p->>''policyId'' and q.query_id=p->>''queryId'' and q.request_nonce=p->>''requestNonce'' and q.session_id=p_session_id and saved=p_verified then\n   return jsonb_build_object(''status'',''admitted'',''namespace'',ns,''queryId'',q.query_id);\n  end if; raise exception ''browser query original conflict'';\n end if;\n select * into g from public.session_grants where session_id=p_session_id for update;\n if not found or lower(g.owner_addr) is distinct from p->>''owner'' or lower(g.sess_addr) is distinct from p->>''signer''\n  or g.grant_epoch is distinct from p->>''grantEpoch'' or g.expiry<=(extract(epoch from clock_timestamp())*1000)::bigint\n  or (p->>''expiresAt'')::bigint<=(extract(epoch from clock_timestamp())*1000)::bigint or (p->>''expiresAt'')::bigint>g.expiry\n  or g.cap is null or g.cap=''NaN''::numeric or g.cap<0 or g.cap*1000000<>trunc(g.cap*1000000)\n  or g.cap*1000000>9007199254740991 or lifetime>g.cap*1000000 then return jsonb_build_object(''status'',''refused''); end if;\n select * into n from public.browser_signing_namespaces where namespace=ns for update;\n if found and (n.owner is distinct from p->>''owner'' or n.signer is distinct from p->>''signer'' or n.service is distinct from p->>''service''\n  or n.allocated_micro+ceiling>lifetime or n.jobs+1>jobs_limit) then return jsonb_build_object(''status'',''refused''); end if;\n if not found then\n  insert into public.browser_signing_namespaces(namespace,owner,signer,service,network,ceiling_micro,job_limit,ceiling_proof)\n   values(ns,p->>''owner'',p->>''signer'',p->>''service'',''eip155:5042002'',lifetime,jobs_limit,jsonb_build_object(''policy'',p,''signature'',p_verified->>''signature''));\n end if;\n insert into public.browser_signing_policies values(ns,p->>''policyId'',p_verified);\n insert into public.browser_signing_queries(namespace,query_id,request_nonce,policy_id,session_id,ceiling_micro)\n  values(ns,p->>''queryId'',p->>''requestNonce'',p->>''policyId'',p_session_id,ceiling);\n update public.browser_signing_namespaces set ceiling_micro=lifetime,job_limit=jobs_limit,ceiling_proof=jsonb_build_object(''policy'',p,''signature'',p_verified->>''sign