r_signing_v2_control where id=1) is true and (select active from public.browser_journal_control where id=1) is true))\n from public.browser_signing_originals o join public.browser_signing_namespaces n on n.namespace=o.namespace\n join public.browser_signing_queries q on (q.namespace,q.query_id)=(o.namespace,o.query_id)\n join public.browser_signing_policies pol on (pol.namespace,pol.policy_id)=(q.namespace,q.policy_id)\n join public.payment_events p on p.id=''x402:''||o.nonce join public.browser_journal_bindings b on b.nonce=o.nonce\n join public.browser_signer_capacity c on c.signer=n.signer join public.browser_retained_grants r on r.grant_epoch=o.original->>''grantEpoch'' and r.signer=n.signer\n left join public.session_grants g on g.session_id=o.session_id\n where n.signer=lower(p_signer) and o.original#>>''{authorization,from}''=lower(p_signer)\n  and o.session_id=p_session_id and o.request_id=p_request_id\n  and p.authorization_phase in (''exposed'',''signed'',''submission_attempted'',''settled'',''failed'');\n$function$\n","kind":"f","language":"sql","leakproof":false,"name":"browser_signing_exposed_snapshot_for_signer","owner":"postgres","parallel":"u","result":"jsonb","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\n select jsonb_build_object(''original'',o.original,''journal'',o.journal||jsonb_strip_nulls(jsonb_build_object(''phase'',p.authorization_phase,\n  ''payment'',(o.journal->''payment'')||jsonb_build_object(''authorizationPhase'',p.authorization_phase,''settled'',p.settled,''settlementStatus'',p.settlement_status,''txHash'',p.tx_hash),\n  ''signedValidAfter'',b.valid_after,''signedValidBefore'',b.valid_before,''signedHeaderHash'',b.header_hash)),\n ''currentGrant'',case when g.session_id is null then null else jsonb_build_object(''sessionId'',g.session_id,''sessAddr'',g.sess_addr,''ownerAddr'',g.owner_addr,''cap'',g.cap,''spent'',g.spent,''expiry'',g.expiry,''txHash'',g.tx_hash,''grantEpoch'',g.grant_epoch) end,\n ''policy'',jsonb_build_object(''policy'',pol.verified->''policy'',''signature'',pol.verified->>''signature''),\n ''namespace'',jsonb_build_object(''namespace'',n.namespace,''owner'',n.owner,''signer'',n.signer,''service'',n.service,''network'',n.network,''ceilingMicros'',n.ceiling_micro::text,''jobLimit'',n.job_limit,''allocatedMicros'',n.allocated_micro::text,''jobs'',n.jobs,''ceilingProof'',n.ceiling_proof),\n ''query'',jsonb_build_object(''queryId'',q.query_id,''namespace'',q.namespace,''ceilingMicros'',q.ceiling_micro::text,''spentMicros'',q.spent_micro::text,''proofDigest'',pol.verified->>''proofDigest''),\n ''signerSpentMicros'',c.spent_micro::text,''retainedEpochSpentMicros'',r.spent_micro::text,''active'',\n  ((select active from public.browser_signing_v2_control where id=1) is true and (select active from public.browser_journal_control where id=1) is true))\n from public.browser_signing_originals o join public.browser_signing_namespaces n on n.namespace=o.namespace\n join public.browser_signing_queries q on (q.namespace,q.query_id)=(o.namespace,o.query_id)\n join public.browser_signing_policies pol on (pol.namespace,pol.policy_id)=(q.namespace,q.policy_id)\n join public.payment_events p on p.id=''x402:''||o.nonce join public.browser_journal_bindings b on b.nonce=o.nonce\n join public.browser_signer_capacity c on c.signer=n.signer join public.browser_retained_grants r on r.grant_epoch=o.original->>''grantEpoch'' and r.signer=n.signer\n left join public.session_grants g on g.session_id=o.session_id\n where n.signer=lower(p_signer) and o.original#>>''{authorization,from}''=lower(p_signer)\n  and o.session_id=p_session_id and o.request_id=p_request_id\n  and p.authorization_phase in (''exposed'',''signed'',''submission_attempted'',''settled'',''failed'');\n","strict":false,"support":null,"volatility":"s"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',176,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_signing_fresh_gate()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\nbegin\n if exists(select 1 from public.browser_signing_v2_barrier where id=1)\n  and not exists(select 1 from public.browser_signing_v2_writer where transaction_id=txid_current()) then raise exception ''browser signing v2 original required''; end if;\n if public.browser_signing_original_floor_for_write()=3\n  and not exists(select 1 from public.browser_signing_v3_writer where transaction_id=txid_current()) then raise exception ''browser signing v3 source original required''; end if;\n return new;\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"browser_signing_fresh_gate","owner":"postgres","parallel":"u","result":"trigger","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\nbegin\n if exists(select 1 from public.browser_signing_v2_barrier where id=1)\n  and not exists(select 1 from public.browser_signing_v2_writer where transaction_id=txid_current()) then raise exception ''browser signing v2 original required''; end if;\n if public.browser_signing_original_floor_for_write()=3\n  and not exists(select 1 from public.browser_signing_v3_writer where transaction_id=txid_current()) then raise exception ''browser signing v3 source original required''; end if;\n return new;\nend ","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',177,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_session_id text, p_request_id text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_signing_header_original(p_session_id text, p_request_id text)\n RETURNS jsonb\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\n select original from public.browser_signing_originals where session_id=p_session_id and request_id=p_request_id;\n$function$\n","kind":"f","language":"sql","leakproof":false,"name":"browser_signing_header_original","owner":"postgres","parallel":"u","result":"jsonb","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\n select original from public.browser_signing_originals where session_id=p_session_id and request_id=p_request_id;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',178,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_session_id text, p_request_id text, p_metadata jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_signing_legacy_signature_internal(p_session_id text, p_request_id text, p_metadata jsonb)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare v_nonce text; v_phase text; b public.browser_journal_bindings%rowtype;\nbegin\n  if coalesce(p_metadata->>''headerHash'','''') !~ ''^[0-9a-f]{64}$''\n     or coalesce(p_metadata->>''validAfter'','''') !~ ''^(0|[1-9][0-9]*)$''\n     or coalesce(p_metadata->>''validBefore'','''') !~ ''^(0|[1-9][0-9]*)$''\n     or (p_metadata->>''validAfter'')::numeric>(p_metadata->>''validBefore'')::numeric\n     or (p_metadata->>''validBefore'')::numeric>8640000000000 then raise exception ''Invalid browser signed metadata''; end if;\n  select i.nonce,p.authorization_phase into v_nonce,v_phase from public.browser_authorization_intents i join public.payment_events p on p.id=''x402:''||i.nonce\n    where i.session_id=p_session_id and i.request_id=p_request_id for update of p;\n  if not found or coalesce(v_phase,'''') not in (''exposed'',''signed'',''submission_attempted'',''settled'',''failed'') then return false; end if;\n  select * into b from public.browser_journal_bindings where nonce=v_nonce for update;\n  if b.header_hash is not null then return (b.header_hash,b.valid_after,b.valid_before) is not distinct from (p_metadata->>''headerHash'',p_metadata->>''validAfter'',p_metadata->>''validBefore''); end if;\n  if v_phase<>''exposed'' then return false; end if;\n  insert into public.browser_journal_writer values(txid_current());\n  update public.browser_journal_bindings set valid_after=p_metadata->>''validAfter'',valid_before=p_metadata->>''validBefore'',header_hash