c.browser_journal_bindings set valid_after=p_metadata->>''validAfter'',valid_before=p_metadata->>''validBefore'',header_hash=p_metadata->>''headerHash'' where nonce=v_nonce;\n  update public.payment_events set authorization_phase=''signed'',authorization_expires_at=to_timestamp((p_metadata->>''validBefore'')::double precision) where id=''x402:''||v_nonce;\n  delete from public.browser_journal_writer where transaction_id=txid_current();\n  return true;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',179,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.browser_signing_original_floor_for_write()\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare minimum integer; control_minimum integer;\nbegin\n -- The barrier starts empty. Lock the always-present control first so a stale\n -- snapshot predating the first barrier INSERT cannot fall back to floor2.\n select min_original_version into control_minimum from public.browser_signing_v2_control where id=1 for share;\n if not found then raise exception ''browser signing control missing''; end if;\n select min_original_version into minimum from public.browser_signing_v2_barrier where id=1 for share;\n return greatest(control_minimum,coalesce(minimum,2));\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"browser_signing_original_floor_for_write","owner":"postgres","parallel":"u","result":"integer","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare minimum integer; control_minimum integer;\nbegin\n -- The barrier starts empty. Lock the always-present control first so a stale\n -- snapshot predating the first barrier INSERT cannot fall back to floor2.\n select min_original_version into control_minimum from public.browser_signing_v2_control where id=1 for share;\n if not found then raise exception ''browser signing control missing''; end if;\n select min_original_version into minimum from public.browser_signing_v2_barrier where id=1 for share;\n return greatest(control_minimum,coalesce(minimum,2));\nend ","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
