nfirmation is null and exists (\n    select 1 from public.private_research_intents i where i.id=p.id and i.payer=lower(p_payer)\n  );\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',200,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_hash text, p_now bigint","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.consume_auth_challenge(p_hash text, p_now bigint)\n RETURNS boolean\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare\n  affected integer;\nbegin\n  delete from public.auth_challenges where hash = p_hash and issued_at <= p_now and expires_at > p_now;\n  get diagnostics affected = row_count;\n  return affected = 1;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"consume_auth_challenge","owner":"postgres","parallel":"u","result":"boolean","returnsSet":false,"rows":"0","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare\n  affected integer;\nbegin\n  delete from public.auth_challenges where hash = p_hash and issued_at <= p_now and expires_at > p_now;\n  get diagnostics affected = row_count;\n  return affected = 1;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',201,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_bucket text, p_points integer, p_window_ms bigint, p_now bigint","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.consume_rate_limit(p_bucket text, p_points integer, p_window_ms bigint, p_now bigint)\n RETURNS TABLE(allowed boolean, ms_before_next bigint)\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare\n  v_count    integer;\n  v_reset_at bigint;\nbegin\n  insert into public.rate_limit_counters (bucket, count, reset_at)\n       values (p_bucket, 1, p_now + p_window_ms)\n  on conflict (bucket) do update\n       set count    = case when public.rate_limit_counters.reset_at <= p_now then 1\n                           else public.rate_limit_counters.count + 1 end,\n           reset_at = case when public.rate_limit_counters.reset_at <= p_now\n                           then p_now + p_window_ms\n                           else public.rate_limit_counters.reset_at end\n    returning count, reset_at into v_count, v_reset_at;\n\n  return query select v_count <= p_points, greatest(0, v_reset_at - p_now);\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"consume_rate_limit","owner":"postgres","parallel":"u","result":"TABLE(allowed boolean, ms_before_next bigint)","returnsSet":true,"rows":"1000","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare\n  v_count    integer;\n  v_reset_at bigint;\nbegin\n  insert into public.rate_limit_counters (bucket, count, reset_at)\n       values (p_bucket, 1, p_now + p_window_ms)\n  on conflict (bucket) do update\n       set count    = case when public.rate_limit_counters.reset_at <= p_now then 1\n                           else public.rate_limit_counters.count + 1 end,\n           reset_at = case when public.rate_limit_counters.reset_at <= p_now\n                           then p_now + p_window_ms\n                           else public.rate_limit_counters.reset_at end\n    returning count, reset_at into v_count, v_reset_at;\n\n  return query select v_count <= p_points, greatest(0, v_reset_at - p_now);\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',202,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_hash text, p_issued_at bigint, p_expires_at bigint","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.create_auth_challenge(p_hash text, p_issued_at bigint, p_expires_at bigint)\n RETURNS void\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\nbegin\n  delete from public.auth_challenges where expires_at <= p_issued_at;\n  insert into public.auth_challenges(hash, issued_at, expires_at) values (p_hash, p_issued_at, p_expires_at);\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"create_auth_challenge","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\nbegin\n  delete from public.auth_challenges where expires_at <= p_issued_at;\n  insert into public.auth_challenges(hash, issued_at, expires_at) values (p_hash, p_issued_at, p_expires_at);\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',203,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_gap_id text, p_claim text, p_question text, p_failed_query_id text, p_source_id text, p_source_item_link text, p_item_id text, p_content_version text, p_article_offer_id text, p_owner_wallet text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.create_gap_intent(p_id text, p_gap_id text, p_claim text, p_question text, p_failed_query_id text, p_source_id text, p_source_item_link text, p_item_id text, p_content_version text, p_article_offer_id text, p_owner_wallet text)\n RETURNS SETOF public.gap_intents\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare\n  v_existing public.gap_intents%rowtype;\nbegin\n  perform pg_advisory_xact_lock(hashtext(p_gap_id), hashtext(lower(p_owner_wallet)));\n\n  select * into v_existing\n    from public.gap_intents\n   where gap_id = p_gap_id\n     and lower(owner_wallet) = lower(p_owner_wallet)\n   order by created_at asc\n   limit 1;\n\n  if found then\n    return next v_existing;\n    return;\n  end if;\n\n  return query\n  insert into public.gap_intents (\n    id, gap_id, claim, question, failed_query_id, source_id, source_item_link,\n    item_id, content_version, article_offer_id, owner_wallet,\n    status, attempts, created_at, updated_at\n  ) values (\n    p_id, p_gap_id, p_claim, p_question, p_failed_query_id, p_source_id,\n    p_source_item_link, p_item_id, p_content_version, p_article_offer_id,\n    lower(p_owner_wallet), ''pending'', 0, now(), now()\n  )\n  returning *;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"create_gap_intent","owner":"postgres","parallel":"u","result":"SETOF public.gap_intents","returnsSet":true,"rows":"1000","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare\n  v_existing public.gap_intents%rowtype;\nbegin\n  perform pg_advisory_xact_lock(hashtext(p_gap_id), hashtext(lower(p_owner_wallet)));\n\n  select * into v_existing\n    from public.gap_intents\n   where gap_id = p_gap_id\n     and lower(owner_wallet) = lower(p_owner_wallet)\n   order by created_at asc\n   limit 1;\n\n  if found then\n    return next v_existing;\n    return;\n  end if;\n\n  return query\n  insert into public.gap_intents (\n    id, gap_id, claim, question, failed_query_id, source_id, source_item_link,\n    item_id, content_version, article_offer_id, owner_wallet,\n    status, attempts, created_at, updated_at\n  ) values (\n    p_id, p_gap_id, p_claim, p_question, p_failed_query_id, p_source_id,\n    p_source_item_link, p_item_id, p_content_version, p_article_offer_id,\n    lower(p_owner_wallet), ''pending'', 0, now(), now()\n  )\n  returning *;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',204,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_hash text, p_wallet text, p_issued_at bigint, p_expires_at bigint","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.create_web_session(p_hash text, p_wallet text, p_issued_at bigint, p_expires_at bigint)\n RETURNS void\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\nbegin\n  delete from public.web_sessions where expires_at <= p_issued_at;\n  insert into public.web_sessions(hash,wallet,issued_at,expires_at) values (p_hash,lower(p_wallet),p_issued_at,p_expires_at);\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"create_web_session","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\nbegin\n  delete from public.web_sessions where expires_at <= p_issued_at;\n  insert into public.web_sessions(hash,wallet,issued_at,expires_at) values (p_hash,lower(p_wallet),p_issued_at,p_expires_at);\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',205,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_session_id text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.disable_browser_journal_grant(p_session_id text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\nbegin\n  if not (select active from public.browser_journal_control where id=1) then raise exception ''browser journal inactive''; end if;\n  insert into public.browser_journal_writer values(txid_current());\n  update public.session_grants set expiry=0 where session_id=p_session_id;\n  delete from public.browser_journal_writer where transaction_id=txid_current();\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"disable_browser_journal_grant","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\nbegin\n  if not (select active from public.browser_journal_control where id=1) then raise exception ''browser journal inactive''; end if;\n  insert into public.browser_journal_writer values(txid_current());\n  update public.session_grants set expiry=0 where session_id=p_session_id;\n  delete from public.browser_journal_writer where transaction_id=txid_current();\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
