('after','functions',207,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_expected_identity jsonb, p_operation text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION keryx_storage.enter_operation(p_expected_identity jsonb, p_operation text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare selected text; policy record;\nbegin\n  selected := keryx_storage.require_identity(p_expected_identity);\n  if p_operation is null or p_operation = '''' then raise exception ''storage operation refused''; end if;\n  select * into policy from keryx_storage.operations where operation=p_operation;\n  if not found or policy.read_only or (policy.real_only and p_expected_identity->>''authorityMode''<>''testnet-real'') then\n    raise exception ''storage authority mode refused'';\n  end if;\n  if exists(select 1 from keryx_storage.writer where transaction_id=txid_current()) then raise exception ''nested storage operation refused''; end if;\n  insert into keryx_storage.writer values(txid_current(),selected,p_operation);\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"enter_operation","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"keryx_storage","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare selected text; policy record;\nbegin\n  selected := keryx_storage.require_identity(p_expected_identity);\n  if p_operation is null or p_operation = '''' then raise exception ''storage operation refused''; end if;\n  select * into policy from keryx_storage.operations where operation=p_operation;\n  if not found or policy.read_only or (policy.real_only and p_expected_identity->>''authorityMode''<>''testnet-real'') then\n    raise exception ''storage authority mode refused'';\n  end if;\n  if exists(select 1 from keryx_storage.writer where transaction_id=txid_current()) then raise exception ''nested storage operation refused''; end if;\n  insert into keryx_storage.writer values(txid_current(),selected,p_operation);\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',208,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_error text, p_max_attempts integer","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.fail_gap_intent(p_id text, p_error text, p_max_attempts integer)\n RETURNS void\n LANGUAGE sql\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\n  update public.gap_intents\n     set status = case\n           when attempts >= greatest(1, p_max_attempts) then ''failed''\n           else ''pending''\n         end,\n         last_error = left(p_error, 500),\n         lease_expires_at = null,\n         updated_at = now()\n   where id = p_id\n     and status = ''running'';\n$function$\n","kind":"f","language":"sql","leakproof":false,"name":"fail_gap_intent","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\n  update public.gap_intents\n     set status = case\n           when attempts >= greatest(1, p_max_attempts) then ''failed''\n           else ''pending''\n         end,\n         last_error = left(p_error, 500),\n         lease_expires_at = null,\n         updated_at = now()\n   where id = p_id\n     and status = ''running'';\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',209,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_authorization_id text, p_circle_transfer_id text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.fail_pending_payment(p_id text, p_authorization_id text, p_circle_transfer_id text)\n RETURNS TABLE(resolved boolean, reservation_released boolean)\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare\n  v_payer text;\n  v_amount numeric;\n  v_grant_epoch text;\n  v_released integer := 0;\nbegin\n  select payer, amount_usdc, grant_epoch\n    into v_payer, v_amount, v_grant_epoch\n    from public.payment_events\n   where id = p_id\n     and authorization_id = p_authorization_id\n     and settled = false\n     and settlement_status = ''pending''\n   for update;\n\n  if not found then\n    return query select false, false;\n    return;\n  end if;\n\n  update public.payment_events\n     set settlement_status = ''failed'', tx_hash = p_circle_transfer_id\n   where id = p_id\n     and authorization_id = p_authorization_id\n     and settled = false\n     and settlement_status = ''pending'';\n\n  if v_grant_epoch is not null then\n    update public.session_grants\n       set spent = greatest(0, round(spent - v_amount, 6))\n     where grant_epoch = v_grant_epoch\n       and lower(sess_addr) = lower(v_payer);\n    get diagnostics v_released = row_count;\n  end if;\n\n  return query select true, v_released = 1;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"fail_pending_payment","owner":"postgres","parallel":"u","result":"TABLE(resolved boolean, reservation_released boolean)","returnsSet":true,"rows":"1000","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare\n  v_payer text;\n  v_amount numeric;\n  v_grant_epoch text;\n  v_released integer := 0;\nbegin\n  select payer, amount_usdc, grant_epoch\n    into v_payer, v_amount, v_grant_epoch\n    from public.payment_events\n   where id = p_id\n     and authorization_id = p_authorization_id\n     and settled = false\n     and settlement_status = ''pending''\n   for update;\n\n  if not found then\n    return query select false, false;\n    return;\n  end if;\n\n  update public.payment_events\n     set settlement_status = ''failed'', tx_hash = p_circle_transfer_id\n   where id = p_id\n     and authorization_id = p_authorization_id\n     and settled = false\n     and settlement_status = ''pending'';\n\n  if v_grant_epoch is not null then\n    update public.session_grants\n       set spent = greatest(0, round(spent - v_amount, 6))\n     where grant_epoch = v_grant_epoch\n       and lower(sess_addr) = lower(v_payer);\n    get diagnostics v_released = row_count;\n  end if;\n\n  return query select true, v_released = 1;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',210,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_session_id text, p_request_id text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.get_browser_journal(p_session_id text, p_request_id text)\n RETURNS jsonb\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\n  select jsonb_build_object(''intent'',to_jsonb(i),''binding'',to_jsonb(b),''payment'',to_jsonb(p))\n  from public.browser_authorization_intents i join public.browser_journal_bindings b using(nonce)\n  join public.payment_events p on p.id=''x402:''||i.nonce\n  where i.session_id=p_session_id and i.request_id=p_request_id;\n$function$\n","kind":"f","language":"sql","leakproof":false,"name":"get_browser_journal","owner":"postgres","parallel":"u","result":"jsonb","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\n  select jsonb_build_object(''intent'',to_jsonb(i),''binding'',to_jsonb(b),''payment'',to_jsonb(p))\n  from public.browser_authorization_intents i join public.browser_journal_bindings b using(nonce)\n  join public.payment_events p on p.id=''x402:''||i.nonce\n  where i.session_id=p_session_id and i.request_id=p_request_id;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',211,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_identity jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION keryx_storage.identity_digest(p_identity jsonb)\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare result text := ''{''; k text; separator text := '''';\nbegin\n  perform keryx_storage.validate_identity(p_identity);\n  foreach k in array array[''format'',''deploymentId'',''storageId'',''network'',''authorityMode'',''profileDigest'',''enrollmentId'',''enrolledAt'',''provenanceDigest''] loop\n    result := result || separator || to_json(k)::text || '':'' || to_json(p_identity->>k)::text;\n    separator := '','';\n  end loop;\n  return encode(sha256(convert_to(result || ''}'',''UTF8'')),''hex'');\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"identity_digest","owner":"postgres","parallel":"u","result":"text","returnsSet":false,"rows":"0","schema":"keryx_storage","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare result text := ''{''; k text; separator text := '''';\nbegin\n  perform keryx_storage.validate_identity(p_identity);\n  foreach k in array array[''format'',''deploymentId'',''storageId'',''network'',''authorityMode'',''profileDigest'',''enrollmentId'',''enrolledAt'',''provenanceDigest''] loop\n    result := result || separator || to_json(k)::text || '':'' || to_json(p_identity->>k)::text;\n    separator := '','';\n  end loop;\n  return encode(sha256(convert_to(result || ''}'',''UTF8'')),''hex'');\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',212,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION keryx_storage.identity_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\nbegin raise exception ''storage identity is immutable''; end;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"identity_immutable","owner":"postgres","parallel":"u","result":"trigger","returnsSet":false,"rows":"0","schema":"keryx_storage","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\nbegin raise exception ''storage identity is immutable''; end;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',213,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_day date, p_event text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.increment_activation_event(p_day date, p_event text)\n RETURNS void\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\nbegin\n  insert into public.activation_events(day, event, count)\n  values (p_day, p_event, 1)\n  on conflict (day, event) do update\n    set count = public.activation_events.count + 1;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"increment_activation_event","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\nbegin\n  insert into public.activation_events(day, event, count)\n  values (p_day, p_event, 1)\n  on conflict (day, event) do update\n    set count = public.activation_events.count + 1;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',214,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION keryx_storage.install_fixed_fences()\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare relation record; column_row record; f record; retained_count bigint; retained_bytes bigint;\nbegin\n  if current_setting(''statement_timeout'')::interval<=interval ''0''\n    or current_setting(''statement_timeout'')::interval>interval ''30 seconds'' then\n    raise exception ''bounded owner statement deadline required'';\n  end if;\n  perform pg_advisory_xact_lock(634781904177021::bigint);\n  if exists(select 1 from keryx_storage.identity) then raise exception ''already enrolled store''; end if;\n  for relation in select c.oid,c.relname from pg_class c where c.relnamespace=''public''::regnamespace\n    and c.relkind in (''r'',''p'') order by c.relname loop\n    execute format(''lock table public.%I in share row exclusive mode'',relation.relname);\n  end loop;\n  select count(*),coalesce(sum(octet_length(text)),0) into retained_count,retained_bytes\n    from public.cache_items where text is not null;\n  if retained_count>512 or retained_bytes>8388608 or exists(select 1 from public.cache_items\n    where text is not null and (octet_length(text)>2097152 or octet_length(source_id)>512)) then\n    raise exception ''storage cache quota refused'';\n  end if;\n  if exists(select 1 from keryx_storage.cache_quota) then raise exception ''cache quota already initialized''; end if;\n  insert into keryx_storage.cache_quota values(true,retained_count,retained_bytes);\n  for relation in select c.oid,c.relname from pg_class c where c.relnamespace=''public''::regnamespace\n    and c.relkind in (''r'',''p'') order by c.relname loop\n    execute format(''revoke all on table public.%I from public,anon,authenticated,service_role'',relation.relname);\n    for column_row in select attname from pg_attribute where attrelid=relation.oid and attnum>0 and not attisdropped loop\n      execute format(''revoke all(%I) on table public.%I from public,anon,authenticated,service_role'',column_row.attname,relation.relname);\n    end loop;\n    execute format(''create trigger storage_authority_writer before insert or update or delete on public.%I for each row execute function keryx_storage.write_fence()'',relation.relname);\n    execute format(''create trigger storage_authority_no_truncate before truncate on public.%I for each statement execute function keryx_storage.write_fence()'',relation.relname);\n  end loop;\n  -- AFTER avoids double-counting speculative INSERT before ON CONFLICT UPDATE.\n  -- A rejected quota update still rolls back the complete public-row mutation.\n  create trigger storage_cache_quota after insert or update or delete on public.cache_items\n    for each row execute function keryx_storage.cache_quota_write();\n  revoke all on all sequences in schema public from public,anon,authenticated,service_role;\n  revoke create on schema public from public,anon,authenticated,service_role;\n  alter default privileges in schema public revoke all on tables from public,anon,authenticated,service_role;\n  alter default privileges in schema public revoke all on sequences from public,anon,authenticated,service_role;\n  alter default privileges in schema public revoke execute on functions from public,anon,authenticated,service_role;\n  for f in select p.oid::regprocedure signature,p.proname from pg_proc p\n    where p.pronamespace=''public''::regnamespace and p.prokind=''f'' order by p.proname,p.oid loop\n    execute ''revoke all on function ''||f.signature||'' from public,anon,authenticated,service_role'';\n    if f.proname=''read_storage_identity'' or f.proname like ''storage\\_%'' escape ''\\'' then\n      execute ''grant execute on function ''||f.signature||'' to service_role'';\n    else\n      -- Explicit pg_temp LAST protects existing invoker/definer domain bodies\n      -- from temporary relation shadowing after the owner-only ACL cutover.\n      execute ''alter function ''||f.signature||'' set search_path to pg_catalog,public,pg_temp'';\n    end if;\n  end loop;\nend; $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"install_fixed_fences","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"keryx_storage","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare relation record; column_row record; f record; retained_count bigint; retained_bytes bigint;\nbegin\n  if current_setting(''statement_timeout'')::interval<=interval ''0''\n    or current_setting(''statement_timeout'')::interval>interval ''30 seconds'' then\n    raise exception ''bounded owner statement deadline required'';\n  end if;\n  perform pg_advisory_xact_lock(634781904177021::bigint);\n  if exists(select 1 from keryx_storage.identity) then raise exception ''already enrolled store''; end if;\n  for relation in select c.oid,c.relname from pg_class c where c.relnamespace=''public''::regnamespace\n    and c.relkind in (''r'',''p'') order by c.relname loop\n    execute format(''lock table public.%I in share row exclusive mode'',relation.relname);\n  end loop;\n  select count(*),coalesce(sum(octet_length(text)),0) into retained_count,retained_bytes\n    from public.cache_items where text is not null;\n  if retained_count>512 or retained_bytes>8388608 or exists(select 1 from public.cache_items\n    where text is not null and (octet_length(text)>2097152 or octet_length(source_id)>512)) then\n    raise exception ''storage cache quota refused'';\n  end if;\n  if exists(select 1 from keryx_storage.cache_quota) then raise exception ''cache quota already initialized''; end if;\n  insert into keryx_storage.cache_quota values(true,retained_count,retained_bytes);\n  for relation in select c.oid,c.relname from pg_class c where c.relnamespace=''public''::regnamespace\n    and c.relkind in (''r'',''p'') order by c.relname loop\n    execute format(''revoke all on table public.%I from public,anon,authenticated,service_role'',relation.relname);\n    for column_row in select attname from pg_attribute where attrelid=relation.oid and attnum>0 and not attisdropped loop\n      execute format(''revoke all(%I) on table public.%I from public,anon,authenticated,service_role'',column_row.attname,relation.relname);\n    end loop;\n    execute format(''create trigger storage_authority_writer before insert or update or delete on public.%I for each row execute function keryx_storage.write_fence()'',relation.relname);\n    execute format(''create trigger storage_authority_no_truncate before truncate on public.%I for each statement execute function keryx_storage.write_fence()'',relation.relname);\n  end loop;\n  -- AFTER avoids double-counting speculative INSERT before ON CONFLICT UPDATE.\n  -- A rejected quota update still rolls back the complete public-row mutation.\n  create trigger storage_cache_quota after insert or update or delete on public.cache_items\n    for each row execute function keryx_storage.cache_quota_write();\n  revoke all on all sequences in schema public from public,anon,authenticated,service_role;\n  revoke create on schema public from public,anon,authenticated,service_role;\n  alter default privileges in schema public revoke all on tables from public,anon,authenticated,service_role;\n  alter default privileges in schema public revoke all on sequences from public,anon,authenticated,service_role;\n  alter default privileges in schema public revoke execute on functions from public,anon,authenticated,service_role;\n  for f in select p.oid::regprocedure signature,p.proname from pg_proc p\n    where p.pronamespace=''public''::regnamespace and p.prokind=''f'' order by p.proname,p.oid loop\n    execute ''revoke all on function ''||f.signature||'' from public,anon,authenticated,service_role'';\n    if f.proname=''read_storage_identity'' or f.proname like ''storage\\_%'' escape ''\\'' then\n      execute ''grant execute on function ''||f.signature||'' to service_role'';\n    else\n      -- Explicit pg_temp LAST protects existing invoker/definer domain bodies\n      -- from temporary relation shadowing after the owner-only ACL cutover.\n      execute ''alter function ''||f.signature||'' set search_path to pg_catalog,public,pg_temp'';\n    end if;\n  end loop;\nend; ","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',215,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_payer text, p_worker_id uuid","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.interrupt_private_research(p_id text, p_payer text, p_worker_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\nbegin\n  -- Same serialization point as creator admission and result saving.\n  perform e.id from public.private_research_executions e join public.private_research_intents i on i.id=e.id\n    where e.id=p_id and e.worker_id=p_worker_id and i.payer=lower(p_payer) for update of e;\n  if not found then return; end if;\n  if exists(select 1 from public.private_research_results where id=p_id) then return; end if;\n  insert into public.private_research_interruptions(id,worker_id,reason)\n    values(p_id,p_worker_id,''worker-interrupted'') on conflict(id) do nothing;\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"interrupt_private_research","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\nbegin\n  -- Same serialization point as creator admission and result saving.\n  perform e.id from public.private_research_executions e join public.private_research_intents i on i.id=e.id\n    where e.id=p_id and e.worker_id=p_worker_id and i.payer=lower(p_payer) for update of e;\n  if not found then return; end if;\n  if exists(select 1 from public.private_research_results where id=p_id) then return; end if;\n  insert into public.private_research_interruptions(id,worker_id,reason)\n    values(p_id,p_worker_id,''worker-interrupted'') on conflict(id) do nothing;\nend ","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',216,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION keryx_storage.leave_operation()\n RETURNS void\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\n  delete from keryx_storage.writer where transaction_id=txid_current();\n$function$\n","kind":"f","language":"sql","leakproof":false,"name":"leave_operation","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"keryx_storage","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\n  delete from keryx_storage.writer where transaction_id=txid_current();\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',217,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_wallet text, p_before_created_at timestamp with time zone, p_before_id text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.list_a2a_orders_for_payer(p_wallet text, p_before_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id text DEFAULT NULL::text)\n RETURNS SETOF public.a2a_orders\n LANGUAGE sql\n STABLE\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\n  select * from public.a2a_orders\n  where lower(payer) = lower(p_wallet)\n    and ((p_before_created_at is null and p_before_id is null)\n      or (p_before_created_at is not null and p_before_id is not null\n        and (created_at < p_before_created_at or (created_at = p_before_created_at and id < p_before_id))))\n  order by created_at desc, id desc limit 26;\n$function$\n","kind":"f","language":"sql","leakproof":false,"name":"list_a2a_orders_for_payer","owner":"postgres","parallel":"u","result":"SETOF public.a2a_orders","returnsSet":true,"rows":"1000","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\n  select * from public.a2a_orders\n  where lower(payer) = lower(p_wallet)\n    and ((p_before_created_at is null and p_before_id is null)\n      or (p_before_created_at is not null and p_before_id is not null\n        and (created_at < p_before_created_at or (created_at = p_before_created_at and id < p_before_id))))\n  order by created_at desc, id desc limit 26;\n","strict":false,"support":null,"volatility":"s"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',218,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_signer text, p_after text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.list_private_reconciliation_candidates(p_signer text, p_after text DEFAULT NULL::text)\n RETURNS TABLE(id text, payer text)\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\nBEGIN\n  IF p_signer IS NULL OR p_signer !~ ''^0x[0-9a-f]{40}$''\n    OR p_signer = ''0x0000000000000000000000000000000000000000''\n    OR (p_after IS NOT NULL AND p_after !~ ''^prv_[0-9a-f]{64}$'') THEN\n    RAISE EXCEPTION ''Invalid private reconciliation selection'';\n  END IF;\n  RETURN QUERY SELECT i.id, i.payer FROM public.private_treasury_reservations r\n    JOIN public.private_research_intents i ON i.id = r.job_id\n    WHERE r.signer = p_signer AND (p_after IS NULL OR i.id > p_after)\n    ORDER BY i.id ASC LIMIT 1;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"list_private_reconciliation_candidates","owner":"postgres","parallel":"u","result":"TABLE(id text, payer text)","returnsSet":true,"rows":"1000","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\nBEGIN\n  IF p_signer IS NULL OR p_signer !~ ''^0x[0-9a-f]{40}$''\n    OR p_signer = ''0x0000000000000000000000000000000000000000''\n    OR (p_after IS NOT NULL AND p_after !~ ''^prv_[0-9a-f]{64}$'') THEN\n    RAISE EXCEPTION ''Invalid private reconciliation selection'';\n  END IF;\n  RETURN QUERY SELECT i.id, i.payer FROM public.private_treasury_reservations r\n    JOIN public.private_research_intents i ON i.id = r.job_id\n    WHERE r.signer = p_signer AND (p_after IS NULL OR i.id > p_after)\n    ORDER BY i.id ASC LIMIT 1;\nEND;\n","strict":false,"support":null,"volatility":"s"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',219,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_signer text, p_after text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.list_private_worker_candidates(p_signer text, p_after text DEFAULT NULL::text)\n RETURNS TABLE(id text, payer text)\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\nBEGIN\n  IF p_signer IS NULL OR p_signer !~ ''^0x[0-9a-f]{40}$''\n    OR p_signer = ''0x0000000000000000000000000000000000000000''\n    OR (p_after IS NOT NULL AND p_after !~ ''^prv_[0-9a-f]{64}$'') THEN\n    RAISE EXCEPTION ''Invalid private worker selection'';\n  END IF;\n  RETURN QUERY SELECT i.id, i.payer FROM public.private_treasury_reservations r\n    JOIN public.private_research_intents i ON i.id = r.job_id\n    JOIN public.private_research_payment_attempts p ON p.id = i.id\n    LEFT JOIN public.private_research_executions e ON e.id = i.id\n    WHERE r.signer = p_signer AND p.confirmation IS NOT NULL AND p.settled_at IS NOT NULL\n      AND e.id IS NULL AND (p_after IS NULL OR i.id > p_after)\n    ORDER BY i.id ASC LIMIT 25;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"list_private_worker_candidates","owner":"postgres","parallel":"u","result":"TABLE(id text, payer text)","returnsSet":true,"rows":"1000","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\nBEGIN\n  IF p_signer IS NULL OR p_signer !~ ''^0x[0-9a-f]{40}$''\n    OR p_signer = ''0x0000000000000000000000000000000000000000''\n    OR (p_after IS NOT NULL AND p_after !~ ''^prv_[0-9a-f]{64}$'') THEN\n    RAISE EXCEPTION ''Invalid private worker selection'';\n  END IF;\n  RETURN QUERY SELECT i.id, i.payer FROM public.private_treasury_reservations r\n    JOIN public.private_research_intents i ON i.id = r.job_id\n    JOIN public.private_research_payment_attempts p ON p.id = i.id\n    LEFT JOIN public.private_research_executions e ON e.id = i.id\n    WHERE r.signer = p_signer AND p.confirmation IS NOT NULL AND p.settled_at IS NOT NULL\n      AND e.id IS NULL AND (p_after IS NULL OR i.id > p_after)\n    ORDER BY i.id ASC LIMIT 25;\nEND;\n","strict":false,"support":null,"volatility":"s"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',220,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_started_at timestamp with time zone","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.mark_a2a_payment_started(p_id text, p_started_at timestamp with time zone)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\nDECLARE\n  changed integer;\nBEGIN\n  UPDATE public.a2a_orders\n     SET payment_started_at = COALESCE(payment_started_at, p_started_at),\n         updated_at = p_started_at\n   WHERE id = p_id\n     AND status = ''running''\n     AND started_at IS NOT NULL\n     AND execution_journal_version = 1;\n  GET DIAGNOSTICS changed = ROW_COUNT;\n  RETURN changed = 1;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"mark_a2a_payment_started","owner":"postgres","parallel":"u","result":"boolean","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\nDECLARE\n  changed integer;\nBEGIN\n  UPDATE public.a2a_orders\n     SET payment_started_at = COALESCE(payment_started_at, p_started_at),\n         updated_at = p_started_at\n   WHERE id = p_id\n     AND status = ''running''\n     AND started_at IS NOT NULL\n     AND execution_journal_version = 1;\n  GET DIAGNOSTICS changed = ROW_COUNT;\n  RETURN changed = 1;\nEND;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',221,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_started_at timestamp with time zone","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.mark_a2a_result_saving(p_id text, p_started_at timestamp with time zone)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\nDECLARE\n  changed integer;\nBEGIN\n  UPDATE public.a2a_orders\n     SET result_saving_at = COALESCE(result_saving_at, p_started_at),\n         updated_at = p_started_at\n   WHERE id = p_id\n     AND status = ''running''\n     AND started_at IS NOT NULL\n     AND execution_journal_version = 1;\n  GET DIAGNOSTICS changed = ROW_COUNT;\n  RETURN changed = 1;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"mark_a2a_result_saving","owner":"postgres","parallel":"u","result":"boolean","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\nDECLARE\n  changed integer;\nBEGIN\n  UPDATE public.a2a_orders\n     SET result_saving_at = COALESCE(result_saving_at, p_started_at),\n         updated_at = p_started_at\n   WHERE id = p_id\n     AND status = ''running''\n     AND started_at IS NOT NULL\n     AND execution_journal_version = 1;\n  GET DIAGNOSTICS changed = ROW_COUNT;\n  RETURN changed = 1;\nEND;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',222,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_signer text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.private_treasury_summary(p_signer text)\n RETURNS TABLE(capacity text, allocated text, committed text, confirmed text, invalid text)\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\nBEGIN\n  IF p_signer IS NULL OR p_signer !~ ''^0x[0-9a-f]{40}$''\n    OR p_signer = ''0x0000000000000000000000000000000000000000'' THEN\n    RAISE EXCEPTION ''Invalid private treasury selection'';\n  END IF;\n  RETURN QUERY WITH legs AS (\n    SELECT s.amount_micros,\n      CASE WHEN\n        (s.data#>>''{submission,amountMicros}'') IS DISTINCT FROM s.amount_micros::text OR\n        (s.data#>>''{submission,payer}'') IS DISTINCT FROM r.signer OR\n        (c.authorization_id IS NOT NULL AND (\n        (c.data->''submission'') IS DISTINCT FROM (s.data->''submission'') OR\n        NOT (COALESCE(c.data->>''source'','''')=''circle-facilitator-success'' OR\n          (COALESCE(c.data->>''source'','''')=''circle-transfer-search'' AND\n           COALESCE(c.data->>''transferStatus'','''') IN (''received'',''batched'',''confirmed'',''completed'')))\n      )) THEN 1 ELSE 0 END AS bad,\n      CASE WHEN c.data->>''source''=''circle-facilitator-success'' OR\n        (c.data->>''source''=''circle-transfer-search'' AND c.data->>''transferStatus'' IN (''confirmed'',''completed''))\n      THEN s.amount_micros ELSE 0 END AS settled\n    FROM public.private_treasury_reservations r JOIN public.private_creator_submissions s ON s.job_id=r.job_id\n    LEFT JOIN public.private_creator_confirmations c ON c.authorization_id=s.authorization_id WHERE r.signer=p_signer\n  ) SELECT p.capacity_micros::text,\n    COALESCE((SELECT SUM(r.amount_micros-COALESCE(x.amount_micros,0)) FROM public.private_treasury_reservations r\n      LEFT JOIN public.private_treasury_releases x ON x.job_id=r.job_id WHERE r.signer=p.signer),0)::text,\n    COALESCE((SELECT SUM(l.amount_micros) FROM legs l),0)::text,\n    COALESCE((SELECT SUM(l.settled) FROM legs l),0)::text,\n    COALESCE((SELECT SUM(l.bad) FROM legs l),0)::text\n    FROM public.private_treasury_pools p WHERE p.signer=p_signer;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"private_treasury_summary","owner":"postgres","parallel":"u","result":"TABLE(capacity text, allocated text, committed text, confirmed text, invalid text)","returnsSet":true,"rows":"1000","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\nBEGIN\n  IF p_signer IS NULL OR p_signer !~ ''^0x[0-9a-f]{40}$''\n    OR p_signer = ''0x0000000000000000000000000000000000000000'' THEN\n    RAISE EXCEPTION ''Invalid private treasury selection'';\n  END IF;\n  RETURN QUERY WITH legs AS (\n    SELECT s.amount_micros,\n      CASE WHEN\n        (s.data#>>''{submission,amountMicros}'') IS DISTINCT FROM s.amount_micros::text OR\n        (s.data#>>''{submission,payer}'') IS DISTINCT FROM r.signer OR\n        (c.authorization_id IS NOT NULL AND (\n        (c.data->''submission'') IS DISTINCT FROM (s.data->''submission'') OR\n        NOT (COALESCE(c.data->>''source'','''')=''circle-facilitator-success'' OR\n          (COALESCE(c.data->>''source'','''')=''circle-transfer-search'' AND\n           COALESCE(c.data->>''transferStatus'','''') IN (''received'',''batched'',''confirmed'',''completed'')))\n      )) THEN 1 ELSE 0 END AS bad,\n      CASE WHEN c.data->>''source''=''circle-facilitator-success'' OR\n        (c.data->>''source''=''circle-transfer-search'' AND c.data->>''transferStatus'' IN (''confirmed'',''completed''))\n      THEN s.amount_micros ELSE 0 END AS settled\n    FROM public.private_treasury_reservations r JOIN public.private_creator_submissions s ON s.job_id=r.job_id\n    LEFT JOIN public.private_creator_confirmations c ON c.authorization_id=s.authorization_id WHERE r.signer=p_signer\n  ) SELECT p.capacity_micros::text,\n    COALESCE((SELECT SUM(r.amount_micros-COALESCE(x.amount_micros,0)) FROM public.private_treasury_reservations r\n      LEFT JOIN public.private_treasury_releases x ON x.job_id=r.job_id WHERE r.signer=p.signer),0)::text,\n    COALESCE((SELECT SUM(l.amount_micros) FROM legs l),0)::text,\n    COALESCE((SELECT SUM(l.settled) FROM legs l),0)::text,\n    COALESCE((SELECT SUM(l.bad) FROM legs l),0)::text\n    FROM public.private_treasury_pools p WHERE p.signer=p_signer;\nEND;\n","strict":false,"support":null,"volatility":"s"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',223,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_expected_identity jsonb, p_operation text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION keryx_storage.read_operation(p_expected_identity jsonb, p_operation text)\n RETURNS void\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare policy keryx_storage.operations%rowtype;\nbegin\n  perform keryx_storage.require_identity_read(p_expected_identity);\n  select * into policy from keryx_storage.operations where operation=p_operation;\n  if not found or not policy.read_only or (policy.real_only and p_expected_identity->>''authorityMode''<>''testnet-real'') then\n    raise exception ''storage readonly operation refused'';\n  end if;\nend; $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"read_operation","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"keryx_storage","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare policy keryx_storage.operations%rowtype;\nbegin\n  perform keryx_storage.require_identity_read(p_expected_identity);\n  select * into policy from keryx_storage.operations where operation=p_operation;\n  if not found or not policy.read_only or (policy.real_only and p_expected_identity->>''authorityMode''<>''testnet-real'') then\n    raise exception ''storage readonly operation refused'';\n  end if;\nend; ","strict":false,"support":null,"volatility":"s"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',224,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_key text, p_transient boolean, p_now bigint, p_threshold integer, p_base_cooldown_ms bigint, p_max_cooldown_ms bigint","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.record_reasoning_circuit_failure(p_key text, p_transient boolean, p_now bigint, p_threshold integer, p_base_cooldown_ms bigint, p_max_cooldown_ms bigint)\n RETURNS TABLE(failures integer, open_until bigint)\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare\n  v_previous integer;\n  v_failures integer;\n  v_exponent integer;\n  v_cooldown bigint;\n  v_open_until bigint;\nbegin\n  insert into public.reasoning_circuits\n    (key, failures, open_until, probe_until, updated_at)\n  values (p_key, 0, 0, 0, p_now)\n  on conflict (key) do nothing;\n\n  select rc.failures\n    into v_previous\n    from public.reasoning_circuits rc\n   where rc.key = p_key\n   for update;\n\n  if p_transient then\n    v_failures := v_previous + 1;\n  else\n    v_failures := greatest(v_previous + 1, p_threshold);\n  end if;\n  v_exponent := greatest(0, least(20, v_failures - p_threshold));\n  v_cooldown := least(\n    greatest(p_base_cooldown_ms, p_max_cooldown_ms),\n    p_base_cooldown_ms * (1::bigint << v_exponent)\n  );\n  v_open_until := case\n    when v_failures >= p_threshold then p_now + v_cooldown\n    else 0\n  end;\n\n  update public.reasoning_circuits\n     set failures = v_failures,\n         open_until = v_open_until,\n         probe_until = 0,\n         updated_at = p_now\n   where key = p_key;\n\n  return query select v_failures, v_open_until;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"record_reasoning_circuit_failure","owner":"postgres","parallel":"u","result":"TABLE(failures integer, open_until bigint)","returnsSet":true,"rows":"1000","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare\n  v_previous integer;\n  v_failures integer;\n  v_exponent integer;\n  v_cooldown bigint;\n  v_open_until bigint;\nbegin\n  insert into public.reasoning_circuits\n    (key, failures, open_until, probe_until, updated_at)\n  values (p_key, 0, 0, 0, p_now)\n  on conflict (key) do nothing;\n\n  select rc.failures\n    into v_previous\n    from public.reasoning_circuits rc\n   where rc.key = p_key\n   for update;\n\n  if p_transient then\n    v_failures := v_previous + 1;\n  else\n    v_failures := greatest(v_previous + 1, p_threshold);\n  end if;\n  v_exponent := greatest(0, least(20, v_failures - p_threshold));\n  v_cooldown := least(\n    greatest(p_base_cooldown_ms, p_max_cooldown_ms),\n    p_base_cooldown_ms * (1::bigint << v_exponent)\n  );\n  v_open_until := case\n    when v_failures >= p_threshold then p_now + v_cooldown\n    else 0\n  end;\n\n  update public.reasoning_circuits\n     set failures = v_failures,\n         open_until = v_open_until,\n         probe_until = 0,\n         updated_at = p_now\n   where key = p_key;\n\n  return query select v_failures, v_open_until;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',225,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.reject_browser_authorization_intent_change()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\nbegin\n  raise exception ''browser authorization intent is immutable'';\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"reject_browser_authorization_intent_change","owner":"postgres","parallel":"u","result":"trigger","returnsSet":false,"rows":"0","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\nbegin\n  raise exception ''browser authorization intent is immutable'';\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',226,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_epoch text, p_signer text, p_amount bigint","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.release_browser_journal_capacity(p_epoch text, p_signer text, p_amount bigint)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare n integer; v_spent bigint;\nbegin\n  update public.browser_retained_grants set spent_micro=spent_micro-p_amount where grant_epoch=p_epoch and signer=lower(p_signer) and spent_micro>=p_amount;\n  get diagnostics n=row_count; if n<>1 then raise exception ''Retained grant capacity mismatch''; end if;\n  update public.browser_signer_capacity set spent_micro=spent_micro-p_amount where signer=lower(p_signer) and spent_micro>=p_amount returning spent_micro into v_spent;\n  if not found then raise exception ''Signer capacity mismatch''; end if;\n  update public.session_grants set spent=v_spent::numeric/1000000 where lower(sess_addr)=lower(p_signer);\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"release_browser_journal_capacity","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare n integer; v_spent bigint;\nbegin\n  update public.browser_retained_grants set spent_micro=spent_micro-p_amount where grant_epoch=p_epoch and signer=lower(p_signer) and spent_micro>=p_amount;\n  get diagnostics n=row_count; if n<>1 then raise exception ''Retained grant capacity mismatch''; end if;\n  update public.browser_signer_capacity set spent_micro=spent_micro-p_amount where signer=lower(p_signer) and spent_micro>=p_amount returning spent_micro into v_spent;\n  if not found then raise exception ''Signer capacity mismatch''; end if;\n  update public.session_grants set spent=v_spent::numeric/1000000 where lower(sess_addr)=lower(p_signer);\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',227,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_address_key text, p_day_key text, p_amount numeric","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.release_onramp(p_address_key text, p_day_key text, p_amount numeric)\n RETURNS void\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare\n  v_total numeric;\nbegin\n  perform pg_advisory_xact_lock(hashtext(p_day_key));\n  delete from public.sync_state where key = p_address_key;\n  select coalesce(value::numeric, 0) into v_total\n    from public.sync_state where key = p_day_key;\n  update public.sync_state\n     set value = greatest(0, coalesce(v_total, 0) - p_amount)::text,\n         updated_at = now()\n   where key = p_day_key;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"release_onramp","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare\n  v_total numeric;\nbegin\n  perform pg_advisory_xact_lock(hashtext(p_day_key));\n  delete from public.sync_state where key = p_address_key;\n  select coalesce(value::numeric, 0) into v_total\n    from public.sync_state where key = p_day_key;\n  update public.sync_state\n     set value = greatest(0, coalesce(v_total, 0) - p_amount)::text,\n         updated_at = now()\n   where key = p_day_key;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',228,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_payer text, p_signer text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.release_private_treasury(p_id text, p_payer text, p_signer text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare budget bigint; used bigint; original bigint; n integer;\nbegin\n  -- Share the pool lock with new reservations. Result sealing and creator admission\n  -- already share the execution lock; use it here too to serialize the final snapshot.\n  perform signer from public.private_treasury_pools where signer=p_signer for update;\n  if not found then return false; end if;\n  select r.amount_micros into budget from public.private_treasury_reservations r\n    join public.private_research_intents i on i.id=r.job_id\n    join public.private_research_executions e on e.id=i.id\n    where r.job_id=p_id and r.signer=p_signer and i.payer=lower(p_payer) for update of e;\n  if not found then return false; end if;\n  if not exists(select 1 from public.private_research_results where id=p_id)\n    and not exists(select 1 from public.private_research_interruptions where id=p_id) then return false; end if;\n  if exists(select 1 from public.private_creator_submissions where job_id=p_id and (\n    (data#>>''{submission,payer}'') is distinct from p_signer or\n    (data#>>''{submission,amountMicros}'') is distinct from amount_micros::text\n  )) then raise exception ''private treasury release accounting mismatch''; end if;\n  select coalesce(sum(amount_micros),0) into used from public.private_creator_submissions where job_id=p_id;\n  if used > budget then raise exception ''private treasury release accounting mismatch''; end if;\n  insert into public.private_treasury_releases(job_id,amount_micros) values(p_id,budget-used) on conflict(job_id) do nothing;\n  get diagnostics n = row_count;\n  select amount_micros into original from public.private_treasury_releases where job_id=p_id;\n  if original <> budget-used then raise exception ''private treasury release accounting mismatch''; end if;\n  return n=1;\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"release_private_treasury","owner":"postgres","parallel":"u","result":"boolean","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare budget bigint; used bigint; original bigint; n integer;\nbegin\n  -- Share the pool lock with new reservations. Result sealing and creator admission\n  -- already share the execution lock; use it here too to serialize the final snapshot.\n  perform signer from public.private_treasury_pools where signer=p_signer for update;\n  if not found then return false; end if;\n  select r.amount_micros into budget from public.private_treasury_reservations r\n    join public.private_research_intents i on i.id=r.job_id\n    join public.private_research_executions e on e.id=i.id\n    where r.job_id=p_id and r.signer=p_signer and i.payer=lower(p_payer) for update of e;\n  if not found then return false; end if;\n  if not exists(select 1 from public.private_research_results where id=p_id)\n    and not exists(select 1 from public.private_research_interruptions where id=p_id) then return false; end if;\n  if exists(select 1 from public.private_creator_submissions where job_id=p_id and (\n    (data#>>''{submission,payer}'') is distinct from p_signer or\n    (data#>>''{submission,amountMicros}'') is distinct from amount_micros::text\n  )) then raise exception ''private treasury release accounting mismatch''; end if;\n  select coalesce(sum(amount_micros),0) into used from public.private_creator_submissions where job_id=p_id;\n  if used > budget then raise exception ''private treasury release accounting mismatch''