('after','functions',229,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_session_id text, p_grant_epoch text, p_sess_addr text, p_amount numeric","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.release_session_grant_spend(p_session_id text, p_grant_epoch text, p_sess_addr text, p_amount numeric)\n RETURNS void\n LANGUAGE sql\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\n  update public.session_grants\n     set spent = greatest(0, round(spent - p_amount, 6))\n   where session_id = p_session_id\n     and grant_epoch = p_grant_epoch\n     and lower(sess_addr) = lower(p_sess_addr);\n$function$\n","kind":"f","language":"sql","leakproof":false,"name":"release_session_grant_spend","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\n  update public.session_grants\n     set spent = greatest(0, round(spent - p_amount, 6))\n   where session_id = p_session_id\n     and grant_epoch = p_grant_epoch\n     and lower(sess_addr) = lower(p_sess_addr);\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
