('after','functions',234,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_address_key text, p_day_key text, p_amount numeric, p_daily_cap numeric, p_now bigint","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.reserve_onramp(p_address_key text, p_day_key text, p_amount numeric, p_daily_cap numeric, p_now bigint)\n RETURNS text\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare\n  v_total numeric;\nbegin\n  perform pg_advisory_xact_lock(hashtext(p_day_key));\n  if exists (select 1 from public.sync_state where key = p_address_key) then\n    return ''already-funded'';\n  end if;\n  select coalesce(value::numeric, 0) into v_total\n    from public.sync_state where key = p_day_key;\n  v_total := coalesce(v_total, 0);\n  if v_total + p_amount > p_daily_cap then\n    return ''daily-cap'';\n  end if;\n  insert into public.sync_state (key, value, updated_at)\n    values (p_address_key, p_now::text, now());\n  insert into public.sync_state (key, value, updated_at)\n    values (p_day_key, (v_total + p_amount)::text, now())\n    on conflict (key) do update\n      set value = excluded.value, updated_at = excluded.updated_at;\n  return ''reserved'';\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"reserve_onramp","owner":"postgres","parallel":"u","result":"text","returnsSet":false,"rows":"0","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare\n  v_total numeric;\nbegin\n  perform pg_advisory_xact_lock(hashtext(p_day_key));\n  if exists (select 1 from public.sync_state where key = p_address_key) then\n    return ''already-funded'';\n  end if;\n  select coalesce(value::numeric, 0) into v_total\n    from public.sync_state where key = p_day_key;\n  v_total := coalesce(v_total, 0);\n  if v_total + p_amount > p_daily_cap then\n    return ''daily-cap'';\n  end if;\n  insert into public.sync_state (key, value, updated_at)\n    values (p_address_key, p_now::text, now());\n  insert into public.sync_state (key, value, updated_at)\n    values (p_day_key, (v_total + p_amount)::text, now())\n    on conflict (key) do update\n      set value = excluded.value, updated_at = excluded.updated_at;\n  return ''reserved'';\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',235,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_payer text, p_signer text, p_capacity bigint","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.reserve_private_treasury(p_id text, p_payer text, p_signer text, p_capacity bigint)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare amount bigint; ceiling bigint; used bigint; original record;\nbegin\n  if p_signer is null or p_signer !~ ''^0x[a-f0-9]{40}$'' or p_signer = ''0x0000000000000000000000000000000000000000''\n    or p_capacity is null or p_capacity < 1 or p_capacity > 999999999999 then raise exception ''invalid capacity policy''; end if;\n  select round((data->''submission''->''request''->>''budget'')::numeric * 1000000)::bigint into amount\n    from public.private_research_intents where id=p_id and payer=lower(p_payer);\n  if not found then raise exception ''private intent unavailable''; end if;\n  insert into public.private_treasury_pools values(p_signer,p_capacity) on conflict(signer) do nothing;\n  select capacity_micros into ceiling from public.private_treasury_pools where signer=p_signer for update;\n  if ceiling <> p_capacity then raise exception ''capacity policy conflict''; end if;\n  select * into original from public.private_treasury_reservations where job_id=p_id;\n  if found then\n    if original.signer <> p_signer or original.amount_micros <> amount then raise exception ''reservation conflict''; end if;\n    return true;\n  end if;\n  select coalesce(sum(r.amount_micros-coalesce(x.amount_micros,0)),0) into used\n    from public.private_treasury_reservations r left join public.private_treasury_releases x on x.job_id=r.job_id where r.signer=p_signer;\n  if amount > ceiling-used then return false; end if;\n  insert into public.private_treasury_reservations values(p_id,p_signer,amount) on conflict(job_id) do nothing;\n  select * into original from public.private_treasury_reservations where job_id=p_id;\n  if original.signer <> p_signer or original.amount_micros <> amount then raise exception ''reservation conflict''; end if;\n  return true;\nend $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"reserve_private_treasury","owner":"postgres","parallel":"u","result":"boolean","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare amount bigint; ceiling bigint; used bigint; original record;\nbegin\n  if p_signer is null or p_signer !~ ''^0x[a-f0-9]{40}$'' or p_signer = ''0x0000000000000000000000000000000000000000''\n    or p_capacity is null or p_capacity < 1 or p_capacity > 999999999999 then raise exception ''invalid capacity policy''; end if;\n  select round((data->''submission''->''request''->>''budget'')::numeric * 1000000)::bigint into amount\n    from public.private_research_intents where id=p_id and payer=lower(p_payer);\n  if not found then raise exception ''private intent unavailable''; end if;\n  insert into public.private_treasury_pools values(p_signer,p_capacity) on conflict(signer) do nothing;\n  select capacity_micros into ceiling from public.private_treasury_pools where signer=p_signer for update;\n  if ceiling <> p_capacity then raise exception ''capacity policy conflict''; end if;\n  select * into original from public.private_treasury_reservations where job_id=p_id;\n  if found then\n    if original.signer <> p_signer or original.amount_micros <> amount then raise exception ''reservation conflict''; end if;\n    return true;\n  end if;\n  select coalesce(sum(r.amount_micros-coalesce(x.amount_micros,0)),0) into used\n    from public.private_treasury_reservations r left join public.private_treasury_releases x on x.job_id=r.job_id where r.signer=p_signer;\n  if amount > ceiling-used then return false; end if;\n  insert into public.private_treasury_reservations values(p_id,p_signer,amount) on conflict(job_id) do nothing;\n  select * into original from public.private_treasury_reservations where job_id=p_id;\n  if original.signer <> p_signer or original.amount_micros <> amount then raise exception ''reservation conflict''; end if;\n  return true;\nend ","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',236,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_session_id text, p_grant_epoch text, p_sess_addr text, p_amount numeric, p_now bigint","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.reserve_session_grant_spend(p_session_id text, p_grant_epoch text, p_sess_addr text, p_amount numeric, p_now bigint)\n RETURNS boolean\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare\n  updated integer;\nbegin\n  update public.session_grants\n     set spent = round(spent + p_amount, 6)\n   where session_id = p_session_id\n     and grant_epoch = p_grant_epoch\n     and lower(sess_addr) = lower(p_sess_addr)\n     and expiry > p_now\n     and round(spent + p_amount, 6) <= cap;\n  get diagnostics updated = row_count;\n  return updated > 0;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"reserve_session_grant_spend","owner":"postgres","parallel":"u","result":"boolean","returnsSet":false,"rows":"0","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare\n  updated integer;\nbegin\n  update public.session_grants\n     set spent = round(spent + p_amount, 6)\n   where session_id = p_session_id\n     and grant_epoch = p_grant_epoch\n     and lower(sess_addr) = lower(p_sess_addr)\n     and expiry > p_now\n     and round(spent + p_amount, 6) <= cap;\n  get diagnostics updated = row_count;\n  return updated > 0;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',237,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_outcome text, p_response jsonb, p_error_code text, p_resolution jsonb, p_started_before timestamp with time zone","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.resolve_a2a_order(p_id text, p_outcome text, p_response jsonb, p_error_code text, p_resolution jsonb, p_started_before timestamp with time zone DEFAULT NULL::timestamp with time zone)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\nDECLARE\n  changed integer;\n  evidence_attempts bigint;\n  evidence_settled bigint;\n  evidence_pending bigint;\n  evidence_failed bigint;\n  evidence_simulated bigint;\n  creator_cap bigint;\n  journal_version smallint;\n  payment_boundary_crossed boolean;\n  result_save_boundary_crossed boolean;\nBEGIN\n  IF p_resolution IS NULL OR jsonb_typeof(p_resolution) <> ''object'' THEN\n    RAISE EXCEPTION ''A2A resolution evidence is required'';\n  END IF;\n\n  SELECT COUNT(*),\n         COALESCE(SUM(CASE WHEN state=''settled'' THEN micros ELSE 0 END), 0),\n         COALESCE(SUM(CASE WHEN state=''pending'' THEN micros ELSE 0 END), 0),\n         COALESCE(SUM(CASE WHEN state=''failed'' THEN micros ELSE 0 END), 0),\n         COALESCE(SUM(CASE WHEN state=''simulated'' THEN micros ELSE 0 END), 0)\n    INTO evidence_attempts, evidence_settled, evidence_pending, evidence_failed, evidence_simulated\n    FROM (\n      SELECT ROUND(payments.amount_usdc * 1000000)::bigint AS micros,\n             COALESCE(\n               payments.settlement_status,\n               CASE WHEN payments.settled THEN ''settled'' ELSE ''simulated'' END\n             ) AS state\n        FROM public.payment_events AS payments\n       WHERE payments.query_id = (\n         SELECT orders.query_id FROM public.a2a_orders AS orders WHERE orders.id = p_id\n       )\n         AND payments.kind <> ''inbound''\n    ) AS creator_payments;\n  SELECT ROUND(orders.creator_budget_usdc * 1000000)::bigint,\n         orders.execution_journal_version,\n         orders.payment_started_at IS NOT NULL,\n         orders.result_saving_at IS NOT NULL\n    INTO creator_cap, journal_version, payment_boundary_crossed, result_save_boundary_crossed\n    FROM public.a2a_orders AS orders\n   WHERE orders.id = p_id;\n\n  IF evidence_attempts IS DISTINCT FROM\n       (p_resolution#>>''{evidence,creatorAttempts}'')::bigint\n     OR evidence_settled IS DISTINCT FROM\n       (p_resolution#>>''{evidence,settledCreatorMicros}'')::bigint\n     OR evidence_pending IS DISTINCT FROM\n       (p_resolution#>>''{evidence,pendingCreatorMicros}'')::bigint\n     OR evidence_failed IS DISTINCT FROM\n       (p_resolution#>>''{evidence,failedCreatorMicros}'')::bigint\n     OR evidence_simulated IS DISTINCT FROM\n       (p_resolution#>>''{evidence,simulatedCreatorMicros}'')::bigint\n     OR journal_version IS DISTINCT FROM\n       (p_resolution#>>''{evidence,executionJournalVersion}'')::smallint\n     OR payment_boundary_crossed IS DISTINCT FROM\n       (p_resolution#>>''{evidence,paymentBoundaryCrossed}'')::boolean\n     OR result_save_boundary_crossed IS DISTINCT FROM\n       (p_resolution#>>''{evidence,resultSaveBoundaryCrossed}'')::boolean\n     OR creator_cap IS NULL\n     OR evidence_settled + evidence_pending > creator_cap THEN\n    RETURN false;\n  END IF;\n\n  IF p_outcome = ''completed'' THEN\n    IF p_response IS NULL OR p_error_code IS NOT NULL\n       OR p_resolution->>''action'' <> ''repair_completed''\n       OR (p_resolution#>>''{evidence,queryRunFound}'')::boolean IS DISTINCT FROM true\n       OR evidence_simulated > 0 THEN\n      RAISE EXCEPTION ''invalid A2A completion resolution'';\n    END IF;\n    WITH live_evidence AS (\n      SELECT COUNT(*) AS attempts,\n             COALESCE(SUM(CASE WHEN state=''settled'' THEN micros ELSE 0 END), 0) AS settled,\n             COALESCE(SUM(CASE WHEN state=''pending'' THEN micros ELSE 0 END), 0) AS pending,\n             COALESCE(SUM(CASE WHEN state=''failed'' THEN micros ELSE 0 END), 0) AS failed,\n             COALESCE(SUM(CASE WHEN state=''simulated'' THEN micros ELSE 0 END), 0) AS simulated\n        FROM (\n          SELECT ROUND(payments.amount_usdc * 1000000)::bigint AS micros,\n                 COALESCE(\n                   payments.settlement_status,\n                   CASE WHEN payments.settled THEN ''settled'' ELSE ''simulated'' END\n                 ) AS state\n            FROM public.payment_events AS payments\n           WHERE payments.query_id = (\n             SELECT query_id FROM public.a2a_orders WHERE id = p_id\n           )\n             AND payments.kind <> ''inbound''\n        ) AS current_creator_payments\n    )\n    UPDATE public.a2a_orders AS orders\n       SET status = ''completed'',\n           response_data = p_response,\n           error_code = NULL,\n           resolution_data = p_resolution,\n           updated_at = (p_resolution->>''resolvedAt'')::timestamptz\n     WHERE orders.id = p_id\n       AND orders.status = ''running''\n       AND orders.started_at IS NOT NULL\n       AND EXISTS (\n         SELECT 1 FROM public.query_runs AS runs\n          WHERE runs.id = orders.query_id AND runs.payment_mode = ''real''\n       )\n       AND orders.execution_journal_version IS NOT DISTINCT FROM journal_version\n       AND (orders.payment_started_at IS NOT NULL) IS NOT DISTINCT FROM payment_boundary_crossed\n       AND (orders.result_saving_at IS NOT NULL) IS NOT DISTINCT FROM result_save_boundary_crossed\n       AND (SELECT attempts FROM live_evidence) = evidence_attempts\n       AND (SELECT settled FROM live_evidence) = evidence_settled\n       AND (SELECT pending FROM live_evidence) = evidence_pending\n       AND (SELECT failed FROM live_evidence) = evidence_failed\n       AND (SELECT simulated FROM live_evidence) = evidence_simulated;\n  ELSIF p_outcome = ''failed'' THEN\n    IF p_response IS NOT NULL OR p_error_code <> ''operator_reviewed_no_result''\n       OR p_started_before IS NULL OR p_resolution->>''action'' <> ''close_failed''\n       OR (p_resolution#>>''{evidence,queryRunFound}'')::boolean IS DISTINCT FROM false\n       OR journal_version IS DISTINCT FROM 1 OR payment_boundary_crossed\n       OR result_save_boundary_crossed\n       OR evidence_attempts > 0 THEN\n      RAISE EXCEPTION ''invalid A2A failure resolution'';\n    END IF;\n    UPDATE public.a2a_orders AS orders\n       SET status = ''failed'',\n           response_data = NULL,\n           error_code = p_error_code,\n           resolution_data = p_resolution,\n           updated_at = (p_resolution->>''resolvedAt'')::timestamptz\n     WHERE orders.id = p_id\n       AND orders.status = ''running''\n       AND orders.started_at IS NOT NULL\n       AND orders.started_at <= p_started_before\n       AND orders.execution_journal_version = 1\n       AND orders.payment_started_at IS NULL\n       AND orders.result_saving_at IS NULL\n       AND NOT EXISTS (\n         SELECT 1 FROM public.query_runs AS runs WHERE runs.id = orders.query_id\n       )\n       AND NOT EXISTS (\n         SELECT 1 FROM public.payment_events AS payments\n          WHERE payments.query_id = orders.query_id AND payments.kind <> ''inbound''\n       );\n  ELSE\n    RAISE EXCEPTION ''invalid A2A resolution outcome'';\n  END IF;\n\n  GET DIAGNOSTICS changed = ROW_COUNT;\n  RETURN changed = 1;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"resolve_a2a_order","owner":"postgres","parallel":"u","result":"boolean","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\nDECLARE\n  changed integer;\n  evidence_attempts bigint;\n  evidence_settled bigint;\n  evidence_pending bigint;\n  evidence_failed bigint;\n  evidence_simulated bigint;\n  creator_cap bigint