('after','functions',244,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_id text, p_nonce text, p_transfer_id text, p_mode text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.terminal_browser_journal(p_id text, p_nonce text, p_transfer_id text, p_mode text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare p public.payment_events%rowtype; v_signer text;\nbegin\n  if coalesce(p_mode,'''') not in (''settled'',''failed'',''cancelled_unexposed'') then raise exception ''Invalid journal terminal mode''; end if;\n  if p_mode<>''cancelled_unexposed'' and coalesce(length(p_transfer_id),0)=0 then raise exception ''Circle terminal proof identifier required''; end if;\n  -- Match lock order used by admission/recovery before touching payment and grant state.\n  select payer into v_signer from public.payment_events where id=p_id and authorization_id=p_nonce;\n  perform 1 from public.browser_signer_capacity where signer=lower(v_signer) for update;\n  select * into p from public.payment_events where id=p_id and authorization_id=p_nonce for update;\n  if not found or p.settlement_status is distinct from ''pending'' then return jsonb_build_object(''resolved'',false,''reservation_released'',false); end if;\n  if p.authorization_phase is null and p.grant_epoch is not null and not (select active from public.browser_journal_control where id=1) then\n    raise exception ''browser journal inactive'';\n  end if;\n  if p_mode=''cancelled_unexposed'' then\n    if p.authorization_phase is distinct from ''prepared'' then return jsonb_build_object(''resolved'',false,''reservation_released'',false); end if;\n  elsif p.authorization_phase is not null and p.authorization_phase not in (''exposed'',''signed'',''submission_attempted'') then\n    return jsonb_build_object(''resolved'',false,''reservation_released'',false);\n  end if;\n  insert into public.browser_journal_writer values(txid_current());\n  update public.payment_events set settlement_status=case when p_mode=''settled'' then ''settled'' else ''failed'' end,\n    settled=(p_mode=''settled''),tx_hash=p_transfer_id,authorization_phase=case when p.authorization_phase is null then null else p_mode end where id=p_id;\n  if p_mode<>''settled'' and p.grant_epoch is not null then\n    perform public.release_browser_journal_capacity(p.grant_epoch,p.payer,(p.amount_usdc*1000000)::bigint);\n  end if;\n  delete from public.browser_journal_writer where transaction_id=txid_current();\n  return jsonb_build_object(''resolved'',true,''reservation_released'',p_mode<>''settled'' and p.grant_epoch is not null);\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"terminal_browser_journal","owner":"postgres","parallel":"u","result":"jsonb","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare p public.payment_events%rowtype; v_signer text;\nbegin\n  if coalesce(p_mode,'''') not in (''settled'',''failed'',''cancelled_unexposed'') then raise exception ''Invalid journal terminal mode''; end if;\n  if p_mode<>''cancelled_unexposed'' and coalesce(length(p_transfer_id),0)=0 then raise exception ''Circle terminal proof identifier required''; end if;\n  -- Match lock order used by admission/recovery before touching payment and grant state.\n  select payer into v_signer from public.payment_events where id=p_id and authorization_id=p_nonce;\n  perform 1 from public.browser_signer_capacity where signer=lower(v_signer) for update;\n  select * into p from public.payment_events where id=p_id and authorization_id=p_nonce for update;\n  if not found or p.settlement_status is distinct from ''pending'' then return jsonb_build_object(''resolved'',false,''reservation_released'',false); end if;\n  if p.authorization_phase is null and p.grant_epoch is not null and not (select active from public.browser_journal_control where id=1) then\n    raise exception ''browser journal inactive'';\n  end if;\n  if p_mode=''cancelled_unexposed'' then\n    if p.authorization_phase is distinct from ''prepared'' then return jsonb_build_object(''resolved'',false,''reservation_released'',false); end if;\n  elsif p.authorization_phase is not null and p.authorization_phase not in (''exposed'',''signed'',''submission_attempted'') then\n    return jsonb_build_object(''resolved'',false,''reservation_released'',false);\n  end if;\n  insert into public.browser_journal_writer values(txid_current());\n  update public.payment_events set settlement_status=case when p_mode=''settled'' then ''settled'' else ''failed'' end,\n    settled=(p_mode=''settled''),tx_hash=p_transfer_id,authorization_phase=case when p.authorization_phase is null then null else p_mode end where id=p_id;\n  if p_mode<>''settled'' and p.grant_epoch is not null then\n    perform public.release_browser_journal_capacity(p.grant_epoch,p.payer,(p.amount_usdc*1000000)::bigint);\n  end if;\n  delete from public.browser_journal_writer where transaction_id=txid_current();\n  return jsonb_build_object(''resolved'',true,''reservation_released'',p_mode<>''settled'' and p.grant_epoch is not null);\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',245,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_session_id text, p_request_id text, p_from text, p_to text","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.transition_browser_journal(p_session_id text, p_request_id text, p_from text, p_to text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare n integer;\nbegin\n  if coalesce((p_from,p_to) in ((''prepared'',''exposed''),(''signed'',''submission_attempted'')),false) is distinct from true then raise exception ''Invalid journal transition''; end if;\n  insert into public.browser_journal_writer values(txid_current());\n  update public.payment_events p set authorization_phase=p_to from public.browser_authorization_intents i,public.browser_journal_bindings b\n    where i.session_id=p_session_id and i.request_id=p_request_id and b.nonce=i.nonce and p.id=''x402:''||i.nonce\n      and p.authorization_phase=p_from and p.settlement_status=''pending'';\n  get diagnostics n=row_count;\n  delete from public.browser_journal_writer where transaction_id=txid_current();\n  return n=1;\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"transition_browser_journal","owner":"postgres","parallel":"u","result":"boolean","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare n integer;\nbegin\n  if coalesce((p_from,p_to) in ((''prepared'',''exposed''),(''signed'',''submission_attempted'')),false) is distinct from true then raise exception ''Invalid journal transition''; end if;\n  insert into public.browser_journal_writer values(txid_current());\n  update public.payment_events p set authorization_phase=p_to from public.browser_authorization_intents i,public.browser_journal_bindings b\n    where i.session_id=p_session_id and i.request_id=p_request_id and b.nonce=i.nonce and p.id=''x402:''||i.nonce\n      and p.authorization_phase=p_from and p.settlement_status=''pending'';\n  get diagnostics n=row_count;\n  delete from public.browser_journal_writer where transaction_id=txid_current();\n  return n=1;\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',246,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_key_id text, p_day date","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.upsert_api_key_usage(p_key_id text, p_day date)\n RETURNS void\n LANGUAGE sql\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\n  INSERT INTO api_key_usage (key_id, day, call_count)\n  VALUES (p_key_id, p_day, 1)\n  ON CONFLICT (key_id, day) DO UPDATE SET call_count = api_key_usage.call_count + 1;\n$function$\n","kind":"f","language":"sql","leakproof":false,"name":"upsert_api_key_usage","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":false,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\n  INSERT INTO api_key_usage (key_id, day, call_count)\n  VALUES (p_key_id, p_day, 1)\n  ON CONFLICT (key_id, day) DO UPDATE SET call_count = api_key_usage.call_count + 1;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',247,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_grant jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION public.upsert_browser_journal_grant(p_grant jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public'', ''pg_temp''\nAS $function$\ndeclare v_signer text:=lower(p_grant->>''sess_addr''); v_spent bigint; v_cap numeric:=(p_grant->>''cap'')::numeric;\nbegin\n  if not (select active from public.browser_journal_control where id=1) then raise exception ''browser journal inactive''; end if;\n  if coalesce(v_signer ~ ''^0x[0-9a-f]{40}$'',false) is distinct from true\n     or v_cap is null or v_cap=''NaN''::numeric or v_cap<0 or v_cap*1000000<>trunc(v_cap*1000000) or v_cap*1000000>9007199254740991\n     or coalesce(length(p_grant->>''session_id''),0)=0 or coalesce(length(p_grant->>''grant_epoch''),0)=0 then raise exception ''Invalid grant capacity''; end if;\n  insert into public.browser_signer_capacity values(v_signer,0) on conflict do nothing;\n  select spent_micro into v_spent from public.browser_signer_capacity where signer=v_signer for update;\n  if v_spent>v_cap*1000000 then raise exception ''Session recovery cannot reset retained authorization capacity''; end if;\n  if exists(select 1 from public.browser_retained_grants where grant_epoch=p_grant->>''grant_epoch'') then raise exception ''Grant epoch already retained''; end if;\n  insert into public.browser_journal_writer values(txid_current());\n  insert into public.browser_retained_grants values(p_grant->>''grant_epoch'',p_grant->>''session_id'',v_signer,0);\n  insert into public.session_grants(session_id,sess_addr,owner_addr,cap,spent,expiry,tx_hash,grant_epoch)\n    values(p_grant->>''session_id'',v_signer,p_grant->>''owner_addr'',v_cap,v_spent::numeric/1000000,(p_grant->>''expiry'')::bigint,p_grant->>''tx_hash'',p_grant->>''grant_epoch'')\n    on conflict(session_id) do update set sess_addr=excluded.sess_addr,owner_addr=excluded.owner_addr,cap=excluded.cap,\n      spent=excluded.spent,expiry=excluded.expiry,tx_hash=excluded.tx_hash,grant_epoch=excluded.grant_epoch;\n  delete from public.browser_journal_writer where transaction_id=txid_current();\nend;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"upsert_browser_journal_grant","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"public","securityDefiner":true,"settings":["search_path=pg_catalog, public, pg_temp"],"source":"\ndeclare v_signer text:=lower(p_grant->>''sess_addr''); v_spent bigint; v_cap numeric:=(p_grant->>''cap'')::numeric;\nbegin\n  if not (select active from public.browser_journal_control where id=1) then raise exception ''browser journal inactive''; end if;\n  if coalesce(v_signer ~ ''^0x[0-9a-f]{40}$'',false) is distinct from true\n     or v_cap is null or v_cap=''NaN''::numeric or v_cap<0 or v_cap*1000000<>trunc(v_cap*1000000) or v_cap*1000000>9007199254740991\n     or coalesce(length(p_grant->>''session_id''),0)=0 or coalesce(length(p_grant->>''grant_epoch''),0)=0 then raise exception ''Invalid grant capacity''; end if;\n  insert into public.browser_signer_capacity values(v_signer,0) on conflict do nothing;\n  select spent_micro into v_spent from public.browser_signer_capacity where signer=v_signer for update;\n  if v_spent>v_cap*1000000 then raise exception ''Session recovery cannot reset retained authorization capacity''; end if;\n  if exists(select 1 from public.browser_retained_grants where grant_epoch=p_grant->>''grant_epoch'') then raise exception ''Grant epoch already retained''; end if;\n  insert into public.browser_journal_writer values(txid_current());\n  insert into public.browser_retained_grants values(p_grant->>''grant_epoch'',p_grant->>''session_id'',v_signer,0);\n  insert into public.session_grants(session_id,sess_addr,owner_addr,cap,spent,expiry,tx_hash,grant_epoch)\n    values(p_grant->>''session_id'',v_signer,p_grant->>''owner_addr'',v_cap,v_spent::numeric/1000000,(p_grant->>''expiry'')::bigint,p_grant->>''tx_hash'',p_grant->>''grant_epoch'')\n    on conflict(session_id) do update set sess_addr=excluded.sess_addr,owner_addr=excluded.owner_addr,cap=excluded.cap,\n      spent=excluded.spent,expiry=excluded.expiry,tx_hash=excluded.tx_hash,grant_epoch=excluded.grant_epoch;\n  delete from public.browser_journal_writer where transaction_id=txid_current();\nend;\n","strict":false,"support":null,"volatility":"v"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',248,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_source_id text, p_text text, p_identity jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION keryx_storage.validate_cache_wire(p_source_id text, p_text text, p_identity jsonb)\n RETURNS void\n LANGUAGE plpgsql\n IMMUTABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare wire text; decoded text; envelope jsonb; k text; field text; bytes bytea;\nbegin\n  if p_identity->>''authorityMode''=''testnet-offline'' then\n    if left(p_text,9)<>''plain:v1:'' or octet_length(p_text)>1048576+9 then raise exception ''storage cache format refused''; end if;\n    return;\n  end if;\n  if left(p_text,7)<>''enc:v3:'' or octet_length(p_text)>2097152 then raise exception ''storage cache format refused''; end if;\n  wire := substr(p_text,8);\n  if wire !~ ''^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$'' then raise exception ''storage cache format refused''; end if;\n  bytes := decode(wire,''base64'');\n  if replace(encode(bytes,''base64''),E''\\n'','''')<>wire then raise exception ''storage cache format refused''; end if;\n  decoded := convert_from(bytes,''UTF8''); envelope := decoded::jsonb;\n  if jsonb_typeof(envelope) is distinct from ''object''\n    or public.browser_signing_source_canonical(envelope)<>decoded\n    or (select array_agg(key order by key) from jsonb_object_keys(envelope) key)\n      is distinct from array[''authTagB64'',''cipherB64'',''format'',''ivB64'',''sourceId'',''storageIdentityDigest'',''wrapIvB64'',''wrappedKeyB64'']::text[]\n    or envelope->>''format''<>''keryx-enrolled-cache-v1'' or envelope->>''sourceId'' is distinct from p_source_id\n    or envelope->>''storageIdentityDigest'' is distinct from keryx_storage.identity_digest(p_identity) then\n    raise exception ''storage cache context refused'';\n  end if;\n  foreach k in array array[''format'',''sourceId'',''storageIdentityDigest'',''cipherB64'',''ivB64'',''authTagB64'',''wrappedKeyB64'',''wrapIvB64''] loop\n    if jsonb_typeof(envelope->k) is distinct from ''string'' then raise exception ''storage cache format refused''; end if;\n  end loop;\n  foreach k in array array[''cipherB64'',''ivB64'',''authTagB64'',''wrappedKeyB64'',''wrapIvB64''] loop\n    field := envelope->>k;\n    if field !~ ''^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$'' then raise exception ''storage cache format refused''; end if;\n    bytes := decode(field,''base64'');\n    if replace(encode(bytes,''base64''),E''\\n'','''')<>field or\n      (k=''cipherB64'' and octet_length(bytes)>1048576) or\n      (k in (''ivB64'',''wrapIvB64'') and octet_length(bytes)<>12) or\n      (k=''authTagB64'' and octet_length(bytes)<>16) or\n      (k=''wrappedKeyB64'' and octet_length(bytes)<>48) then raise exception ''storage cache format refused''; end if;\n  end loop;\nend; $function$\n","kind":"f","language":"plpgsql","leakproof":false,"name":"validate_cache_wire","owner":"postgres","parallel":"u","result":"void","returnsSet":false,"rows":"0","schema":"keryx_storage","securityDefiner":true,"settings":["search_path=pg_catalog, pg_temp"],"source":"\ndeclare wire text; decoded text; envelope jsonb; k text; field text; bytes bytea;\nbegin\n  if p_identity->>''authorityMode''=''testnet-offline'' then\n    if left(p_text,9)<>''plain:v1:'' or octet_length(p_text)>1048576+9 then raise exception ''storage cache format refused''; end if;\n    return;\n  end if;\n  if left(p_text,7)<>''enc:v3:'' or octet_length(p_text)>2097152 then raise exception ''storage cache format refused''; end if;\n  wire := substr(p_text,8);\n  if wire !~ ''^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$'' then raise exception ''storage cache format refused''; end if;\n  bytes := decode(wire,''base64'');\n  if replace(encode(bytes,''base64''),E''\\n'','''')<>wire then raise exception ''storage cache format refused''; end if;\n  decoded := convert_from(bytes,''UTF8''); envelope := decoded::jsonb;\n  if jsonb_typeof(envelope) is distinct from ''object''\n    or public.browser_signing_source_canonical(envelope)<>decoded\n    or (select array_agg(key order by key) from jsonb_object_keys(envelope) key)\n      is distinct from array[''authTagB64'',''cipherB64'',''format'',''ivB64'',''sourceId'',''storageIdentityDigest'',''wrapIvB64'',''wrappedKeyB64'']::text[]\n    or envelope->>''format''<>''keryx-enrolled-cache-v1'' or envelope->>''sourceId'' is distinct from p_source_id\n    or envelope->>''storageIdentityDigest'' is distinct from keryx_storage.identity_digest(p_identity) then\n    raise exception ''storage cache context refused'';\n  end if;\n  foreach k in array array[''format'',''sourceId'',''storageIdentityDigest'',''cipherB64'',''ivB64'',''authTagB64'',''wrappedKeyB64'',''wrapIvB64''] loop\n    if jsonb_typeof(envelope->k) is distinct from ''string'' then raise exception ''storage cache format refused''; end if;\n  end loop;\n  foreach k in array array[''cipherB64'',''ivB64'',''authTagB64'',''wrappedKeyB64'',''wrapIvB64''] loop\n    field := envelope->>k;\n    if field !~ ''^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$'' then raise exception ''storage cache format refused''; end if;\n    bytes := decode(field,''base64'');\n    if replace(encode(bytes,''base64''),E''\\n'','''')<>field or\n      (k=''cipherB64'' and octet_length(bytes)>1048576) or\n      (k in (''ivB64'',''wrapIvB64'') and octet_length(bytes)<>12) or\n      (k=''authTagB64'' and octet_length(bytes)<>16) or\n      (k=''wrappedKeyB64'' and octet_length(bytes)<>48) then raise exception ''storage cache format refused''; end if;\n  end loop;\nend; ","strict":false,"support":null,"volatility":"i"}'::jsonb,'e7b939bc1fc1bea83cca58f498acf48a0da1598b1a0857b0024d8917d3869774'),
('after','functions',249,'{"acl":{"explicit":true,"grants":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}]},"arguments":"p_identity jsonb","binary":null,"cost":"100","definition":"CREATE OR REPLACE FUNCTION keryx_storage.validate_identity(p_identity jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''pg_temp''\nAS $function$\ndeclare k text; keys text[];\nbegin\n  if p_identity is null or jsonb_typeof(p_identity) is distinct from ''object'' then\n    raise exception ''storage identity refused: invalid_identity'';\n  end if;\n  select array_agg(key order by key) into keys from jsonb_object_keys(p_identity) as key;\n  if keys is distinct from array[''authorityMode'',''deploymentId'',''enrolledAt'',''enrollmentId'',''format'',''network'',''profileDigest'',''provenanceDigest'',''storageId'']::text[] then\n    raise exception ''storage identity refused: invalid_identity'';\n  end if;\n  foreach k in array keys loop\n    if jsonb_typeof(p_identity->k) is distinct from ''string'' then raise exception ''storage identity refused: invalid_identity''; end if;\n  end loop;\n  if p_identity->>''format'' <> ''keryx-storage-identity-v1''\n    or p_identity->>''network'' <> ''eip155:5042002''\n    or p_identity->>''authorityMode'' not in (''testnet-real'',''testnet-offline'')\n    or p_identity->>''profileDigest'' <> ''1e6fc06a6668d1626af05d70e88a5df59eebdc67680aca58164cfc9f9c778d9c''\n    or p_identity->>''provenanceDigest'' !~ ''^[0-9a-f]{64}$''\n    or p_identity->>''enrolledAt'' !~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\\.[0-9]{3}Z$'' then\n    raise exception ''storage identity refused: invalid_identity'';\n  end if;\n  foreach k in array array[''deploymentId'',''storageId'',''enrollmentId''] loop\n    if p_identity->>k !~ ''^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'' then\n      raise exception ''storage identity refused: invalid_identity'';\n    